INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(301, 'koKR', 'Raport dla Żelaznej Kuźni', 'Żeby Ironband dostał więcej prochu strzelniczego, potrzebna nam zgoda z góry. Musisz zanieść jego raport do siedziby Ligi Odkrywców w Żelaznej Kuźni.$B$BOto raport. Oddaj go poszukiwaczowi Gromdardzie i nie zapomnij zrobić uniku, kiedy już go dostarczysz. Gromdarda to w gorącej wodzie kąpany krasnolud i nie ucieszy się, gdy usłyszy, jak wolno Ironbandowi idą prace na wykopaliskach.$B$BGromdardę znajdziesz w Zgromadzeniu Odkrywców.', 'Zanieś raport postępów Ironbanda poszukiwaczowi Gromdardzie.', '', '', '', '', '', '', 0),
(302, 'koKR', 'Proch dla Ironbanda', 'Jeśli Ironband nadal potrzebuje prochu, to na Magniego, dostanie go! Wysłałem już przodem gońca ze zgodą do Jerna Rogohełma w Thelsamarze. Przygotuje proch i inne zapasy dla Ironbanda.$B$BI jeszcze jedno: chcę, żebyś osobiście $gdopilnował:dopilnowała;, by transport prochu dotarł na miejsce. Poprzedni nie dotarł, więc miej się na baczności i patrz uważnie.', 'Porozmawiaj z Jernem Rogohełmem w Thelsamarze w Loch Modan.', '', '', '', '', '', '', 0),
(514, 'koKR', 'List do Gromdardy', 'Mam w Żelaznej Kuźni kolegę, który może pomóc odszyfrować ten list. Udaj się do biblioteki w Sali Odkrywców w Żelaznej Kuźni i porozmawiaj z poszukiwaczem Gromdardą. Powiedz mu, że to ja cię przysłałem, i pokaż mu list. Jeśli ktokolwiek na północ od Iglicy Czarnej Góry potrafi to odczytać, to właśnie on.', 'Zanieś sprytnie zaszyfrowany list poszukiwaczowi Gromdardzie w Żelaznej Kuźni.', '', '', '', '', '', '', 0),
(525, 'koKR', 'Kolejne zagadki', 'Odszyfrowałem list, ale nie wiem, co o nim myśleć. Mówisz, że $gznalazłeś:znalazłaś; go u złodziei na przedgórzu Alterak? Bardzo dziwne...$B$BZanieś to sędziemu w Południowym Brzegu. Choć list jest zagadkowy, jego miasto leży najbliżej Alterak – jeśli szykuje się jakieś zagrożenie, powinien o nim wiedzieć.', 'Zanieś odszyfrowany list sędziemu Malebowi w Południowym Brzegu.', '', '', '', '', '', '', 0),
(554, 'koKR', 'Odszyfrowanie Gromdardy', 'Poszukiwacz Gromdarda to mistrz rozszyfrowywania i odczytywania zagadkowych pism. Jeśli zaniesiesz mu pergamin, który $gznalazłeś:znalazłaś;, przy odrobinie szczęścia zdoła coś z niego wyczytać. Gromdarda prowadzi obecnie badania w siedzibie poszukiwaczy w Żelaznej Kuźni.$B$BA gdy go zobaczysz, powiedz mu, że $grozmawiałeś:rozmawiałaś; ze mną – ostatnio sporo zleceń mu podsyłam.', 'Zanieś zaczarowany pergamin poszukiwaczowi Gromdardzie w Żelaznej Kuźni.', '', '', '', '', '', '', 0),
(637, 'koKR', 'List Sully\'ego Balloo', 'Przemoczona i sfatygowana wojną koperta rozpada ci się w dłoniach, a zostaje w nich tylko kilka kartek listu, starannie i z wielkim trudem zapisanych.$b$bList jest zaadresowany do pani Sary Balloo z Żelaznej Kuźni i zaczyna się od słów: „Moja droga Saro...”.', 'Dostarcz list Sully\'ego Balloo Sarze Balloo.', '', '', '', '', '', '', 0),
(653, 'koKR', 'Sprzymierzeńcy Myzrael', '<Myzrael przemawia.>$B$BWolna! JESTEM WOLNA! Mogę teraz zbierać siły, ukryta przed moimi strażnikami. Gdyby bowiem stanęli ze mną do walki teraz, z pewnością by mnie pokonali i znów uwięzili.$B$BLecz w swoim czasie stawię czoła olbrzymom i pożałują, że trzymali mnie pod strażą!$B$BJesteś $gszlachetnym sprzymierzeńcem:szlachetną sprzymierzeńczynią;, $N. Z czasem znów będę potrzebować twojej pomocy. Gdy będę gotowa, $gbędziesz musiał:będziesz musiała; przyzwać mnie na powierzchnię.$B$BPorozmawiaj z Gerrigiem Kościochwytem. Jest w Żelaznej Kuźni, w sklepie w Opuszczonej Pieczarze. Wie, jak można mnie przyzwać.', 'Porozmawiaj z Gerrigiem Kościochwytem w Opuszczonej Pieczarze w Żelaznej Kuźni.', '', '', '', '', '', '', 0),
(683, 'koKR', 'Prośba Sary Balloo', '$N, mam do ciebie drobną prośbę.$b$bZanieś ten liścik, który przygotowałam, naszemu wielkiemu władcy Żelaznej Kuźni, królowi Magniemu Miedziobrodemu. To niewielka przysługa dla kogoś takiego jak ty, kto do tej pory wykazał się wielką odwagą w służbie Przymierza.$b$bGdybym to ja stanęła przed królem, pogrążona w takim żalu, nie przysłużyłabym się swojej sprawie. Na pewno to rozumiesz.', 'Zanieś liścik Sary Balloo królowi Magniemu Miedziobrodemu w Żelaznej Kuźni.', '', '', '', '', '', '', 0),
(686, 'koKR', 'Hołd króla', 'Nie oczekuję, że dobre krasnoludy, takie jak pani Balloo, zrozumieją, dlaczego dla większego dobra naszego ludu trzeba znosić okropieństwa wojny. Strata jej męża i każdego krasnoluda, który walczy w imię Przymierza, ciąży mi na duszy.$b$bNie mogę sprowadzić jej męża z powrotem z Wypaczonej Otchłani, ale mogę oddać mu hołd.$b$bZlecę wielkiemu murarzowi Marblestenowi wzniesienie pomnika ku czci Sully\'ego Balloo.$b$bZanieś mu tę wieść, $N. Powierzam ci wykonanie mojej woli.', 'Król Magni Miedziobrody chce, żebyś $gporozmawiał:porozmawiała; z wielkim murarzem Marblestenem.', '', '', '', '', '', '', 0),
(687, 'koKR', 'Theldurin Zagubiony', 'Theldurin Zagubiony był niegdyś członkiem naszego zakonu, Młota Zmierzchu. Postradał jednak zmysły i wzgardził naszymi naukami. A zanim od nas uciekł, ukradł zwój Myzrael! Nie zdołaliśmy go złapać, ale plotki głoszą, że ukrywa się na Bezludziu, bełkocząc jak szaleniec.$B$BAby przywrócić nam Panią, musisz odnaleźć zwój. A żeby to zrobić, musisz odnaleźć Theldurina.', 'Odnajdź Theldurina Zagubionego.', '', '', '', '', '', '', 0),
(689, 'koKR', 'Hołd króla', 'Nasz dobry król chce więc wznieść pomnik ku czci żołnierza imieniem Sully Balloo? I mówisz, że biedaczysko zginął w tragedii na Moście Thandol?$b$bEch, czy w Azeroth kiedykolwiek zapanuje pokój?$b$bTak czy inaczej, każde zlecenie od króla jest najwyższej wagi. Żeby stworzyć naprawdę wspaniałe i trwałe dzieło, chcę pracować z jednym z najlepszych kamieni, jakie można zdobyć. Udaj się na Wzgórze Darrow w Międzygórzu i przynieś mi trochę granitu z Alterak.', 'Wielki murarz Marblesten z Żelaznej Kuźni chce 5 bloków granitu z Alterak.', '', 'Wróć do wielkiego murarza Marblestena w Dun Morogh.', '', '', '', '', 0),
(700, 'koKR', 'Hołd króla', 'Ach, cóż za wspaniały kamień pochodzi z Lordaeronu. Szkoda, że ta kraina leży w takiej ruinie.$b$bAle pomnik wyszedł całkiem nieźle! Myślę, że król będzie z niego bardzo zadowolony.$b$bA teraz, jeśli łaska, zanieś Jego Królewskiej Mości wieść, że pomnik jest gotowy, tak jak sobie życzył.', 'Zamelduj się u króla Magniego Miedziobrodego.', '', '', '', '', '', '', 0),
(707, 'koKR', 'Ironband cię potrzebuje!', '$N. Dostałem meldunki od poszukiwacza Ironbanda z jego wykopalisk w Loch Modan – potrzebuje kogoś do trochę biegania w sprawie innych naszych wykopalisk.$B$BWięcej szczegółów nie znam, ale jeśli chcesz rozprostować nogi, idź porozmawiać z Ironbandem.', 'Porozmawiaj z poszukiwaczem Ironbandem na Wykopaliskach Ironbanda w Loch Modan.', '', '', '', '', '', '', 0),
(708, 'koKR', 'Czarna skrzynka', 'Powierzchnia tej metalowej czarnej skrzynki jest mocno pokryta wżerami, jakby zanurzono ją w kwasie – musiała długo leżeć w żołądku olbrzymiego kondora.$B$BPo odwróceniu skrzynki na jej dnie widać wybity symbol. Pod symbolem widnieją słowa:$B$B„Machina nr 19 – Brygada Oblężnicza Żelaznej Kuźni”', 'Zanieś skorodowaną czarną skrzynkę do Sali Oręża w Żelaznej Kuźni.', '', '', '', '', '', '', 0),
(723, 'koKR', 'Kwestia wiary', '<Młotopalcy przyciska dłonie do ran i przez chwilę zbiera siły, zanim znów się odezwie.>$B$BZnajdź Ryedola, $N. Zanieś mu mój amulet. <kaszel, kaszel> On... <kaszel> będzie wiedział, co robić. Wie, że szukałem korzeni naszego ludu, i wie... <kaszel>... że moim zadaniem było też powstrzymać klan Cienistej Kuźni. Nie wolno im pozwolić znaleźć tych zwojów... <kaszel>', 'Zanieś amulet Młotopalcego poszukiwaczowi Ryedolowi na Bezludziu.', '', '', '', '', '', '', 0),
(724, 'koKR', 'Kwestia wiary', 'Dobra, dobra... kto będzie wiedział, co robić?$B$BHistoryk Karnik! No jasne!$B$BJest w Żelaznej Kuźni. On pomoże. Razem z Młotopalcym szukali zaginionych artefaktów w Uldamanie.$B$BWidać Cienista Kuźnia się zwiedziała, że ci dwaj wiedzą więcej, niż mówią.$B$BPowiedz Karnikowi, co się stało z Młotopalcym, i daj mu amulet – on ci powie, co dalej.', 'Zanieś amulet Młotopalcego historykowi Karnikowi w Żelaznej Kuźni.', '', '', '', '', '', '', 0),
(725, 'koKR', 'Przekazanie wieści o zagrożeniu', '$N, biegnij jak najszybciej do doradcy Belgruma. Opowiedz mu, czego $gbyłeś:byłaś; świadkiem, i zapytaj, jak mamy postąpić. Ten liścik wyjaśni mu więcej.$B$BTymczasem ja spróbuję porozmawiać z duchem Młotopalcego. Może wie coś, co pomoże nam powstrzymać tych kretynów z Cienistej Kuźni na Bezludziu. Pozostaje nam się modlić.', 'Odnajdź doradcę Belgruma i daj mu liścik.', '', 'Zamelduj się u doradcy Belgruma w Żelaznej Kuźni.', '', '', '', '', 0),
(726, 'koKR', 'Przekazanie wieści o zagrożeniu', '<Doradca Belgrum dochodzi do końca liściku, a jego oczy na moment się rozszerzają.>$B$BOch, złe to wieści.$B$B$N, proszę, wróć do historyka Karnika i przekaż mu, że z upoważnienia króla ma działać na podstawie tych informacji szybko i zdecydowanie. Musi powstrzymać działania Cienistej Kuźni na Bezludziu.', 'Porozmawiaj z historykiem Karnikiem.', '', 'Porozmawiaj z historykiem Karnikiem w Żelaznej Kuźni.', '', '', '', '', 0),
(727, 'koKR', 'Do Żelaznej Kuźni po Kompendium Yagyina', 'Tablica mówi wiele. Ale nie dość! O wiele za mało!$B$BIstnieje księga, kompendium, które Yagyin spisał w dawnych wiekach. Ci... od których uciekłem... trzymają tę księgę w wielu miejscach. A ich najuczeńsi ją studiują. Kryje ogromną wiedzę. Wiedzę, która nas ochroni!$B$BIdź do Gerriga Kościochwyta. Ma sklep w Żelaznej Kuźni, w Opuszczonej Pieczarze. Pokaż mu ten symbol, a weźmie cię za jednego z nich. Poproś go o Kompendium Yagyina... i przynieś je mnie!', 'Daj Symbol Młota Gerrigowi Kościochwytowi w Opuszczonej Pieczarze w Żelaznej Kuźni.', '', '', '', '', '', '', 0),
(735, 'koKR', 'Gwiazda, dłoń i serce', 'Kompendium Yagyina, tak? Zakładasz gdzieś nowy oddział naszego zakonu? Mniejsza z tym, nie mnie o to pytać.$B$BPomogę ci, bo mam zapasowy egzemplarz. Musimy sobie pomagać, prawda? Tak właśnie rośniemy w siłę.$B$BPotrzebuję trzech przedmiotów mocy. Przynieś mi je, a dam ci kompendium.$B$BNie wypowiem ich nazw. Ktoś może podsłuchiwać. Ale proszę, zapiszę je.', 'Przynieś Gerrigowi Kościochwytowi w Żelaznej Kuźni przedmioty wymienione w liściku Kościochwyta.', '', 'Wróć do Gerriga Kościochwyta w Opuszczonej Pieczarze w Żelaznej Kuźni.', '', '', '', '', 0),
(736, 'koKR', 'Gwiazda, dłoń i serce', 'Potrzebujesz Kompendium Yagyina? A więc zamierzasz zebrać nowe stado? Oczywiście, że tak... i oczywiście, że ci pomogę, $gbracie:siostro;.$B$BAle ty też musisz mi pomóc.$B$BPotrzebuję trzech przedmiotów mocy. Przynieś mi je, a kompendium będzie twoje.$B$BNie mogę wypowiedzieć ich nazw, ale je zapiszę.$B$BZdobądź przedmioty z tej listy. Jeśli ci się to uda, naprawdę będziesz $ggodny:godna; założyć własny oddział naszego zakonu.', 'Przynieś przedmioty wymienione w Notatce Bel\'dugura Opiekunowi Bel\'dugurowi w Podmieście.', '', 'Wróć do Opiekuna Bel\'dugura nad Jeziorem Lordamere w Górach Alterak.', '', '', '', '', 0),
(737, 'koKR', 'Zakazana wiedza', 'Mam dla ciebie kompendium, $N. Nie muszę ci mówić, żebyś się z nim $gobchodził:obchodziła; ostrożnie. I $gtrzymał:trzymała; je z dala od nieprzyjaznych rąk.$B$BTa księga kryje wiele prawd...$B$B...a prawda potrafi parzyć.', 'Zanieś Kompendium Yagyina Theldurinowi.', '', '', '', '', '', '', 0),
(762, 'koKR', 'Ambasador zła', 'Ambasadora Infernusa wysłał do Fortecy Angor sam Ragnaros, by pilnował Cienistej Kuźni w poszukiwaniach zaginionych artefaktów w Uldamanie.$B$BJuż to kosztowało nasz lud ogromne straty, a sytuacja najwyraźniej się pogorszyła. Wolę nie zgadywać, ile artefaktów zdołaliby znaleźć i obrócić przeciwko Żelaznej Kuźni.$B$BNasz cel jest prosty, $N. Wróć na Bezludzie i zniszcz ambasadora Infernusa. Gdy zagrożenie zostanie zażegnane, wróć do doradcy Belgruma z dowodem zwycięstwa.$B$BTeraz wszystko w twoich rękach.', 'Zabij ambasadora Infernusa w Fortecy Angor i przynieś dowód jego śmierci doradcy Belgrumowi w Żelaznej Kuźni.', '', 'Wróć do doradcy Belgruma w Żelaznej Kuźni.', '', '', '', '', 0),
(968, 'koKR', 'Moce z głębin', 'Choć okładka jest mocno zniszczona i porysowana, wciąż da się odczytać tytuł księgi:$B$BMoce z głębin$B$BWewnątrz znajduje się spis niewymawialnych imion ze złowieszczymi tytułami, sposobów oddawania czci i ulubionych ofiar... wśród których wiele to żywe istoty humanoidalne.$B$BNa wewnętrznej stronie okładki widnieją słowa: „Runy i Zagłady Kościochwyta, Opuszczona Pieczara, Żelazna Kuźnia. Właściciel: Gerrig Kościochwyt”.$B$BSkoro Kościochwyt sprzedaje takie księgi, może odkupi tę.', 'Zanieś Księgę: Moce z głębin Gerrigowi Kościochwytowi w Opuszczonej Pieczarze w Żelaznej Kuźni.', '', '', '', '', '', '', 0),
(971, 'koKR', 'Wiedza w głębinach', 'Jak może wiesz, kolekcjonuję wiedzę. Dawną wiedzę. Potężną wiedzę. Wiedzę, która otwiera przejścia, i wiedzę, która może zbudzić Tych, Którzy Śpią.$B$BKrążą plotki o pewnym starym zapisie, Manuskrypcie Lorgalisa, spoczywającym na dnie Czarnych Głębin w Jesionowej Kniei. To dawne siedlisko dawno zmarłych elfów. Elfów, które posiadały wielką wiedzę, zanim ich miasto popadło w ruinę.$B$BPrzeszukaj Czarne Głębiny i znajdź manuskrypt. Zrób to, a nie zapomnę ci tego. Nawet po... dniach ostatecznych.', 'Przynieś Manuskrypt Lorgalisa Gerrigowi Kościochwytowi w Opuszczonej Pieczarze w Żelaznej Kuźni.', '', 'Wróć do Gerriga Kościochwyta w Dun Morogh.', '', '', '', '', 0),
(1050, 'koKR', 'Mitologia tytanów', 'Przyszłość jest nieunikniona! Pędzimy ku niej jak krople deszczu spadające do Wielkiego Morza.$b$bAle może, studiując przeszłość, dowiemy się, czego się spodziewać, i lepiej przygotujemy się na nieznane.$b$bZanim na Lordaeron spadły straszne nieszczęścia, na Polanach Tirisfal istniała ukryta ostoja wiedzy. Podobno w bibliotece starego klasztoru przechowywano księgę zatytułowaną „Mitologia tytanów”.$b$bPrzynieś mi ją, a może razem odkryjemy tajemnice przeszłości!', 'Odzyskaj „Mitologię tytanów” z klasztoru i przynieś ją bibliotekarce Mae Bladopył w Żelaznej Kuźni.', '', 'Wróć do bibliotekarki Mae Bladopył w Sali Odkrywców w Żelaznej Kuźni.', '', '', '', '', 0),
(1072, 'koKR', 'Stary kolega', 'Urządzenie, o którym myślę, to moja najbardziej zaawansowana wersja jak dotąd. Ale żeby zadziałało, potrzebujemy specjalnej mikstury. Skoro ta misja może być twoją ostatnią, równie dobrze możemy sięgnąć po najlepszy towar.$B$BA do tego będą nam potrzebne silne materiały wybuchowe: nitromirglicerynium.$B$BJedyny, kto potrafi zrobić NG-5, to mój stary przyjaciel: Lomac Zdzierotryb. Szukaj go w Majsterkowie.$B$BTy namówisz go, żeby zrobił nam trochę NG-5, a ja zabiorę się do rozmieszczania moich urządzeń.', 'Porozmawiaj z Lomakiem Zdzierotrybem w Żelaznej Kuźni.', '', '', '', '', '', '', 0),
(1073, 'koKR', 'Nieudolność + chemikalia = zabawa', 'Hahaha... potrzebujesz nitromirglicerynium, żeby powstrzymać gobliny przed zniszczeniem lasu?!$B$BNie obchodzi mnie, czy znasz Gaxima, czy nie... dam ci ten towar choćby po to, żeby zobaczyć, jak ty albo one wylatujecie w powietrze na malusieńkie kawałeczki.$B$BJest tylko jeden problem: skończył mi się.$B$BAle wiesz co? Przynieś mi odpowiednie mikstury, a od razu trochę dla ciebie zrobię.$B$BTo najmniej, co możesz zrobić: udowodnij, że masz jakieś pojęcie o alchemii, zanim po prostu dam ci próbkę mojego największego dzieła.', 'Przynieś 4 pomniejsze mikstury many i 2 eliksiry pomniejszej wytrwałości Lomacowi Zdzierotrybowi w Żelaznej Kuźni.', '', 'Wróć do Lomaca Zdzierotryba w Żelaznej Kuźni.', '', '', '', '', 0),
(1074, 'koKR', 'Nieudolność + chemikalia = zabawa', 'Proszę bardzo, $gnieznajomy:nieznajoma;. Tylko uważaj z tym... to lotny towar.$B$BJeśli naprawdę jesteś $gprzyjacielem:przyjaciółką; Gaxima, to go ode mnie pozdrów. A jeśli nie, to baw się dobrze, wysadzając się w powietrze.', 'Zanieś nitromirglicerynium Gaximowi Rdzawosykowi w Górach Szponogłazach.', '', '', '', '', '', '', 0),
(1139, 'koKR', 'Zaginione tablice woli', 'Spowolniliśmy klan Cienistej Kuźni, odcinając go od Iglicy Czarnej Góry, ale misja Młotopalcego wciąż nie została wypełniona. Jego śmierć nie może pójść na marne. Marzył o odnalezieniu Tablicy woli: kamiennego odłamka, na którym sami tytani wyryli magię, by tchnąć życie w swoje dzieła – by miały własną wolę, a przynajmniej tak głoszą legendy.$B$BMusimy odzyskać Tablicę, zanim znajdzie ją klan Cienistej Kuźni.$B$BWróć do Uldamanu, znajdź tablicę i natychmiast wracaj tutaj.', 'Znajdź Tablicę woli i zanieś ją doradcy Belgrumowi w Żelaznej Kuźni.', '', 'Wróć do doradcy Belgruma w Żelaznej Kuźni.', '', '', '', '', 0),
(1179, 'koKR', 'Bracia Mosiężnośrubowie', '$GSłyszałeś:Słyszałaś; kiedyś o Migoczących Równinach? To połać solnisk daleko w Kalimdorze, na południe od kanionu Tysiąca Filarów. Świetne miejsce na wyścigi, bo, no cóż, jest tam tak płasko!$B$BJest tam dwóch braci gnomów, moich przyjaciół, którzy testują swój nowy samochód rakietowy, a z tego, co słyszę, jest szybki! Heh, tak szybki, że ich kierowcy ciągle się rozbijają. I nabijają sobie wstrząśnienia mózgu.$B$BPoprosili mnie więc o kaski pilotów machin oblężniczych, ale mam tu swoje obowiązki. Nie mogę się tam wybrać!$B$BA ty możesz?', 'Zanieś skrzynię kasków ochronnych Wizzle\'owi Mosiężnośrubowi na Torze Wyścigowym Miraż w Tysiącu Filarów.', '', '', '', '', '', '', 0),
(1360, 'koKR', 'Odzyskane skarby', 'Miałem porządną robotę jako kopacz na wykopaliskach w Uldamanie na Bezludziu... dopóki nie zjawiły się te przeklęte troggi. Uszedłem ledwie z całą skórą i niczym więcej. W zamieszaniu zostawiłem mój największy skarb. W skrzyni jest bezpieczny przed troggami, to pewne, ale leży w samym ich środku.$B$BBędę twoim dłużnikiem, i co do honoru, i co do grosza, jeśli mi go przyniesiesz! Skrzynia z moim imieniem stoi na końcu Północnej Sali Wspólnej. To do niej musisz się dostać.', 'Wydobądź cenny skarb Kroma Krzepkorękiego z jego skrzyni w Północnej Sali Wspólnej Uldamanu i przynieś mu go do Żelaznej Kuźni.', '', 'Wróć do Kroma Krzepkorękiego w Dun Morogh.', '', '', '', '', 0),
(1453, 'koKR', 'Interesy Odzyskiwaczy w Mrocznym Pustkowiu', 'W Mrocznym Pustkowiu jest robota do zrobienia, $N. To okropne miejsce, zapaskudzone przez centaury i inne paskudztwa. Ale jeśli szukasz porządnej, uczciwej roboty na tydzień, ruszaj tam, spotkaj się z Kreldigiem Ungorem i powiedz mu, że to ja cię przysłałem.$B$BZnajdziesz go zaszytego w Punkcie Nijela – to mały, przytulny obóz ukryty w górach północnego Mrocznego Pustkowia. Jeśli wejdziesz od strony Gór Szponogłazów, kieruj się po prostu na wschód. Łatwo go przeoczyć, więc miej oczy otwarte.', 'Porozmawiaj z Kreldigiem Ungorem w Punkcie Nijela w Mrocznym Pustkowiu.', '', '', '', '', '', '', 0),
(1457, 'koKR', 'Wrak statku Karnitola', 'Zanieś rzeczy Karnitola Roettenowi w Żelaznej Kuźni, a on zapłaci ci za dobrze wykonaną robotę.$B$BHaha, jeśli nie będziesz $guważał:uważała;, będzie z ciebie tak zadowolony, że zaproponuje ci stałą robotę u nas.$B$BJeszcze raz: świetna robota, $N.$B$BUważaj w drodze powrotnej i nie zwlekaj za długo – Karnitol nie należy do najcierpliwszych ludzi, ale mimo to jest bardzo hojny.', 'Zanieś torbę Karnitola Roettenowi Kamiennomłotowi w Żelaznej Kuźni.', '', '', '', '', '', '', 0),
(1467, 'koKR', 'Składniki dla Odzyskiwaczy sp. z o.o.', 'Żeby dostać zapłatę, musisz wrócić do Żelaznej Kuźni i porozmawiać z samym Roettenem. I tak ucieszy się, że paczkę Leftwitcha ma już z głowy. Daj mu tylko to, a powinno wystarczyć, żebyś $godebrał:odebrała; swój łup.$B$BI nie martw się, jak wrócę, wstawię się za tobą. Długo już w Mrocznym Pustkowiu nie zabawię.', 'Zanieś paczkę Leftwitcha Roettenowi Kamiennomłotowi w Żelaznej Kuźni.', '', '', '', '', '', '', 0),
(1578, 'koKR', 'Zaopatrzenie dla frontu', 'Górscy strażnicy z Loch Modan walczą z troggami i mają pełne ręce roboty! Jeśli kiedykolwiek mamy zapanować nad troggami, muszą stale dostawać nowe zbroje i broń.$B$BDlatego jest tam mój kolega Thorvald – dba o to, żeby górscy strażnicy mieli porządny sprzęt. Jeśli więc wykujesz kilka miedzianych toporów i miedzianych kolczych pasów i zaniesiesz je Thorvaldowi, będzie ci wdzięczny. Może nawet podzieli się z tobą swoją wiedzą.$B$BThorvald jest w południowej wieży strażniczej w Loch Modan.', 'Zanieś 6 miedzianych toporów i 6 miedzianych kolczych pasów Thorvaldowi w południowej wieży strażniczej w Loch Modan.', '', 'Wróć do Thorvalda Głębokucia na Przełęczy Północnej Bramy w Dun Morogh.', '', '', '', '', 0),
(1618, 'koKR', 'Sprzęt dla Rudej Grani', 'Nie tylko my, krasnoludy, walczymy. Nasi ludzcy sojusznicy też mają pełne ręce roboty!$B$BRuda Grań jest co jakiś czas atakowana przez orków z Czarnej Skały, a zapasy sprzętu zawsze są tam na wyczerpaniu. Jeśli im pomożesz, jestem pewien, że tamtejszy kowal, Verner Osgood, nauczy cię paru sztuczek.', 'Tormus Głębokuć chce, żebyś $gzaniósł:zaniosła; 4 runiczne miedziane pasy i 4 ciężkie miedziane młoty Vernerowi Osgoodowi w Rudej Grani.', '', 'Porozmawiaj z Vernerem Osgoodem w Jeziernych Włościach w Górach Rudej Grani.', '', '', '', '', 0),
(1654, 'koKR', 'Próba prawości', 'Chciałbym cię nagrodzić, jeśli zechcesz przyjąć coś takiego. Nie zrozum mnie źle, moja hojność zależy od tego, jak bardzo zdołasz mi pomóc, ale widzę, że obie strony wiele zyskają na takim sojuszu.$B$BWykuję dla ciebie broń godną twoich dokonań, symbol paladyńskiego powołania i Światłości, ale musisz zebrać przedmioty, których potrzebuję do jej wykonania. Zacząłem już robić notatki o tych przedmiotach; potrzeba tylko kogoś dość odważnego i zręcznego, by je zdobył. Co ty na to, $N?', 'Korzystając z notatek Jordana o broni, zdobądź drewno białokamiennego dębu, przesyłkę oczyszczonej rudy Bailora, kowalski młot Jordana oraz klejnot Kor i zanieś je Jordanowi Stilwellowi w Żelaznej Kuźni.', '', 'Wróć do Jordana Stilwella u Wrót Żelaznej Kuźni w Dun Morogh.', '', '', '', '', 0),
(1678, 'koKR', 'Vejrek', 'Jeśli chcesz awansować w szeregach wojowników, lepiej bądź $gtwardy:twarda;. Mogę cię nauczyć nowych ruchów, ale najpierw udowodnij mi, że potrafisz poradzić sobie z prawdziwymi wrogami.$B$BVejrek to najtwardszy troll w tych stronach i właśnie jego musisz pokonać. Ma chatę na pogórzu tuż na południe od Warowni Mroźnych Grzyw.$B$BPrzynieś mi głowę Vejreka, a będę wiedział, że masz charakter.', 'Przynieś głowę Vejreka Murenowi Gromdardzie w Żelaznej Kuźni.', '', 'Wróć do Murena Gromdardy w Dun Morogh.', '', '', '', '', 0),
(1680, 'koKR', 'Tormus Głębokuć', 'Skoro już $gnauczyłeś:nauczyłaś; się kilku ruchów, czas zdobyć dla ciebie porządną broń. Porozmawiaj z Tormusem Głębokuciem. On wykuje ci broń, która na pewno ci się spodoba.$B$BTormusa znajdziesz tutaj, w Żelaznej Kuźni, przy Wielkiej Kuźni.', 'Porozmawiaj z Tormusem Głębokuciem.', '', '', '', '', '', '', 0),
(1681, 'koKR', 'Siedlisko Ironbanda', 'Mój mistrz, Sturgy Ironband, miał siedlisko na południe od Jeziora Łoża Helma we wschodnim Dun Morogh. Uczył tam kowalstwa i był najlepszy.$B$BAle pewnego dnia jeden z jego uczniów przyniósł mu ładunek dziwnej rudy. Mistrz Ironband nazwał ją mroczną rudą i palił się do pracy z nią, ale wkrótce po jej przybyciu... jego siedlisko zaatakowała banda krasnoludów z klanu Czarnorytych. Zabili wszystkich!$B$BWejdź do Siedliska Ironbanda, $N, i pomścij śmierć mojego mistrza. I przynieś mi ładunek mrocznej rudy, który ją sprowadził.', 'Przynieś ładunek mrocznej rudy Tormusowi Głębokuciowi w Żelaznej Kuźni.', '', 'Wróć do Tormusa Głębokucia w Dun Morogh.', '', '', '', '', 0),
(1682, 'koKR', 'Broń z szarego żelaza', '', '', '', '', '', '', '', '', 0),
(1708, 'koKR', 'Żelazny koral', 'Chcę wypróbować nowe techniki Furena Długobrodego na własnym pancerzu. A że ty $gpomogłeś:pomogłaś; Furenowi, a on pomógł mnie, pancerz będzie twój, kiedy go skończę!$B$BŻeby go dokończyć, potrzebuję specjalnego korala – parzącego korala. Rośnie tylko w jednym miejscu: wzdłuż wybrzeża na południe od Przystani Menethilów na Bagniskach.$B$BPrzynieś mi dość parzącego korala, a od razu wezmę się do pracy nad pancerzem. I pospiesz się, $N. Tak mi pilno zaczynać, że aż mi się palce u stóp skręcają!', 'Przynieś 20 ładunków parzącego korala Klockmortowi Kluczokrętowi w Żelaznej Kuźni.', '', 'Wróć do Klockmorta Kluczokręta w Dun Morogh.', '', '', '', '', 0),
(1709, 'koKR', 'Dzieło Klockmorta', '', '', '', '', '', '', '', '', 0),
(1758, 'koKR', 'Księga Sprzysiężenia', 'Zwykły krąg przywołania nie wystarczy, by sprowadzić łowcę spaczenia, z którym się zmierzysz.$b$bMoi trzej akolici i ja pomożemy stworzyć magiczne kręgi. Potrzebujesz egzemplarza Księgi Sprzysiężenia, która od dawna uchodzi za zaginioną. Spisała ją pierwsza grupa czarnoksiężników, którzy przywołali łowcę spaczenia bez niczyjej pomocy.$b$bByć może pomoże ci w tym Krom Krzepkoręki. Jest teraz wędrownym czarnoksiężnikiem, a dnie spędza na gromadzeniu starożytnych tekstów i przemykaniu po bibliotece w Żelaznej Kuźni.', 'Porozmawiaj z Kromem Krzepkorękim w Żelaznej Kuźni.', '', '', '', '', '', '', 0),
(1801, 'koKR', 'Księga Sprzysiężenia', 'Zwykły krąg przywołań nie wystarczy, by sprowadzić łowcę spaczenia, z którym się zmierzysz.$b$bMoi trzej akolici i ja pomożemy stworzyć magiczne kręgi. Potrzebujesz egzemplarza Księgi Sprzysiężenia, która od dawna uchodzi za zaginioną. Spisała ją pierwsza grupa czarnoksiężników, którzy przywołali łowcę spaczenia bez niczyjej pomocy.$b$bByć może pomoże ci w tym Jorah Annison. Pracuje teraz jako kartograf w Podmieście, ale wciąż zna się na starożytnych tekstach lepiej niż ktokolwiek, kogo znam.', 'Porozmawiaj z Jorahem Annisonem w Podmieście.', '', '', '', '', '', '', 0),
(1802, 'koKR', 'Księga Sprzysiężenia', 'Zaginęła, ale co nieco wiadomo o tym, gdzie można by jej szukać.$b$bSporządzono tylko jeden egzemplarz, a w pewnym momencie ktoś go zniszczył, wyrywając z oprawy sporą część kartek. Wieść niesie, że ta część jakimś sposobem trafiła w ręce centaurów z Tysiąca Filarów.$b$bReszta przepadła u wybrzeża na zachód od Południowego Brzegu, skąd miała zostać przewieziona łodzią do Przystani Menethilów. Nigdy tam nie dotarła.$b$bW zamian za tę wiedzę proszę tylko o jedno: jeśli ją odnajdziesz, przynieś mi ją, żebym mógł ją obejrzeć.', 'Zdobądź spleśniałą księgę i podarty manuskrypt dla Kroma Krzepkorękiego w Żelaznej Kuźni.', '', 'Wróć do Kroma Krzepkorękiego w Dun Morogh.', '', '', '', '', 0),
(1803, 'koKR', 'Księga Sprzysiężenia', 'Ach! Widzę, że jesteś $gczarnoksiężnikiem:czarnoksiężniczką; o gustach podobnych do moich. Zdobycie Księgi Sprzysiężenia to istotnie godny cel. Czy wiesz, że niegdyś przechowywano ją w murach Lordaeronu? Została jednak zbezczeszczona – wyrwano z niej prawie połowę stron. Kto dopuściłby się tak haniebnego czynu?$b$bTamta połowa przepadła, choć plotka głosi, że trafiła w ręce centaurów z Tysiąca Filarów.$b$bResztę tekstu miano przewieźć do Żelaznej Kuźni, ale zaginęła w drodze na wybrzeżu na zachód od Południowego Brzegu.', 'Zdobądź Spleśniałą księgę i Podarty manuskrypt dla Joraha Annisona w Podmieście.', '', 'Wróć do Joraha Annisona na Polanach Tirisfal.', '', '', '', '', 0),
(1804, 'koKR', 'Księga Sprzysiężenia', 'No cóż, trudno mi się z nią rozstać. Ale to ty ją $gznalazłeś:znalazłaś; i masz z nią do zrobienia ważniejsze rzeczy, rzecz jasna. Tylko, proszę, nie zapomnij wspomnieć Strahadowi, że chciałem kopię.$b$bPod twoją nieobecność przysłał dla ciebie wiadomość. Prosił, żebym ci przekazał, że aby jego akolici mogli pomóc w przywołaniu, musisz zdobyć trzy pręty kanalizowania.$b$bOn może nie wiedzieć, gdzie ich szukać, ale ja wiem! Ostatnio używały ich orki z klanu Smoczych Paszcz na Bagniskach. Sprawdziłbym ich czarowników!', 'Przynieś odtworzoną księgę i 3 pręty kanalizowania Strahadowi Farsanowi w Zapadce.', '', '', '', '', '', '', 0),
(1805, 'koKR', 'Księga Sprzysiężenia', 'To jeden z najciekawszych tekstów, jakie przeglądałem w ostatnich latach. Wybór mam tu skromny – głównie książki o geografii – i przeczytałem już wszystkie. Mam nadzieję, że Strahad przyśle mi kopię tej księgi, kiedy będzie miał okazję.$b$bSkoro o nim mowa, przysłał mi wiadomość, gdy cię nie było. Do swojego zadania musisz zdobyć trzy pręty kanalizowania.$b$bW zamian za to, że $gpozwoliłeś:pozwoliłaś; mi zajrzeć do tego tekstu, zdradzę ci sekret: pręty znajdziesz przy orkach z klanu Smoczych Paszcz na Bagniskach.', 'Przynieś odtworzoną księgę i 3 pręty kanalizowania Strahadowi Farsanowi w Zapadce.', '', '', '', '', '', '', 0),
(1806, 'koKR', 'Próba prawości', 'Może pójdziemy do kuźni i zaczniemy? Od dawna szykowałem się na twoje przybycie, więc nie powinno to długo potrwać.$B$BKiedy skończymy, będziesz o wiele lepiej $gprzygotowany:przygotowana; do obrony Światłości niż dotąd, na to przysięgam.$B$BPowiem szczerze, $N, gdy widzę owoce twoich wyczynów, trochę ci zazdroszczę. Ale świadomość, że mogę na swój sposób wnieść coś ważnego do twoich przygód, sprawia mi radość.', 'Zaczekaj, aż Jordan Stilwell skończy wykuwać dla ciebie broń.', '', '', '', '', '', '', 0),
(1880, 'koKR', 'Magofantastyczny gadżetometr', 'My, magowie, robimy coś więcej, niż tylko machamy palcami i sypiemy ładnymi iskrami! Panujemy nad magią, podstawową tkanką naszego świata! A to wymaga wielkiej ostrożności i determinacji. I wiedzy... tyle wiedzy!$B$BJedno z moich urządzeń, magofantastyczny gadżetometr, gromadzi i przechowuje tę wiedzę w ogromnych ilościach! Ale przepadł! Kiedy uciekaliśmy z naszego domu, Gnomoregan, zostawiłam go w skrzyni w jednej z naszych chat pod miastem, a teraz roi się tam od trędowatych gnomów!$B$BProszę, $N, odzyskaj mój gadżetometr!', 'Przynieś Bink jej magofantastyczny gadżetometr.', '', 'Wróć do Bink w Dun Morogh.', '', '', '', '', 0),
(2039, 'koKR', 'Odnajdź Binglesa', 'Straciliśmy kontakt z Binglesem! Wysłano go na zwiad nad Gnomoregan i od ponad tygodnia się nie zameldował. Jestem pewien, że wysadził się w powietrze.$B$BOstatnio widziano go, jak leciał nad Loch Modan. Może ty to zbadasz, $N.', 'Odnajdź Binglesa Blastenheimera w Loch Modan.', '', '', '', '', '', '', 0),
(2198, 'koKR', 'Strzaskany naszyjnik', '$GZnalazłeś:Znalazłaś; zmatowiały naszyjnik, choć pod nalotem kryje się misterna, magiczna robota. Naszyjnik jest strzaskany – w oprawie brakuje trzech klejnotów. Na spodzie widnieje słaby odcisk pieczęci miejskiej Żelaznej Kuźni. Pod pieczęcią wygrawerowano trzy maleńkie litery: „TdK”.$B$BJeśli z naszyjnika da się cokolwiek wyczytać, trzeba poznać jego pochodzenie. Może pieczęć i inicjały to dobry początek...', 'Odszukaj twórcę strzaskanego naszyjnika, by dowiedzieć się, ile może być wart.', '', '', '', '', '', '', 0),
(2199, 'koKR', 'Wiedza ma swoją cenę', 'Jestem jubilerem o wielkiej renomie tu, w Żelaznej Kuźni! No, o dawnej renomie... Popadłem w tarapaty przez szachrajstwa pewnego konkurenta! W tej branży zła reputacja oznacza finansową katastrofę. W rezultacie nie mam złamanego miedziaka, a moje dobre imię jest – przynajmniej na razie – zszargane.$B$BPotrzebuję pięciu sztabek srebra, żeby dokończyć zamówienie – pierwsze od, zdawałoby się, całej wieczności.$B$BZdobądź mi te pięć sztabek srebra, a odpowiem na twoje pytania o naszyjnik.', 'Przynieś pięć sztabek srebra Talvashowi del Kisselowi w Żelaznej Kuźni.', '', 'Wróć do Talvasha del Kissela w Dzielnicy Mistycznej w Żelaznej Kuźni.', '', '', '', '', 0),
(2200, 'koKR', 'Powrót do Uldamanu', 'Jeden z moich konkurentów puścił plotkę, że mój naszyjnik przeklął tego paladyna. Nie trzeba chyba mówić, że nikt nie chce kupować od jubilera przeklętych przedmiotów.$B$B$N, proponuję ci układ: znajdź klejnoty, a ja złożę naszyjnik z powrotem, pod warunkiem że będziesz rozgłaszać, że NIE robię przeklętych przedmiotów!$B$BPoszukaj wskazówek w Uldamanie; sprawdź, czy nie leży tam ciało paladyna, bo wiemy, że to on miał naszyjnik ostatni! Kiedy znajdziesz klejnoty, użyj tego – dzięki temu skontaktujesz się ze mną tu, w Żelaznej Kuźni.', 'Poszukaj w Uldamanie wskazówek, co się obecnie dzieje z naszyjnikiem Talvasha. Zabity paladyn, o którym wspomniał, był ostatnią osobą, która go miała.', '', '', '', '', '', '', 0),
(2201, 'koKR', 'Znajdź klejnoty', 'Dziennik paladyna dostarczył być może jedynych wskazówek, jakie Uldaman może dać co do położenia klejnotów z naszyjnika. Jeśli zapiski paladyna wciąż są aktualne, trzeba będzie rozprawić się z krasnoludami z Cienistej Kuźni i troggami, które walczą o panowanie nad wykopaliskami.$B$BZ tą wiedzą można na dobre rozpocząć poszukiwania klejnotów. Gdy wszystkie zostaną zdobyte, należy zgodnie z instrukcjami powiadomić Talvasha w Żelaznej Kuźni za pomocą wróżebnej fiolki.', 'Znajdź rubin, szafir i topaz rozrzucone po Uldamanie. Gdy je zdobędziesz, skontaktuj się na odległość z Talvashem del Kisselem, używając wróżebnej fiolki, którą ci wcześniej dał.$B$BZ dziennika wiesz, że...$B* Rubin ukryto na zabarykadowanym terenie Cienistej Kuźni.$B* Topaz schowano w urnie na jednym z terenów troggów, w pobliżu krasnoludów z Przymierza.$B$B* Szafir przywłaszczył sobie Grimlok, przywódca troggów.', '', 'Wróć do wróżebnej misy Talvasha.', '', '', '', '', 0),
(2204, 'koKR', 'Naprawa naszyjnika', 'Musisz znaleźć trochę „kopa” dla naszyjnika, a najlepszym miejscem, żeby go zdobyć, jest chyba właśnie Uldaman. Kręci się tam sporo konstruktów, tak? No to rozwal największy, najgroźniejszy konstrukt w tym miejscu i zabierz jego źródło mocy! Jestem prawie pewien, że zdołam wtopić je w naszyjnik.$B$BBez tego źródła mocy naprawa naszyjnika będzie niemożliwa. Wróć do mnie tutaj, do Żelaznej Kuźni, kiedy je zdobędziesz, a wszystko ci naprawimy!', 'Zdobądź źródło mocy z najpotężniejszego konstruktu, jaki znajdziesz w Uldamanie, i dostarcz je Talvashowi del Kisselowi w Żelaznej Kuźni.', '', 'Wróć do Talvasha del Kissela w Dzielnicy Mistycznej w Żelaznej Kuźni.', '', '', '', '', 0),
(2240, 'koKR', 'Ukryta komnata', 'A teraz do rzeczy.$B$BJest tu tajna komnata, Komnata Khaz\'mul, którą trzeba zbadać. Kłopot w tym, że kryje się za ogromnymi, zamkniętymi drzwiami! Na szczęście wiem, jak je otworzyć.$B$BWszystko opisałem w dzienniku, tu na stole. Moja drużyna i ja na razie tu utknęliśmy... więc to ty, $N, musisz odnaleźć dla nas Komnatę Khaz\'mul!$B$BPrzeczytaj mój dziennik, zbadaj komnatę, a potem zamelduj się u poszukiwacza Gromdardy w Lidze Odkrywców w Żelaznej Kuźni.', 'Przeczytaj dziennik Baeloga, zbadaj ukrytą komnatę, a następnie zamelduj się u poszukiwacza Gromdardy.', 'Zbadaj ukrytą komnatę', 'Wróć do poszukiwacza Gromdardy w Dun Morogh.', '', '', '', '', 0),
(2279, 'koKR', 'Platynowe dyski', 'Gdy ponownie dotykasz Dysków Norgannona, znów czujesz mrowienie w dłoni. Tym razem jednak z wnętrza dysków dobiega dziwny zgrzyt.$B$BTwój plecak nagle staje się cięższy niż przedtem. W środku znajdujesz miniaturową wersję dysków!$B$BBez wątpienia taki przedmiot byłby bezcenny dla kogoś, kto interesuje się pradawną historią Azeroth. Liga Odkrywców z Żelaznej Kuźni, znana w całym Przymierzu, to właśnie taka grupa; może zrobi z niego dobry użytek.', 'Zanieś miniaturową wersję Dysków Norgannona do Ligi Odkrywców w Żelaznej Kuźni.', '', '', '', '', '', '', 0),
(2280, 'koKR', 'Platynowe dyski', 'Gdy znów dotykasz Dysków Norgannona, czujesz mrowienie w dłoni. Tym razem jednak ze środka dysków dobiega dziwny zgrzyt.$B$BTwój plecak nagle staje się cięższy niż przedtem. W środku znajdujesz miniaturową wersję dysków!$B$BBez wątpienia taki przedmiot byłby bezcenny dla kogoś, kogo zajmują dawne dzieje Azeroth. Mędrcy z Gromowych Urwisk to właśnie tacy historycy, znani w całej Hordzie; może oni zrobią z niego dobry użytek.', 'Zanieś miniaturową wersję Dysków Norgannona jednemu z mędrców w Gromowych Urwiskach.', '', '', '', '', '', '', 0),
(2342, 'koKR', 'Odzyskane skarby', 'Zamiatanie zagród nietoperzy tą miotłą nie przystoi Garrettowi! Zarobiłem trochę grosza na tej przeklętej robocie i chętnie wydam go na ciebie, by poprawić swoje położenie.$B$BUlubiona broń rodu Garrettów jest zamknięta w naszej skrzyni w Południowej Sali Wspólnej w Uldamanie – została tam z czasów, gdy my, Garrettowie, harowaliśmy tam jako kopacze. Bez niej utknę tu na zawsze – dosłownie – sprzątając po tych piekielnych nietoperzach.$B$BOdzyskaj skarb mojej rodziny i przynieś go mi! Pomóż mi odzyskać to, co należy mi się z urodzenia!', 'Zabierz skarb rodziny Patricka Garretta z rodzinnej skrzyni w Południowej Sali Wspólnej w Uldamanie i zanieś go Patrickowi do Podmiasta.', '', 'Wróć do Patricka Garretta nad Jeziorem Lordamere w Górach Alterak.', '', '', '', '', 0),
(2361, 'koKR', 'Naprawa naszyjnika', '', '', '', '', '', '', '', '', 0),
(2398, 'koKR', 'Zaginione krasnoludy', 'Wykopaliska w Uldamanie nie zawsze były w rękach wroga. My, krasnoludy z Żelaznej Kuźni, władaliśmy kiedyś tym terenem, ale... to było, zanim przyszły troggi. Przybyły tak szybko i w takiej liczbie, że nawet krasnoludzka siła nie zdołała ich powstrzymać!$B$BIch atak był wręcz tak nagły, że obawiam się, iż część naszych mogła zostać odcięta za liniami wroga.$B$BMój przyjaciel Baelog tuż przed pojawieniem się troggów poprowadził niewielką grupę krasnoludów w głąb wykopalisk. Jeśli on i jego towarzysze żyją, chcę, żebyś ich $godnalazł:odnalazła;.', 'Odnajdź Baeloga w Uldamanie.', '', '', '', '', '', '', 0),
(2439, 'koKR', 'Platynowe dyski', 'Ten przedmiot to niesamowite znalezisko. Jeśli zapisana w nim wiedza jest prawdziwa, to pradawni tytani – czy też Stwórcy, jak nazywają ich te dyski – są ogniwem łączącym nas z tajemnicą naszego magicznego stworzenia! Musimy poświęcić na badania tyle czasu, ile się da.$B$BCo do ciebie, $gmój bohaterze:moja bohaterko;, zanieś ten bon Dinicie Kamiennopłaszcz w skarbcu. Zapewni ci nagrodę, którą uważam za stosowną za tak ogromne znalezisko!$B$BWróć do mnie od razu, gdy będziesz $ggotów:gotowa; – Liga Odkrywców ma jeszcze wiele do zrobienia!', 'Zanieś bon na nagrodę Dinicie Kamiennopłaszcz w Skarbcu Żelaznej Kuźni.', '', '', '', '', '', '', 0),
(2440, 'koKR', 'Platynowe dyski', 'Skupię swoje siły na tych dyskach; w swoim czasie odsłonią przede mną swoje prawdziwe działanie.$B$BCo do ciebie, $N, teraz nagrodzę cię za staranność, z jaką $gzwróciłeś:zwróciłaś; moją uwagę na to znalezisko. Zanieś ten bon Benie Zimowe Kopyto, nauczycielce alchemii w Gromowych Urwiskach. Da ci wyjątkowy przedmiot, który, jak sądzę, przypadnie ci do gustu, i pozwoli wybrać mikstury z moich osobistych zapasów.$B$BWróć do mnie niebawem, bo czuję, że w związku z tym znaleziskiem czeka nas jeszcze wiele pracy.', 'Zanieś bon z nagrodą Benie Zimowe Kopyto w Gromowych Urwiskach.', '', '', '', '', '', '', 0),
(2769, 'koKR', 'Bracia Mosiężnośrubowie', 'Znasz braci Mosiężnośrubów? Są na Migoczących Równinach w Kalimdorze i ścigają się swoim rakietowym autem z goblinami. Zwykle wygrywają, co nie dziwi – goblińskie auto wybucha tak często, że prawie nigdy nie dojeżdża do mety!$B$BAle i tak bracia Mosiężnośrubowie ciągle szukają sposobów, żeby ich auto jechało szybciej, a Wizzle mówił mi, że do następnego eksperymentu potrzebuje bardzo rzadkiej części.$B$BPewnie przyda mu się pomoc w jej zdobyciu. Porozmawiaj z nim i się dowiedz.', 'Porozmawiaj z Wizzle\'em Mosiężnośrubem na Migoczących Równinach.', '', '', '', '', '', '', 0),
(2946, 'koKR', 'Zobaczymy, co się stanie', 'Chcemy, żebyś $gzaniósł:zaniosła; znalezione przez ciebie miniaturowe dyski do zapieczętowanych wrót Uldum. My... nie wiemy do końca, co się wtedy stanie.$B$BTo brzmi ryzykownie, owszem, przyznajemy. Może się jednak okazać, że nic się nie stanie. Może trzeba będzie użyć dysków na czymś. Może drzwi otworzą się same, gdy będziesz mieć dyski przy sobie. Bądź $ggotów:gotowa; spróbować wszystkiego i na wszystko, co może się zdarzyć.$B$BGdy już się dowiesz, co się dzieje, wróć do Żelaznej Kuźni. Kiedy skończysz, będziemy mieli mnóstwo do analizowania!', 'Zanieś miniaturowe platynowe dyski do wrót Uldum w Tanaris i poszukaj wskazówek, co łączy jedne z drugimi.', '', '', '', '', '', '', 0),
(2948, 'koKR', 'Ulepszenie po gnomiemu', 'Słuchaj, $n, ten pierścień jest twój, jasne... ale mogę ci zrobić lepszy! Jak mówiłem, jego wzór jest naprawdę prosty. Teraz mam znacznie większe umiejętności i za skromną opłatą trzydziestu srebrnych monet trochę go podrasuję! No, właściwie za trochę więcej niż trzydzieści...$B$BJestem teraz w trudnym położeniu; skończyły mi się wszystkie materiały. Jeśli przyniesiesz mi sztabkę srebra i agat mszysty, dodam do pierścienia srebrno-agatową plecionkę, która doda mu trochę blasku!$B$BZaufaj mi!', 'Przynieś błyszczący złoty pierścień, sztabkę srebra, agat mszysty i 30 srebrnych monet Talvashowi del Kisselowi w Żelaznej Kuźni.', '', '', '', '', '', '', 0),
(2963, 'koKR', 'Znaki Uldum', 'Witaj ponownie, $n! Twoje odkrycie w Uldamanie wywołało w Lidze Odkrywców prawdziwe poruszenie. Liga pracuje nad odkryciem tajemnic miniaturowych platynowych dysków, które $gznalazłeś:znalazłaś;. Twoje szczęśliwe przybycie tu, do Sali, pozwala mi zdradzić ci, że być może na coś trafiliśmy!$B$BHistoryk Karnik odkrył ważne wskazówki dotyczące prawdziwego pochodzenia Doliny Strażników na pustyni Tanaris. Chciałby jak najszybciej z tobą porozmawiać!', 'Porozmawiaj z historykiem Karnikiem w Sali Odkrywców w Żelaznej Kuźni.', '', '', '', '', '', '', 0),
(2964, 'koKR', 'Zadanie na przyszłość', 'Cóż, $n... wygląda na to, że na razie utknęliśmy w ślepym zaułku. Wiemy, czego potrzebujemy – Płyt Uldum – ale nie mamy pojęcia, gdzie mogą być. Będziemy musieli sporo nad tym popracować, żeby opracować solidny plan działania. Mam kilka pomysłów, od czego zacząć szukać; mam wielką nadzieję, że wkrótce poprosimy cię, żebyś $gwyruszył:wyruszyła; je odzyskać.$B$BArcyodkrywca musi się o tym dowiedzieć, $n; bez wątpienia chce też osobiście ci podziękować za to, że po raz kolejny $gpomogłeś:pomogłaś; Lidze.', 'Porozmawiaj z arcyodkrywcą Magellasem w Żelaznej Kuźni.', '', '', '', '', '', '', 0),
(2965, 'koKR', 'Znaki Uldum', 'Ach, $n, to szczęśliwy traf, że znów do mnie przychodzisz. Twoje odkrycia na wykopaliskach w Uldamanie dały nam, mędrcom, wiele do omówienia. Właśnie o nich rozmawiałem z jedną z druidek, Narą Dzikogrzywą, gdy przyszło mi do głowy, że jej dawne wyprawy mogą mieć wielkie znaczenie dla naszego następnego kroku.$B$BChciałbym, żebyś $gporozmawiał:porozmawiała; z nią o jej podróżach do Doliny Strażników na pustyni Tanaris. Czeka na ciebie na Wzniesieniu Starszych.', 'Porozmawiaj z Narą Dzikogrzywą na Wzniesieniu Starszych w Gromowych Urwiskach.', '', '', '', '', '', '', 0),
(2966, 'koKR', 'Zobaczymy, co się stanie', 'Mędrzec Poszukiwacz Prawdy i ja chcielibyśmy, żebyś $gzaniósł:zaniosła; znalezione przez ciebie miniaturowe dyski do zapieczętowanych wrót Uldum. Nie... nie jesteśmy pewni, co się stanie, gdy to zrobisz.$B$BTak, brzmi to ryzykownie, przyznajemy. Może jednak nic się nie wydarzy. Być może trzeba będzie użyć dysków na czymś. Być może wrota otworzą się, gdy będziesz mieć dyski przy sobie. Bądź $gotwarty:otwarta; na każdą próbę i $ggotów:gotowa; na wszystko.$B$BDowiedz się, czego zdołasz, i wróć do mnie. Będziemy mieli wiele do omówienia.', 'Zanieś miniaturowe platynowe dyski do wrót Uldum w Tanaris i poszukaj wskazówek, co łączy jedne z drugimi.', '', '', '', '', '', '', 0),
(2968, 'koKR', 'Zadanie na przyszłość', 'Cóż, $n... wygląda na to, że utknęliśmy w martwym punkcie. Wiemy, czego potrzebujemy – Płyt Uldum – ale nie mamy pojęcia, gdzie mogą być. Zbadamy tę sprawę, a potem opracujemy solidny plan działania. Mam kilka pomysłów, od czego zacząć poszukiwania; mocno wierzę, że wkrótce znów poprosimy cię o dołączenie do naszych starań o odkrycie prawdy.$B$BTrzeba o tym powiadomić mędrca Poszukiwacza Prawdy, $n; bez wątpienia chce też osobiście podziękować ci za to, że po raz kolejny $godpowiedziałeś:odpowiedziałaś; na wezwanie.', 'Porozmawiaj z mędrcem Poszukiwaczem Prawdy w Gromowych Urwiskach.', '', '', '', '', '', '', 0),
(2977, 'koKR', 'Powrót do Żelaznej Kuźni', 'Ponownie dotykasz piedestału; platynowe dyski nagle znów pojawiają się w twoim plecaku.$B$BZ wiedzą przekazaną przez kamiennego obserwatora i dyskami z powrotem w twoim posiadaniu nadszedł czas, by wrócić do Żelaznej Kuźni i powiadomić Ligę Odkrywców o twoim odkryciu.', 'Porozmawiaj z historykiem Karnikiem w Żelaznej Kuźni.', '', '', '', '', '', '', 0),
(3182, 'koKR', 'Dowód czynu', 'Chcesz, żebym uwierzyła w taką historyjkę? W prawdziwym rogu wciąż tkwiłoby ostrze mojego złamanego topora.$B$BSłuchaj, zanieś tę oczywistą podróbkę kustoszowi Thoriusowi w Żelaznej Kuźni. Jeśli potwierdzi twoje słowa, dostaniesz dowód czynu. Przynieś mi ten dowód, a dam ci klucz do Płonącego Wąwozu.$B$BRuszaj!', 'Zanieś gigantyczny róg Margola kustoszowi Thoriusowi w Żelaznej Kuźni.', '', '', '', '', '', '', 0),
(3201, 'koKR', 'Nareszcie!', 'Nie mogę uwierzyć, że Kamyczek wątpiła w autentyczność rogu. Między nami mówiąc, myślę, że jest po prostu zazdrosna. Wiem, że bardzo chciała sama zabić tę bestię, zwłaszcza po tym całym „incydencie”.$B$BPotrzebujesz więc dowodu czynu? Po tym, co właśnie $gofiarowałeś:ofiarowałaś; muzeum, to żaden problem.$B$B<Kustosz Thorius zaczyna wypełniać duży dokument.>$B$BGotowe! Możesz to zanieść Kamyczek.', 'Zanieś dowód czynu z powrotem górskiej strażniczce Kamyczek.', '', '', '', '', '', '', 0),
(3367, 'koKR', 'Kamienie Suntary', '<Dorius jęczy.>$B$BJestem ciężko ranny. Kręci mi się... w głowie... Świat wiruje... Krwawię... wewnętrznie.$B$BMuszę wrócić do Żelaznej Kuźni. Pomóż mi, $N.$B', 'Pomóż Doriusowi wrócić do Żelaznej Kuźni.$B', 'Eskorta Doriusa', 'Podnieś przypalony list w Płonącym Wąwozie.', '', '', '', '', 0),
(3368, 'koKR', 'Kamienie Suntary', 'Bracie,$B$BJeśli czytasz ten list, już mnie nie ma. Nie wiem, jak do ciebie trafił, ale podziękuj tym, którzy go dostarczyli, i ich wynagrodź.$B$BCo do kamieni: istnieją, a Czarnoryci mają je w swoim posiadaniu. Ich przywódca, Lathoric Czarny, wykorzystuje moc kamieni, by zniewolić moją ekipę wykopaliskową. Zabrano ich do Kotła. Ich umysły są wypaczone, pracują dniem i nocą, by ukończyć coś, co nazywają Obsidionem.$B$BPomóż im, bracie. To ostatnie życzenie zmarłego.$B$B– Dorius$B', 'Zanieś przypalony list Thoriusowi w Żelaznej Kuźni. Znajdziesz go w Sali Odkrywców.', '', '', '', '', '', '', 0),
(3371, 'koKR', 'Krasnoludzka sprawiedliwość', 'Tam, gdzie kiedyś było moje serce, ziała teraz pustka, $N. Po stracie Doriusa prędko się nie pozbieram. Muszę spełnić jego ostatnią wolę – sprawcy tego morderstwa z zimną krwią muszą ponieść karę.$B$BWróć do Płonącego Wąwozu i spełnij jego ostatnią prośbę: uwolnij jego ludzi. Krasnoludy z klanu Czarnorytych zmuszają niewolników do pracy w dusznej kopalni zwanej Żużlową Jamą. Tam szukaj ludzi Doriusa.', 'Wróć do Płonącego Wąwozu i odnajdź ekipę archeologiczną Doriusa.', '', '', '', '', '', '', 0),
(3375, 'koKR', 'Zapasowa fiolka', 'Eee... potrzebujesz kolejnej wróżebnej fiolki? Żartujesz, prawda? Co $gzrobiłeś:zrobiłaś; z pierwszą?! Mamy przed sobą mnóstwo pracy. Te fiolki nie rosną na drzewach! Właściwie szkoda, bo poszedłbym tam i jedną zerwał, skoro nie mam już żadnej!!$B$BŻeby ci ją zrobić, potrzebuję: mikstury many, kawałka węgla i trochę słodkiego nektaru. Nie pytaj dlaczego, po prostu przynieś, o co proszę, a zrobię ci nową.', 'Przynieś miksturę many, węgiel i słodki nektar Talvashowi del Kisselowi w Żelaznej Kuźni, by dostać nową wróżebną fiolkę Talvasha.', '', 'Wróć do Talvasha del Kissela w Dzielnicy Mistycznej w Żelaznej Kuźni.', '', '', '', '', 0),
(3448, 'koKR', 'Przekazanie brzemienia', 'Niedawno powierzono mi zbadanie Aszary – niegdyś pięknej krainy, którą elfy nazywały domem. Było to w czasach, gdy jeszcze parały się magią. Dziś jest tam bardziej niebezpiecznie niż pięknie, ale to nie powstrzymuje nas przed odwracaniem każdego kamienia w poszukiwaniu odpowiedzi o naszej przeszłości.$B$BMój towarzysz, Tymor, zaoferował pomoc w badaniu tego obszaru, bo szczególnie interesują go takie rzeczy.$B$BMa niewielki lokal na prawo od Sali Tajemnic, tu w mieście.', 'Porozmawiaj z Tymorem w Żelaznej Kuźni.', '', '', '', '', '', '', 0),
(3449, 'koKR', 'Tajemne runy', 'Dla niektórych elfów magia była niegdyś otaczana czcią równą samej Elunie. Niektórzy z ich najpotężniejszych magów tworzyli runy i tablice przytaczające zasady mocy tajemnej i wnioski z ich odkryć. Zostawiali je w miejscach publicznych, by każdy mógł nad nimi rozmyślać.$B$BBardzo chciałbym mieć odbitki tych run z Ruin Eldarath. Mam dla ciebie zestaw do robienia odbitek, ale znalezienie run będzie należało do ciebie. Uważaj jednak, Liga Odkrywców nie jest jedyną, którą interesuje Eldarath.', 'Za pomocą zestawu do rysowania zrób odbitki runy Beth\'Amara, runy Jin\'yael, runy Markri i runy Sael\'hai, a następnie udaj się na niewielką wyspę u wybrzeża południowego półwyspu Aszary i daj sygnał pilotowi Xiggsowi Lontopalowi, by je odebrał.', '', 'Wróć do pilota Xiggsa Lontopala przy Pomniku Ravencresta w Aszarze.', '', '', '', '', 0),
(3450, 'koKR', 'Łatwy odbiór', 'Chcę, żeby odbitki trafiły do mojej wieży, ale nie ma potrzeby, żebyś $gfatygował:fatygowała; się aż tam. Po prostu każę je przetransportować z Aszary drogą powietrzną.$B$BXiggs Lontopal jest mi winien przysługę czy dwie i wkrótce będzie w okolicy – zaciągnął się do patrolowania wybrzeża. Porozmawiaj z nim, zanim wyruszysz. Da ci rakietnicę, żebyś $gmógł:mogła; dać mu sygnał. Kiedy zdobędziesz odbitki, udaj się tam, gdzie ci wskaże, i przekaż mu je, żeby bezpiecznie dostarczył je do mojej wieży. Powinien być w hangarze w Dzielnicy Wojskowej.', 'Porozmawiaj z Xiggsem Lontopalem w Żelaznej Kuźni.', '', '', '', '', '', '', 0),
(3451, 'koKR', 'Sygnał do odbioru', 'Ach, więc to Tymor cię przysłał, tak? No, jestem mu winien przysługę czy dwie. Co takiego? A to mały diabeł. Tak, mogę mu w tym pomóc. Czyli potrzebujesz rakietnicy i miejsca... to proste.$B$BU wybrzeża południowego półwyspu Aszary jest mała wyspa, na której zrobiliśmy lądowisko. Weź tę rakietnicę i użyj jej tam. Zobaczę twój sygnał i przylecę odebrać to... cokolwiek on tam chce.', 'Porozmawiaj z Xiggsem Lontopalem w Żelaznej Kuźni i odbierz od niego regulaminową rakietnicę.', '', '', '', '', '', '', 0),
(3461, 'koKR', 'Powrót do Tymora', 'Tymor nie dał mi niczego, żeby ci zapłacić, więc radzę upomnieć się o to u niego, kiedy wrócisz do Żelaznej Kuźni. Na pewno wciąż siedzi u siebie w Dzielnicy Mistycznej. Zapukaj i dopilnuj, żeby porządnie ci zapłacił. To miejsce to nie piknik... co to, to nie.$B$BW każdym razie jeszcze raz dzięki, że mu $gpomogłeś:pomogłaś;, i powodzenia.$B$BAch, i nie potrzebuję zestawu do rysowania. Może po prostu oddasz go Tymorowi, kiedy do niego pójdziesz?', 'Zwróć Tymorowi jego zestaw do rysowania w Żelaznej Kuźni.', '', '', '', '', '', '', 0),
(3483, 'koKR', 'Sygnał do odbioru', '', '', '', '', '', '', '', '', 0),
(3566, 'koKR', 'Powstań, Obsidionie!', 'To... To... To była pułapka.$B$BWybacz... mi.$B$BZabij zdrajcę... Zabij go dla nas... dla Thoriusa.', 'Zabij Lathorica Czarnego i Obsidiona, a potem wróć do Thoriusa w Żelaznej Kuźni z głową Lathorica Czarnego i sercem Obsidiona.', '', 'Wróć do kustosza Thoriusa w Żelaznej Kuźni.', '', '', '', '', 0),
(3632, 'koKR', 'Gnomia inżynieria', 'Inżynieria na poziomie eksperckim dzieli się na dwie dyscypliny: gnomią i goblińską. Gnomia inżynieria jest zdecydowanie lepsza z nich dwóch! Chodzi w niej o konstruowanie wspaniałych gadżetów i urządzeń, które ułatwiają życie!$B$B$N, przeczytaj ten podręcznik. Jeśli chcesz dowiedzieć się więcej o gnomiej inżynierii, zanieś go majstrowi Nadiskrze tutaj, w Żelaznej Kuźni. Pamiętaj – przynależność jest dożywotnia i wyklucza wstąpienie do drugiej dyscypliny, więc upewnij się, że naprawdę tego chcesz, zanim wykonasz jego zadanie!', 'Jeśli chcesz dowiedzieć się więcej o gnomiej inżynierii, zanieś podręcznik dyscyplin inżynieryjnych majstrowi Nadiskrze w Żelaznej Kuźni.', '', '', '', '', '', '', 0),
(3634, 'koKR', 'Gnomia inżynieria', 'Inżynieria na poziomie eksperckim dzieli się na dwie dyscypliny: gnomią i goblińską. Choć moim zdaniem to strata czasu, $gpowinieneś:powinnaś; wiedzieć o gnomiej specjalizacji. Gnomy robią przedmioty i gadżety, które podobno mają zmienić świat, ale rzadko kiedy w ogóle działają.$B$B$N, przeczytaj ten podręcznik. Jeśli chcesz się nauczyć robić metalowe przyciski do papieru, zanieś go majstrowi Nadiskrze w Żelaznej Kuźni. Pamiętaj – przynależność jest dożywotnia i wyklucza wstąpienie do drugiej dyscypliny, więc upewnij się, że naprawdę tego chcesz, zanim wykonasz jego zadanie!', 'Jeśli chcesz dowiedzieć się więcej o gnomiej inżynierii, zanieś podręcznik dyscyplin inżynieryjnych majstrowi Nadiskrze w Żelaznej Kuźni.', '', '', '', '', '', '', 0),
(3639, 'koKR', 'Pokaż, co potrafisz', 'Błysk w twoim oku mówi mi wszystko: chcesz wysadzać różne rzeczy w powietrze. Masz wschodzący talent, $N, ale chciałbym dostać próbki twojej pracy, żeby sprawdzić, jak położyć w niej większy nacisk na goblińskie techniki. Potrzebuję: dwudziestu dużych żelaznych bomb, dwudziestu lasek solidnego dynamitu i pięciu wybuchowych owiec – i nie zdejmuj zabezpieczeń!$b$bPrzekaż mi te przedmioty, a zostaniesz $goficjalnym goblińskim inżynierem:oficjalną goblińską inżynierką;!', 'Przynieś 20 dużych żelaznych bomb, 20 lasek solidnego dynamitu i 5 wybuchowych owiec Nixxowi Sprężynotrybowi w Gadżetonie.', '', 'Wróć do Nixxa Sprężynotryba w Tanaris.', '', '', '', '', 0),
(3640, 'koKR', 'Przyrzeczenie tajemnicy', 'W gnomiej inżynierii chodzi o teorię inżynieryjną ukształtowaną tak, by służyła naszym potrzebom! Nasze schematy pozwalają budować urządzenia, które panują nad otaczającym nas światem; była o tym mowa w podręczniku, który $gprzeczytałeś:przeczytałaś;.$B$BW podręczniku była też mowa o naszej odwiecznej przysiędze, że schematy pozostaną tajemnicą. Gdy zostaniesz $ggnomim inżynierem:gnomią inżynierką;, klamka zapadła. Do goblińskiej inżynierii nie będziesz mieć żadnego dostępu.$B$BJeśli nadal chcesz zostać $ggnomim inżynierem:gnomią inżynierką;, podpisz ten dokument, przyrzekając dożywotnie zachowanie tajemnicy, i porozmawiaj ze mną ponownie. Dobrze się zastanów, $N.', 'Jeśli zgadzasz się zostać $ggnomim inżynierem:gnomią inżynierką;, kliknij prawym przyciskiem Przyrzeczenie tajemnicy i porozmawiaj jeszcze raz z majstrem Nadiskrą w Żelaznej Kuźni.', '', 'Wróć do majstra Nadiskry w Dun Morogh.', '', '', '', '', 0),
(3641, 'koKR', 'Pokaż, co potrafisz', 'Jeśli chcesz tworzyć naprawdę fantastyczne urządzenia, to $gtrafiłeś:trafiłaś; we właściwe miejsce. Widzę, że jesteś $gwprawnym inżynierem:wprawną inżynierką;, ale chcę zobaczyć próbki twojej pracy. Mam nadzieję przeanalizować twój warsztat pod kątem tego, jak w przyszłych pracach położyć większy nacisk na gnomie techniki. Potrzebuję następujących próbek: sześciu mithrilowych rur, precyzyjnej lunety i dwóch zaawansowanych kukieł treningowych.$B$BPrzekaż mi te przedmioty, a zostaniesz $goficjalnym gnomim inżynierem:oficjalną gnomią inżynierką; z dostępem do wszystkich schematów!', 'Przynieś 6 mithrilowych rur, precyzyjną lunetę i 2 zaawansowane kukły treningowe majstrowi Nadiskrze w Żelaznej Kuźni.', '', 'Wróć do majstra Nadiskry w Dun Morogh.', '', '', '', '', 0),
(3643, 'koKR', 'Pokaż, co potrafisz', 'Jeśli chcesz tworzyć naprawdę fantastyczne urządzenia, to $gtrafiłeś:trafiłaś; we właściwe miejsce. Widzę, że jesteś $gwprawnym inżynierem:wprawną inżynierką;, ale chcę zobaczyć próbki twojej pracy. Mam nadzieję przeanalizować twój warsztat pod kątem tego, jak w przyszłych pracach położyć większy nacisk na gnomie techniki. Potrzebuję następujących próbek: sześciu mithrilowych rur, precyzyjnej lunety i dwóch zaawansowanych kukieł treningowych.$B$BPrzekaż mi te przedmioty, a zostaniesz $goficjalnym gnomim inżynierem:oficjalną gnomią inżynierką; z dostępem do wszystkich schematów!', 'Przynieś 6 mithrilowych rur, precyzyjną lunetę i 2 zaawansowane kukły treningowe Oglethorpe\'owi Obnoticusowi w Łupieżczej Zatoce.', '', 'Wróć do Oglethorpe\'a Obnoticusa w Łupieżczej Zatoce w Dolinie Cierniodławów.', '', '', '', '', 0),
(3644, 'koKR', 'Odnowienie legitymacji członkowskiej', '', '', '', '', '', '', '', '', 0),
(3645, 'koKR', 'Odnowienie legitymacji członkowskiej', '', '', '', '', '', '', '', '', 0),
(3646, 'koKR', 'Odnowienie legitymacji członkowskiej', '$B', '', '', '', '', '', '', '', 0),
(3647, 'koKR', 'Odnowienie legitymacji członkowskiej', '', '', '', '', '', '', '', '', 0),
(3701, 'koKR', 'Tlące się ruiny Thaurissanu', 'Wyrusz do tlących się ruin Thaurissanu na Płonących Stepach i zbierz jak najwięcej informacji.$B$BPodobno w ruinach walają się tajemnicze relikwie. Może od nich $gpowinieneś:powinnaś; zacząć poszukiwania, $N. Strzeż się strażników Thaurissanu – zabójców, którzy pilnują ruin i chronią wszelkie sekrety, jakie mogą być tam jeszcze pogrzebane.', 'Wyrusz do Ruin Thaurissanu na Płonących Stepach i wydobądź informacje z relikwii Thaurissana. Gdy je zdobędziesz, wróć do królewskiej historyczki Archesonus.', '', 'Wróć do królewskiej historyczki Archesonus w Wysokiej Izbie w Żelaznej Kuźni.', 'Zdobyte informacje', '', '', '', 0),
(3702, 'koKR', 'Tlące się ruiny Thaurissanu', 'Czy chcesz usłyszeć krótką historię krasnoludów z klanu Czarnorytych?', 'Wysłuchaj opowieści królewskiej historyczki Archesonus o dziejach Thaurissanu.', 'Opowieść o Thaurissanie', 'Wróć do królewskiej historyczki Archesonus w Dun Morogh.', '', '', '', '', 0),
(4003, 'koKR', 'Królewski ratunek', 'Ten cios w krasnoludy z klanu Czarnorytych, jeśli się powiedzie, wstrząśnie całym ich królestwem.$B$BKsiężniczka Miedziobroda jest pod władzą imperatora Thaurissana. Aby ją uwolnić, musisz zabić imperatora. Uważaj, twoje zadanie jest podwójnie niebezpieczne, bo dopóki imperator nad nią panuje, Miedziobroda bez wahania cię zaatakuje.$B$BNIE WOLNO CI JEJ SKRZYWDZIĆ!', 'Zabij imperatora Dagrana Thaurissana i uwolnij księżniczkę Moirę Miedziobrodą spod jego złego czaru.$B', '', 'Porozmawiaj z księżniczką Moirą Miedziobrodą przy tronie w Otchłani Czarnej Góry.', '', '', '', '', 0),
(4341, 'koKR', 'Kharan Potężny Młot', '$GByłeś:Byłaś; w tlących się ruinach Thaurissanu? Czy przypadkiem nie $gnatknąłeś:natknęłaś; się tam na żałosnego gamonia imieniem Kharan Potężny Młot? Na krasnoluda, który rzekomo miał pilnować mojej córeczki!$B$B<Król szlocha.>$B$BA teraz jej nie ma, $N!$B$BKazałem moim ludziom przewrócić Stepy do góry nogami. Jedyny ślad, jaki mają co do miejsca pobytu mojej córki, to to, że może być w Otchłani. Kto wie, może już nie żyje!$B$BKharan jest tam podobno więziony... odnajdź go! Chcę odpowiedzi!', 'Udaj się do Otchłani Czarnej Góry i odnajdź Kharana Potężnego Młota.$B$BKról wspomniał, że Kharan jest tam więziony – może warto poszukać więzienia.', '', '', '', '', '', '', 0),
(4361, 'koKR', 'Zwiastun złych wieści', 'Musisz zanieść te wieści królowi Magniemu, $N. On będzie wiedział, co robić!$B', 'Wróć do Żelaznej Kuźni i przekaż złe wieści królowi Magniemu Miedziobrodemu.', '', '', '', '', '', '', 0),
(4362, 'koKR', 'Los królestwa', 'Wygląda na to, że mój dawny wróg, Dagran Thaurissan, trzyma mnie i królestwo Żelaznej Kuźni w garści.$B$BMożesz być moją ostatnią nadzieją, $N. Musisz uratować moją ukochaną córkę, Moirę!$B$BIstnieje tylko jeden sposób, by mieć pewność, że czar, który Thaurissan rzucił na Moirę, zostanie złamany: zabij go.$B$BI jeszcze jedno, $N: nie rób jej krzywdy! Pamiętaj, że Thaurissan nią steruje! Wszystko, co może zrobić lub powiedzieć, to skutek jego złego czaru!', 'Wróć do Otchłani Czarnej Góry i wyrwij księżniczkę Moirę Miedziobrodą ze szponów imperatora Dagrana Thaurissana.$B', '', 'Porozmawiaj z księżniczką Moirą Miedziobrodą przy tronie w Otchłani Czarnej Góry.', '', '', '', '', 0),
(4363, 'koKR', 'Niespodzianka księżniczki', 'Thaurissan był wielkim i honorowym krasnoludem. $GZniszczyłeś:Zniszczyłaś; życie mnie i mojemu nienarodzonemu dziecku!$B$B<Przychodzi ci na myśl, że księżniczka Miedziobroda wciąż może być pod wpływem resztek czaru imperatora.>$B$BWróć do Żelaznej Kuźni i powiedz mojemu ojcu, że dziedzic Królestwa Żelaznej Kuźni będzie krasnoludem z klanu Czarnorytych.$B$BCzy mu się to podoba, czy nie, tak się stanie.', 'Wróć do Żelaznej Kuźni i porozmawiaj z królem Magnim Miedziobrodym.', '', '', '', '', '', '', 0),
(4512, 'koKR', 'Trochę szlamu wystarczy na długo', 'Ale najwięcej badałem szlamy. Wiem, że to brzmi dziwnie, ale są wszędzie!$B$BNiedawno pomogłem pewnej pani z Przystani Menethilów odnaleźć torbę – pożarły ją szlamy. Widziałem, jak członkowie Królewskich Zakładów Chemicznych z Podmiasta zbierają próbki tego paskudztwa. Chcę wiedzieć dlaczego! Skąd się to bierze?$B$BSłyszałem, że więcej ich jest w Spaczonej Kniei. Potrzebuję próbek tamtejszych szlamów, żeby kontynuować badania. Dam ci pojemniki, a ty użyj ich, żeby pobrać próbki z martwych stworzeń.', 'Przynieś 6 pełnych słojów przeklętego szlamu i 6 pełnych słojów skażonego szlamu Larisowi Trybomarudzie w Żelaznej Kuźni.', '', 'Wróć do Larisa Trybomarudy w bibliotece w Żelaznej Kuźni.', '', '', '', '', 0),
(4513, 'koKR', 'Trochę szlamu wystarczy na długo', 'Będę potrzebował więcej próbek, $N. Ale... nie wiem, jak to ująć... to muszą być czyste próbki. Wiem, wiem. „Co znaczy »czyste«, Laris?” Nie jestem pewien. Wiem tylko, że te są skażone... tak jak Spaczona Knieja. I właśnie dlatego moje odkrycie jest takie ważne. Szlamy chyba się przystosowują... przejmują cechy okolicy, w której żyją. Muszę znaleźć próbki, które nie zostały skażone. Ale gdzie? Gdzie?!$B$BEch! $N, weź te pojemniki, na wypadek gdybyś $gznalazł:znalazła; jakieś na własną rękę.', 'Przynieś 10 pełnych słojów z czystą próbką Larisowi Trybomarudzie w Żelaznej Kuźni.$B$BJeśli masz kłopot z ich znalezieniem, spróbuj wyciągnąć od Larisa więcej wskazówek.', '', 'Wróć do Larisa Trybomarudy w Dun Morogh.', '', '', '', '', 0),
(4561, 'koKR', 'Badanie zanieczyszczeń – Krater Un\'Goro', '', '', '', 'Wróć do sprzętu testowego.', '', '', '', '', 0),
(4661, 'koKR', 'Badanie skażenia – Spaczona Knieja', '', '', '', 'Wróć do sprzętu testowego.', '', '', '', '', 0),
(4736, 'koKR', 'W poszukiwaniu Menary Rozdzieraczki Pustki', 'Ach, witaj, $N. Dobrze ci idzie nauka. Tak dobrze, że moim zdaniem zasługujesz na nagrodę za ciężką pracę – i za to, że magia tajemna jeszcze cię nie splugawiła.$B$BJeśli jesteś $gzainteresowany:zainteresowana;, odszukaj Menarę Rozdzieraczkę Pustki w Zapadce. Mieszka obecnie w wieży Strahada Farsana, z której roztacza się widok na miasteczko.$B$BNie jest zbyt przyjazna, $N, więc nie licz na pochwały. Ale jeśli będziesz ciężko pracować, zadba o ciebie.', 'Porozmawiaj z Menarą Rozdzieraczką Pustki na Pustkowiach.', '', '', '', '', '', '', 0),
(4965, 'koKR', 'Wiedza o Kuli Orahila', 'No proszę, proszę... miło widzieć, że rośniesz w siłę, $N. Założę się, że już niemal jesteś $ggotów:gotowa;, by porozmawiać z Menarą Rozdzieraczką Pustki na Pustkowiach. Jeśli jeszcze z nią nie $grozmawiałeś:rozmawiałaś;, to powiem ci, że chyba nigdy nie spotkałem nikogo, kto lepiej znałby się na tworzeniu przedmiotów – a konkretnie kul – potrafiących tak łatwo uwięzić nawet demona i zmusić go do służby.$B$BJeśli jesteś $gzainteresowany:zainteresowana;, znajdziesz ją w wieży Strahada nad Zapadką na Pustkowiach.', 'Porozmawiaj z Menarą Rozdzieraczką Pustki na Pustkowiach.', '', '', '', '', '', '', 0),
(5283, 'koKR', 'Sztuka płatnerza', 'A więc $gpodjąłeś:podjęłaś; mądrą decyzję.$B$BMiędzy mną a starym Ironusem nie ma za grosz sympatii. Ten nicpoń od zabawek dobrze wie, kto tu jest prawdziwym rzemieślnikiem.$B$BNaprawdę wielkie wojny wygrywa się dobrą obroną. Kiedy przyjdzie co do czego, żaden atak ci nie pomoże.$B$BDobra, bierzmy się do roboty. Musisz mi tylko pokazać, że masz surowy talent. Potem wytopię z ciebie resztki zanieczyszczeń i wykuję z ciebie $gpłatnerza:płatnerkę;. Umiesz przecie robić zdobiony mithril, co?', 'Aby zostać $gpłatnerzem:płatnerką;, musisz wykonać następujące przedmioty i przynieść je Grumnusowi: 4 zdobione mithrilowe hełmy, 2 pary zdobionych mithrilowych butów, 1 zdobiony mithrilowy napierśnik.', '', 'Wróć do Grumnusa Stalotwórcy w Żelaznej Kuźni.', '', '', '', '', 0),
(5284, 'koKR', 'Droga kowala broni', 'Jako $gkowal:kowalka; broni przekonasz się, że bohaterowie i poszukiwacze przygód najczęściej przychodzą po sprzęt właśnie do ciebie. Choć bywa, że roboty jest ponad siły, bogactwo z nawiązką wynagradza ból krzyża i popiół w płucach.$B$BO tak, $N, to kowale broni mają całe złoto!$B$BJeśli chcesz dołączyć do naszych szeregów, musisz mi pokazać, że potrafisz zarobić dla mnie srebrnika czy dwa... to znaczy pokazać, że masz to, czego trzeba, by być $gtym, do którego:tą, do której; ludzie przychodzą, gdy potrzebują broni najwyższej jakości. Do roboty!', 'Aby zostać $gkowalem:kowalką; broni, musisz wykonać następujące przedmioty i przynieść je Ironusowi: 4 pałasze z księżycowej stali, 4 masywne żelazne topory, 2 ciężkie mithrilowe topory i 2 duże czarne buzdygany.$B', '', 'Wróć do Ironusa Zimnej Stali przy Wielkiej Kuźni w Żelaznej Kuźni.', '', '', '', '', 0),
(5301, 'koKR', 'Sztuka płatnerza', 'Satysfakcja. To ją czerpię z młota i kowadła. Widok dumnego wojownika Hordy, którego chroni moja stal, przypomina mi, co znaczy żyć. To nałóg, którego nigdy nie odważę się rzucić, $N.$B$BNie mogę dać ci tej satysfakcji, mogę tylko wskazać ci ścieżkę. Jak każde życiowe przedsięwzięcie, ścieżka płatnerza jest podróżą.$B$BJeśli chcesz należeć do nielicznych wybranych, wystarczy poprosić, a cię wyszkolę – najpierw jednak musisz wykonać zadanie.', 'Aby zostać $gpłatnerzem:płatnerką;, musisz wykonać następujące przedmioty i przynieść je Okothosowi: 4 zdobione mithrilowe hełmy, 2 pary zdobionych mithrilowych butów, 1 zdobiony mithrilowy napierśnik.', '', 'Wróć do Okothosa Żelaznego Szału w Orgrimmarze.', '', '', '', '', 0),
(5302, 'koKR', 'Droga kowala broni', 'Pewnego dnia stworzę legendarny młot. Młot godny wodza!$B$BTo dzieło mojego życia, $N. Moja pasja. Widzę, że masz w sobie potencjał, by być wśród nas, jednym z nas – $gkowalem:kowalką; broni. To ja mogę ci pomóc ten potencjał wykorzystać.$B$BMusisz tylko wykonać proste zadanie. Proste dla kogoś o tak wyjątkowych umiejętnościach.', 'Aby zostać $gkowalem:kowalką; broni, musisz wykonać następujące przedmioty i przynieść je Borgoshowi: 4 pałasze z księżycowej stali, 4 masywne żelazne topory, 2 ciężkie mithrilowe topory i 2 duże czarne buzdygany.$B', '', 'Wróć do Borgosha Gnącego Rdzeń w Orgrimmarze.', '', '', '', '', 0),
(6388, 'koKR', 'Gryth Thurden', 'Oto honorowe kilofy dla uczniów Brocka. Jeśli już $gbyłeś:byłaś; w Thelsamarze, możesz tam wrócić na gryfie!$B$BZanieś kilofy naszemu mistrzowi gryfów, Grythowi Thurdenowi, i porozmawiaj z nim o locie z powrotem do Thelsamaru.', 'Zanieś honorowe kilofy Grythowi Thurdenowi w Żelaznej Kuźni.', '', '', '', '', '', '', 0),
(6391, 'koKR', 'Lot do Żelaznej Kuźni', 'Za kilka monet jeden z moich gryfów zabierze cię do Żelaznej Kuźni. Stamtąd zanieś listę Brocka Golnirowi Głazopalcowi. Znajdziesz go w Gildii Górniczej Głębogóry. To w dzielnicy Wielkiej Kuźni w Żelaznej Kuźni, dokładnie tam, gdzie wysadzi cię mój gryf!$B$BPorozmawiaj ze mną znowu, kiedy będziesz $ggotów:gotowa; do podróży.', 'Wykup u mistrza gryfów Thorgruma Borrelsona lot do Żelaznej Kuźni, a potem zanieś listę Brocka Golnirowi Głazopalcowi w Żelaznej Kuźni.', '', '', '', '', '', '', 0),
(6392, 'koKR', 'Powrót do Brocka', 'Za niewielką opłatą możesz wykupić lot gryfem do Thelsamaru... o ile już tam $gbyłeś:byłaś;. Gryfy zabiorą cię tylko tam, gdzie już $gbyłeś:byłaś;, więc rozmawiaj z każdym mistrzem gryfów, jakiego spotkasz, żeby móc później do niego polecieć.$B$B$GByłeś:Byłaś; już u Thorgruma, mistrza gryfów z Thelsamaru, więc możesz teraz do niego wrócić. A w Thelsamarze przekażesz kilofy Brockowi Szukaczowi Kamieni.$B$BPorozmawiaj ze mną, kiedy będziesz $ggotów:gotowa; do drogi.', 'Wykup u mistrza gryfów Grytha Thurdena lot do Thelsamaru, a potem zanieś honorowe kilofy Brockowi Szukaczowi Kamieni w Thelsamarze.', '', '', '', '', '', '', 0),
(6609, 'koKR', 'Nic mi już nie zostało!', 'Jestem krasnoludem, do licha, $gchłopcze:panienko;! Nie stworzono mnie do łowienia ryb! No spójrz tylko na mnie! Jestem prawie cały z kamienia.$B$BNic mi już nie zostało – $gwycisnąłeś:wycisnęłaś; ze mnie wszystko. Nauczyłem cię wszystkiego, co umiem, ty płotko!$B$BNie łapiesz? Ech, niech będzie. Mam starego kumpla w Kalimdorze, który ci pomoże. Nazywa się Nat Pagle, porządny chłop. Znajdziesz go na wyspach na południe od Theramore. Ruszaj się!', 'Udaj się do Kalimdoru, do nadmorskiego miasta Theramore. Stamtąd musisz odszukać wyspę na południe od głównego miasta. Nat Pagle czeka na ciebie!', '', '', '', '', '', '', 0),
(6612, 'koKR', 'Znam takiego jednego...', 'Po twojej kuchennej łyżce widzę, że wiesz, co robisz. Niestety, niczego więcej cię nie nauczę.$B$BNa szczęście dla ciebie znam takiego jednego. To goblin i chyba najlepszy kucharz w Kalimdorze.$B$BAno, i tu jest ta zła wiadomość, $gchłopcze:panienko; – musisz się wybrać do Kalimdoru. Ruszaj do Gadżetonu i znajdź Dirge\'a Szybkosieka. On ci pokaże, co i jak.$B', 'Udaj się do Gadżetonu na pustyni Tanaris i porozmawiaj z Dirge\'em Szybkosiekiem o rozwoju swojej kariery kulinarnej.$B', '', '', '', '', '', '', 0),
(6625, 'koKR', 'Oddział urazowy Przymierza', 'Doktor $N, jak mniemam. Miło cię widzieć.$B$BMam dla ciebie wspaniałe wieści! Gustaf VanHowzen, naczelny lekarz Oddziału Urazowego Przymierza, osobiście poprosił, byś $gdołączył:dołączyła; do niego w Theramore. To może być okazja życia! Oddałabym wszystko za szansę nauki u wielkiego doktora Gustafa VanHowzena! Nie zmarnuj tej okazji, $gdoktorze:pani doktor;!', 'Udaj się do Theramore na Pyłowym Bagnisku i porozmawiaj z doktorem Gustafem VanHowzenem o wstąpieniu w szeregi Oddziału Urazowego Przymierza.', '', '', '', '', '', '', 0),
(6721, 'koKR', 'Ścieżka łowcy', 'Witaj, $gmłody łowco:młoda łowczyni;. Wyglądasz mi na kogoś dość wprawnego, by poradzić sobie z bestią i wyszkolić ją na swojego towarzysza.$B$BMusisz odwiedzić Dazalara w Dolanaar. On wskaże ci ścieżkę do zdobycia własnego zwierzęcia.$B', 'Porozmawiaj z Dazalarem w Dolanaar na Teldrassilu.', '', '', '', '', '', '', 0),
(6961, 'koKR', 'Praojciec Mróz przybył!', 'Cudownej Zimowej Uczty, $gprzyjacielu:przyjaciółko;! Koniecznie przywitaj się z Praojcem Mrozem! Jeśli w tym roku $gbyłeś grzeczny:byłaś grzeczna;, w dzień Zimowej Uczty dostaniesz cudowne smakołyki. Nie zapomnij mu powiedzieć, co chcesz dostać w tym roku!$B$BZaopatrz się też w smakołyki dla tych, którzy byli w tym roku grzeczni. Mamy wspaniały wybór. Prosto z naszej farmy na twój talerz – zdrowe smakołyki od Wędzonych Pastwisk!', 'Porozmawiaj z Praojcem Mrozem; znajdziesz go w Orgrimmarze, w pobliżu stoisk Wędzonych Pastwisk.', '', '', '', '', '', '', 0),
(6962, 'koKR', 'Smakołyki dla Praojca Mroza', 'Hej, zrobisz coś dla Praojca Mroza, ee, $gchłopczyku:dziewczynko;?$B$BNie żebym lubił bez potrzeby mówić o sobie w trzeciej osobie, ale Praojciec Mróz siedzi tu cały dzień i sam chętnie by coś przekąsił. Trochę piernikowych ciastek i lodowato zimne mleko do popicia byłyby w sam raz. Pomożesz Praojcu po przyjacielsku i przyniesiesz mi je?', 'Przynieś Praojcu Mrozowi w Orgrimmarze 5 piernikowych ciastek i lodowato zimne mleko.', '', 'Wróć do Praojca Mroza w Orgrimmarze.', '', '', '', '', 0),
(6963, 'koKR', 'Skradzione smakołyki na Zimową Ucztę', 'Słuchaj... nie chcę psuć świątecznej magii, ale Wędzonym Pastwiskom przydałaby się pomoc – taka, z jakiej słyniecie wy, poszukiwacze przygód.$B$BZaginęła nam ważna dostawa smakołyków, która miała uzupełnić nasze zapasy na święta, a teraz zaginął jeszcze agent Wędzonych Pastwisk, którego wysłaliśmy w teren, żeby ją znalazł! Proszę – ostatnie wieści o dostawie przyszły z Gór Alterak i tam właśnie nasz człowiek poszedł jej szukać.$B$BSprawdź, czy jedno i drugie tam jest, całe i zdrowe!', 'Odszukaj agenta Wędzonych Pastwisk, który zaginął w zaśnieżonej części Gór Alterak.', '', '', '', '', '', '', 0),
(6964, 'koKR', 'Prawdziwy sens święta', 'Prezenty, łakocie, podarunki... phi, powiadam!$B$BTe gobliny zatruwają prawdziwe znaczenie tego czasu – Zimowej Uczty. To czas odnowy; ziemia śpi pod kołdrą śniegu przyniesioną przez Praojca Mroza, który NIE jest tym niezdarnym błaznem w czerwonym stroju, o tam!$B$BJeśli chcesz się $gsam:sama; przekonać, o co naprawdę chodzi w Uczcie, zapytaj Sagorne\'a Graniokroka. Pewnie się zdziwi, że kogoś obchodzi historia, a nie prezenty.', 'Porozmawiaj z Sagorne\'em Graniokrokiem w Dolinie Mądrości w Orgrimmarze o Zimowej Uczcie.', '', '', '', '', '', '', 0),
(6983, 'koKR', 'Wredny z ciebie typ...', 'To s-s-stwór zwany „Ohydnym Greenchem” u-u-ukradł naszą dostawę s-s-smakołyków, $N. Ale u-u-uważaj! To on z-z-zamienił mnie w tę ś-ś-śnieżną kupę nieszczęścia!$B$BB-b-będziesz potrzebować p-p-pomocy, żeby stawić mu c-c-czoła. K-k-kręci się wszędzie tam, gdzie ż-ż-żyją yeti; na p-p-pewno gdzieś tu jest! Z-z-znajdź smakołyki, $N, zanieś je z p-p-powrotem do Wędzonych Pastwisk w Orgrimmarze i p-p-powiedz im, że trzeba mnie r-r-rozmrozić!', 'Odszukaj skradzione smakołyki i odnieś je Kaymardowi Miedziogroszowi w Orgrimmarze. Ostatnio miał je podobno Ohydny Greench, który przebywa gdzieś w zaśnieżonej części Gór Alterak.', '', 'Wróć do Kaymarda Miedziogrosza w Orgrimmarze.', '', '', '', '', 0),
(6984, 'koKR', 'Podziękowanie od Wędzonych Pastwisk!', 'My, Wędzone Pastwiska, doceniamy odzyskanie skradzionych smakołyków, $N. Dlatego chcemy ci ofiarować wyjątkowy prezent... a wręczy go nie kto inny, jak sam Praojciec Mróz!$B$BPorozmawiaj, proszę, z Praojcem Mrozem, a przekaże ci prezent na Zimową Ucztę od nas, Wędzonych Pastwisk. Prosto z naszej farmy na twój talerz – to zawsze zdrowe smakołyki od Wędzonych Pastwisk... oczywiście dzięki tobie!', 'Porozmawiaj z Praojcem Mrozem w Orgrimmarze.', '', '', '', '', '', '', 0),
(7022, 'koKR', 'Praojciec Mróz przybył!', 'Cudownej Zimowej Uczty, $gprzyjacielu:przyjaciółko;! Koniecznie przywitaj się z Praojcem Mrozem! Jeśli w tym roku $gbyłeś grzeczny:byłaś grzeczna;, w dzień Zimowej Uczty dostaniesz cudowne smakołyki. Nie zapomnij mu powiedzieć, co chcesz dostać w tym roku!$B$BZaopatrz się też w smakołyki dla tych, którzy byli w tym roku grzeczni. Mamy wspaniały wybór. Prosto z naszej farmy na twój talerz – zdrowe smakołyki od Wędzonych Pastwisk!', 'Porozmawiaj z Praojcem Mrozem; znajdziesz go w Żelaznej Kuźni, w pobliżu stoisk Wędzonych Pastwisk.', '', '', '', '', '', '', 0),
(7025, 'koKR', 'Smakołyki dla Praojca Mroza', 'Hej, zrobisz coś dla Praojca Mroza, ee, $gchłopczyku:dziewczynko;?$B$BNie żebym lubił bez potrzeby mówić o sobie w trzeciej osobie, ale Praojciec Mróz siedzi tu cały dzień i sam chętnie by coś przekąsił. Trochę piernikowych ciastek i lodowato zimne mleko do popicia byłyby w sam raz. Pomożesz Praojcu po przyjacielsku i przyniesiesz mi je?', 'Przynieś Praojcu Mrozowi w Żelaznej Kuźni 5 piernikowych ciastek i lodowato zimne mleko.', '', 'Wróć do Praojca Mroza w Dun Morogh.', '', '', '', '', 0),
(7042, 'koKR', 'Skradzione smakołyki na Zimową Ucztę', 'Słuchaj... nie chcę psuć świątecznej magii, ale Wędzonym Pastwiskom przydałaby się pomoc – taka, z jakiej słyniecie wy, poszukiwacze przygód.$B$BZaginęła nam ważna dostawa smakołyków, która miała uzupełnić nasze zapasy na święta, a teraz zaginął jeszcze agent Wędzonych Pastwisk, którego wysłaliśmy w teren, żeby ją znalazł! Proszę – ostatnie wieści o dostawie przyszły z Gór Alterak i tam właśnie nasz człowiek poszedł jej szukać.$B$BSprawdź, czy jedno i drugie tam jest, całe i zdrowe!', 'Odszukaj agenta Wędzonych Pastwisk, który zaginął w zaśnieżonej części Gór Alterak.', '', '', '', '', '', '', 0),
(7043, 'koKR', 'Wredny z ciebie typ...', 'To s-s-stwór zwany „Ohydnym Greenchem” u-u-ukradł naszą dostawę s-s-smakołyków, $N. Ale u-u-uważaj! To on z-z-zamienił mnie w tę ś-ś-śnieżną kupę nieszczęścia!$B$BB-b-będziesz potrzebować p-p-pomocy, żeby stawić mu c-c-czoła. K-k-kręci się wszędzie tam, gdzie ż-ż-żyją yeti; na p-p-pewno gdzieś tu jest! Z-z-znajdź smakołyki, $N, zanieś je z p-p-powrotem do Wędzonych Pastwisk w Żelaznej Kuźni i p-p-powiedz im, że trzeba mnie r-r-rozmrozić!', 'Odszukaj skradzione smakołyki i odnieś je Wulmortowi Brzęczącej Kieszeni w Żelaznej Kuźni. Ostatnio miał je podobno Ohydny Greench, który przebywa gdzieś w zaśnieżonej części Gór Alterak.$B', '', 'Wróć do Wulmorta Brzęczącej Kieszeni na Placu Wspólnym w Żelaznej Kuźni.', '', '', '', '', 0),
(7045, 'koKR', 'Podziękowanie od Wędzonych Pastwisk!', 'My, Wędzone Pastwiska, doceniamy odzyskanie skradzionych smakołyków, $N. Dlatego chcemy ci ofiarować wyjątkowy prezent... a wręczy go nie kto inny, jak sam Praojciec Mróz!$B$BPorozmawiaj, proszę, z Praojcem Mrozem, a przekaże ci prezent na Zimową Ucztę od nas, Wędzonych Pastwisk. Prosto z naszej farmy na twój talerz – to zawsze zdrowe smakołyki od Wędzonych Pastwisk... oczywiście dzięki tobie!', 'Porozmawiaj z Praojcem Mrozem w Żelaznej Kuźni.', '', '', '', '', '', '', 0),
(7061, 'koKR', 'Zimowa Uczta', 'Proszę – jeśli chcesz dowiedzieć się więcej o Zimowej Uczcie, przeczytaj tę księgę. Choć uważam, że to my właściwie pojmujemy tę legendę, dość długo zgłębiam legendy, by docenić zebranie wszystkich informacji w jednym źródle.$B$BGdy skończysz, zanieś księgę Kairnowi Krwawemu Kopytu do Gromowych Urwisk. Wiem na pewno, że chętnie usłyszy, że inni interesują się podaniami naszego ludu.', 'Możesz przeczytać księgę „Zimowa Uczta”, by dowiedzieć się więcej o tym święcie. Gdy skończysz, dostarcz ją Kairnowi Krwawemu Kopytu w Gromowych Urwiskach.', '', '', '', '', '', '', 0),
(7062, 'koKR', 'Prawdziwy sens święta', 'Upominki, łakocie, prezenty... phi, powiadam!$B$BTe gobliny kalają prawdziwy sens tego święta – Zimowej Uczty. To czas odnowy; ziemia drzemie pod śnieżną pierzyną, którą przynosi Praojciec Mróz – a to NIE jest ten niezdarny błazen w czerwonym stroju, o tam!$B$BJeśli chcesz $gsam:sama; się dowiedzieć, o co naprawdę chodzi w Uczcie, zapytaj historyka Karnika w Lidze Odkrywców. Na pewno się zdziwi, że ktoś interesuje się historią, a nie dostawaniem prezentów.', 'Porozmawiaj z historykiem Karnikiem w Lidze Odkrywców w Żelaznej Kuźni o Zimowej Uczcie.', '', '', '', '', '', '', 0),
(7063, 'koKR', 'Zimowa Uczta', 'Proszę – jeśli chcesz dowiedzieć się więcej o Zimowej Uczcie, przeczytaj tę księgę. Choć uważam, że to nasze rozumienie legendy jest właściwe, jestem na tyle uczonym, by docenić zebranie wszystkich informacji w jednym źródle.$B$BGdy skończysz, zanieś księgę królowi Magniemu Miedziobrodemu. Wiem na pewno, że chętnie usłyszy, iż inni zainteresowali się dawnymi legendami.', 'Możesz przeczytać księgę „Zimowa Uczta”, by dowiedzieć się więcej o tym święcie. Gdy skończysz lekturę, dostarcz księgę królowi Magniemu Miedziobrodemu w Żelaznej Kuźni.', '', '', '', '', '', '', 0),
(7261, 'koKR', 'Królewski nakaz', 'Toczymy brutalną bitwę w dolinach Alterak. Dziki Klan Mroźnego Wilka rzuca wyzwanie potędze Gromdardów! Trzeba ich wytępić w imię króla Magniego Miedziobrodego! Zajęcie, oczyszczenie i przejęcie tej ziemi to suwerenny i terytorialny imperatyw królestwa Żelaznej Kuźni.$B$BNiestety, żołnierze nie rosną na drzewach! Zamelduj się u porucznika Haggerdina przed Doliną Alterak, by rozpocząć służbę i zdobywać chwałę w szeregach Gromdardów.', 'Udaj się do Doliny Alterak w Międzygórzu. Przed tunelem wejściowym odszukaj porucznika Haggerdina i porozmawiaj z nim.$B$BKu chwale Miedziobrodego!', '', '', '', '', '', '', 0),
