INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES
(182, 'koKR', 'Szanowni koledzy i poszukiwacze prawdy\n\nWykopaliska trwają, ale spowalniają je troggi, o których wspominałem w ostatnim raporcie. Jestem pewien, że damy sobie z nimi radę, choć niektóre z tych troggów są agresywniejsze niż zwykle.\n\nOstatnio znaleźliśmy kolejne artefakty, jednak we wszystkich przypadkach poza jednym (o którym piszę niżej)\n nowe znaleziska są tej samej klasy co poprzednie – ciekawe, choć niewiele wyjaśniają.', 0),
(183, 'koKR', 'Jest jeden wyjątek. Osobliwie rzeźbione posążki, które niedawno znaleźliśmy (krótko opisałem je w ostatnim raporcie), zdają się wpływać na troggi na wykopaliskach. Kamienne rzeźby je przyciągają, a niektóre troggi wpadają przez nie w szał!\n\nZanim wyciągniemy jakiekolwiek wnioski na temat tych posążków, potrzeba dalszych badań, ale wciąż mam nadzieję, że rzucą one światło na związek między troggami a tytanami.', 0),
(184, 'koKR', 'Na koniec muszę ponowić prośbę o proch strzelniczy. Moje zapasy są na wyczerpaniu, co poważnie utrudnia postęp wykopalisk. Zapewniono mnie, że nowa dostawa prochu jest w drodze, ale dotąd jej nie otrzymałem.\n\nCzy mogę zapytać, skąd to opóźnienie?\n\nZ wyrazami szacunku\nposzukiwacz Darteus Ironband', 0),
(248, 'koKR', 'Pozdrowienia, Mistrzu,\n\nwybacz mi sposób, w jaki przesyłam tę wiadomość. Moi magowie cienia w Alterak są pochłonięci swoimi zadaniami, więc muszę posłużyć się obcym posłańcem – zwerbowanym spośród naszych nowych „sojuszników” – by dostarczyć Ci ten raport. Zaszyfrowałem jednak ten list jednym z naszych najbardziej tajemnych szyfrów. Jego słowa są bezpieczne przed tymi prostakami.', 0),
(257, 'koKR', 'Nasze plany postępują pomyślnie. Jak wspominałem, zawarliśmy przymierze z grupą ludzi, którzy nazywają siebie Syndykatem. Jego przywódcy byli niegdyś szlachtą Alterak i pragną znów sprawować tu władzę.\n\nZawarli więc z nami układ. Układ, którego pożałują.', 0),
(258, 'koKR', 'Dziś Syndykat ma na tych ziemiach niewielką władzę, ale dobrze zna okolicę i zebrał dość ludzi do zadań, które nas czekają. Przy właściwym prowadzeniu jestem pewien, że wkrótce Syndykat znów będzie rządził królestwem Alterak.\n\nPonadto nakłoniliśmy Syndykat, by obrał za cel miasto Stromgard na pobliskich Wyżynach Aratorskich. Miasto jest polem bitwy między naszymi siłami, ogrami i ludźmi ze Stromgardu, lecz sądzimy, że dzięki rozważnej taktyce zawładniemy tym niegdyś wspaniałym miastem.', 0),
(259, 'koKR', 'A gdy to się dokona, będzie mógł się rozpocząć kolejny etap naszego planu. Mając własne państwo i ośrodek władzy w tym regionie, przygotujemy drogę dla Trzeciego Zastępu.\n\nWkrótce Władcy Legionu nagrodzą nasze dzieło, znów zsyłając ogień z nieba!', 0),
(315, 'koKR', 'Rada postąpiła mądrze, stawiając Cię na czele Czuwania Argusa i powierzając Ci kierowanie jego strategią w krainie ludzi i krasnoludów. A ja mam zaszczyt być wykonawcą Twojej woli w Alterak.\n\nW imię Sargerasa\n	\nNagaz, \nhierofanta Argusa', 0),
(317, 'koKR', 'Dun Modr na Bagniskach$B$BMoja droga Saro,$B$Bwszystko wskazuje na to, że za kilka dni wyruszymy, by objąć straż nad Mostem Thandol. Na wypadek gdybym nie mógł już więcej do Ciebie napisać, czuję potrzebę skreślenia kilku słów, które trafią przed Twoje oczy, gdy mnie już nie będzie.', 0),
(318, 'koKR', 'Nasze zadanie może potrwać kilka dni i upłynąć przyjemnie, a może też oznaczać zaciekłą walkę i dla mnie śmierć. Jeśli będzie trzeba, bym poległ na polu bitwy za Przymierze, jestem gotów.$B$BNie mam żadnych wątpliwości ani braku wiary w sprawę, której służę, a moja odwaga nie słabnie ani się nie chwieje.', 0),
(319, 'koKR', 'Wiem, jak bardzo Królestwo Żelaznej Kuźni polega na zwycięstwie Przymierza i jak wielki dług mamy wobec tych, którzy szli przed nami przez krew i cierpienie Wielkich Wojen. Jestem gotów, w pełni gotów złożyć w ofierze wszystkie radości tego życia, by pomóc utrzymać to Przymierze i spłacić ten dług.', 0),
(320, 'koKR', 'Saro, moja miłość do Ciebie jest nieśmiertelna. Zdaje się wiązać mnie potężnymi linami, których nic poza Wszechmocą nie zdoła zerwać, a miłość do Królestwa ogarnia mnie jak silny wiatr i nieodparcie niesie mnie wraz z tymi wszystkimi łańcuchami na pole bitwy.', 0),
(321, 'koKR', 'Wspomnienia wszystkich błogich chwil, które z Tobą spędziłem, ogarniają mnie, a ja czuję najgłębszą wdzięczność dla Światłości i dla Ciebie, że mogłem cieszyć się nimi tak długo. Jakże trudno mi z nich zrezygnować i spalić na popiół nadzieje przyszłych lat, gdy moglibyśmy jeszcze razem żyć i kochać się, i patrzeć, jak nasi synowie wyrastają wokół nas na honorowych krasnoludów.', 0),
(322, 'koKR', 'Wiem, że mam niewiele i niewielkie prawa do Boskiej opatrzności, lecz coś mi szepcze – może to niesiona wiatrem modlitwa mojego małego Edgara – że wrócę do moich ukochanych cały i zdrowy. Jeśli nie wrócę, moja droga Saro, nigdy nie zapominaj, jak bardzo Cię kocham, a gdy na polu bitwy uleci ze mnie ostatni oddech, wyszepczę Twoje imię.$B$BWybacz mi moje liczne wady i wszystkie cierpienia, jakie Ci sprawiłem. Jakże często byłem bezmyślny, jakże często głupi.', 0),
(323, 'koKR', 'Jakże chętnie zmyłbym łzami każdą najmniejszą plamkę z Twojego szczęścia i zmagał się ze wszystkimi nieszczęściami tego świata, by osłonić Ciebie i nasze drogie dzieci przed krzywdą.$B$BAle nie mogę.$B$BBędę musiał patrzeć na Ciebie z Wypaczonej Otchłani i unosić się przy Tobie, gdy będziesz stawiać czoło burzom ze swoim drogocennym małym brzemieniem, i czekać ze smutną cierpliwością, aż spotkamy się, by nigdy się już nie rozstać.', 0),
(332, 'koKR', 'Ale, och, Saro, jeśli zmarli mogą wracać do Azeroth i niewidzialni krążyć wokół tych, których kochają, zawsze będę przy Tobie – w najradośniejszy dzień i w najciemniejszą noc, w najszczęśliwszych chwilach i najposępniejszych godzinach, zawsze, zawsze. A jeśli poczujesz na policzkach łagodny powiew, będzie to mój oddech; gdy chłodne powietrze owieje Twoje pulsujące skronie, będzie to mój duch przechodzący obok.$B$BSaro, nie opłakuj mnie jak zmarłego. Myśl, że odszedłem i czekam na Ciebie, bo znów się spotkamy.$B$B– Sully', 0),
(333, 'koKR', 'Do mojego Czcigodnego Króla:$B$BNie przystoi żonie prostego żołnierza kwestionować czynów tak wielkich przywódców jak Ty, panie. Bitwy, które szaleją na naszych ziemiach, toczy się po to, by ocalić wspaniałe życie, które znamy i kochamy – od chłodnych wód Loch Modan po rześkie, ośnieżone szczyty Dun Morogh.', 0),
(334, 'koKR', 'Lecz jaką cenę przyjdzie zapłacić za wojny, które toczymy w imię ocalenia? Po śmierci którego z poległych żołnierzy zrozumiemy, że samo życie, które chcemy ocalić, wymyka się nam na polu bitwy?$B$BPod ile mieczy i toporów musimy rzucić naszą przyszłość? Pod iloma stopami rozmokłej ziemi musimy pogrzebać naszą przeszłość?', 0),
(335, 'koKR', 'Nie przystoi żonie prostego żołnierza zadawać takich pytań.$B$BA jednak piszę teraz do Ciebie jako wdowa po prostym żołnierzu. Dla Ciebie mój mąż mógł być jednym z tysięcy żołnierzy w szeregach. Dla mnie był wielkim Sullym Balloo, ojcem moich dzieci i moim jedynym towarzyszem w tym życiu.$B$BWybacz, jeśli moje pytania, o wielki przywódco, brzmią niestosownie. Ale zmarli nie mogą sami zadać tych pytań...$B$BTwoja wierna poddana$BSara Balloo', 0),
(372, 'koKR', 'Gwiazda Xil\'yeh$B$BGwiazdę ma Grel\'borg Skąpiec. To chciwy ogr, który całymi dniami przeszukuje Ruiny Alterak w Górach Alterak w poszukiwaniu błyskotek. Większość jego zbiorów jest bezwartościowa, ale jeden przedmiot, Gwiazda Xil\'yeh, ma cenne właściwości.', 0),
(373, 'koKR', 'Ręka Daguna$B  $BPradawne teksty głoszą, że szpony Daguna wydzielają truciznę, która nie zabija ofiary, lecz przemienia ją w coś innego – w przedstawiciela dawnych ras. Jej wartość dla nas jest bezsprzeczna.$B$BDagun żyje w głębinach morza, ale plemię murloków z Bagnopłetwych na Pyłowym Bagnisku regularnie wabi go na powierzchnię. Ich wyrocznie przywołują go zaczarowanym wodorostem morskim. Jeśli zabijesz dość wyroczni, znajdziesz wodorost. Połóż go wtedy na ołtarzu murloków, a Dagun przybędzie.', 0),
(374, 'koKR', 'Serce dziedzictwa$B$BMogh Nieumierający to trollowy szaman-znachor w Dolinie Cierniodławów. Posiada Serce dziedzictwa, które podobno odpędza śmierć od tych, którzy zdołają poznać jego tajemnice. Mogha znajdziesz w Ruinach Zul\'Mamwe. Pokonaj go, jeśli zdołasz, i przynieś mi Serce dziedzictwa.', 0),
(375, 'koKR', 'Przynieś mi te trzy przedmioty – Gwiazdę, Rękę i Serce – a Kompendium Yagyina będzie twoje.$B$B– G.B.', 0),
(575, 'koKR', 'Nikt nie wie dokładnie, jak powstał wszechświat. Niektórzy twierdzą, że katastrofalny kosmiczny wybuch rozrzucił nieskończone światy w bezmiar Wielkiej Ciemności – światy, na których pewnego dnia miały się zrodzić formy życia o cudownej i przerażającej różnorodności. Inni wierzą, że wszechświat, taki, jaki istnieje, został stworzony w całości przez jedną, wszechmocną istotę.', 0),
(576, 'koKR', 'Choć dokładne początki chaotycznego wszechświata pozostają niejasne, jasne jest, że powstała rasa potężnych istot, by zaprowadzić ład na rozmaitych światach i zapewnić bezpieczną przyszłość istotom, które miały pójść w ich ślady.$B$BTytani, kolosalni bogowie o metalicznej skórze z najdalszych zakątków kosmosu, przybyli i zabrali się do pracy nad napotkanymi światami. Kształtowali oblicze swoich światów, wznosząc potężne góry i wydrążając rozległe morza.', 0),
(577, 'koKR', 'Tchnęli w istnienie niebiosa i szalejące atmosfery – wszystko w ramach swego niezgłębionego, dalekosiężnego planu stworzenia ładu z chaosu. Obdarzali nawet mocą prymitywne rasy, by te doglądały ich dzieł i strzegły spójności swoich światów.$B$BTytani, rządzeni przez elitarny krąg zwany Panteonem, w pierwszych epokach stworzenia zaprowadzili ład na stu milionach światów rozsianych po Wielkiej Ciemności.', 0),
(578, 'koKR', 'Dobrotliwy Panteon, pragnąc ochronić swoje uporządkowane światy, zawsze czuwał przed groźbą ataku ze strony plugawych, pozawymiarowych istot z Wypaczonej Otchłani. Otchłań, eteryczny wymiar chaotycznej magii łączący ze sobą niezliczone światy wszechświata, była domem nieskończonej liczby złowrogich, demonicznych istot, które pragnęły jedynie niszczyć życie i pożerać energię żywego wszechświata.', 0),
(794, 'koKR', 'Nasz świat kipi historią. Historią ras nowych i starych. Historią dawno zakończonych wojen i tych, które wciąż się tlą.\n\nHistorią bogów, którzy przybyli z nieba. I historią starszych bogów, którzy śpią w ziemi.\n\nMówię teraz o tych istotach – o Przedwiecznych. O tych, którzy żyli i szaleli w Azeroth, gdy świat był młody.', 0),
(795, 'koKR', 'Przedwieczni są wolą naszego świata. W każdej burzy ryczy śmiech Przedwiecznego. Płomień pożaru to żar ich spojrzenia. Gdy Przedwieczni kroczą, ziemia drży i pęka, a pomniejsze istoty krzyczą i w rozpaczy rozdzierają własne ciało.\n\nI słusznie rozpaczają, bo tak jak ogień nie zna litości dla ciekawskiej rączki dziecka, tak Przedwieczni nie dbają o tych, którzy stoją niżej od nich. W najlepszym razie jesteśmy pionkami. W najgorszym – zabawkami.', 0),
(796, 'koKR', 'Byli pierwszymi panami świata i rządzili siłą i grozą. Choć teraz są spętani i śpią, ich słudzy wciąż krążą po świecie, a my, mali i słabi śmiertelnicy, nie dorównamy im siłą.\n\nCi, którzy próbują, zostają pożarci. Lecz ci, którzy znają swoje miejsce, którzy klękają w pokorze przed sługami Przedwiecznych, którzy dobrowolnie poświęcają umysł i duszę... tylko oni znajdą łaskę.', 0),
(797, 'koKR', 'Aku\'mai, Księżniczka Głębin, służy Przedwiecznym. Mieszka w Czarnych Głębinach i błogosławi ich pieczary swoją pradawną mądrością. Sprowadzona do Głębin przez dawniejszych śmiertelników, Aku\'mai jest symbolem boskości. Ma zaledwie okruch mocy i dzikości Przedwiecznych, a mimo to jej moc jest niezmierzona.\n\nDlatego czczą ją. Boją się jej i ją kochają.\n\n\n– Lorgalis', 0),
(871, 'koKR', '$N,$BZanim przejdę dalej, pozwól, że jeszcze raz podziękuję ci za wszystko, co $gzrobiłeś:zrobiłaś; dla mnie i mojej żony. $GUratowałeś:Uratowałaś; jej życie i za to jestem ci winien o wiele więcej, niż zdołałbym spłacić w stu żywotach. Ona jest dla mnie wszystkim. Gdyby umarła... cóż, nie wiem, co bym zrobił.$B$BOto lista rzeczy, które musisz zdobyć, jeśli mam wykuć dla ciebie świętą broń. Ułożyłem je od najłatwiejszej do najtrudniejszej – mam nadzieję, że to ci ułatwi sprawę.', 0),
(872, 'koKR', 'Porządne drewno białokamiennego dębu – zanim kopalnie pod Księżycowym Potokiem w Zachodnim Skraju zostały zajęte, było tam pod dostatkiem tego drewna. Używano go do budowy ważniejszych rusztowań i narzędzi, bo jest odporne na żar i nacisk.$B$BSprowadzono je tam statkiem skądś zza morza. To rzadkie drewno, wystarczająco mocne, by posłużyć do wykucia twojej broni. Jeśli coś z niego zostało w kopalniach, muszą je mieć goblińscy snycerze.', 0),
(873, 'koKR', 'Oczyszczona ruda – w Thelsamarze mieszka krasnolud, kowal, u którego przez jakiś czas się szkoliłem, Bailor Kamiennoręki. Wytwarza bardzo szczególny stop, który moim zdaniem idealnie nada się do twojej broni. Spodziewałem się, że przesyłka tego stopu dotrze, gdy byłem w Żelaznej Kuźni, ale dotąd nie mam od niego żadnych wieści.$B$BOdszukaj go i dowiedz się, co z przesyłką. A jeśli nie ma go już w Loch Modan, chciałbym przynajmniej wiedzieć, co się stało z moim starym nauczycielem.', 0),
(874, 'koKR', 'Kowalski młot – przed nadejściem Zarazy i zdradą Arthasa mieszkałem w miasteczku zwanym Stosowym Lasem, w głębi pięknego Srebrzystego Boru. Las nie jest już nawet w połowie tak piękny jak niegdyś, a twierdza, w której poznałem tajniki stali, dawno już stała się zepsuta i plugawa, opanowana przez istoty o niewyobrażalnym złu.$B$BGdy razem z żoną uciekaliśmy z miejsca, które dziś zwie się Twierdzą Cienistego Kła, zostawiliśmy tam część naszych najcenniejszych rzeczy.', 0),
(875, 'koKR', 'Wśród nich kowalski młot, który dał mi ojciec. W młodości w to wątpiłem, ale on zawsze powtarzał, że młot jest zaczarowany. To ostatnia pamiątka, jaka mi po nim została, zanim zginął z rąk Plagi.$B$BPrzynieś mi mój młot, $N, żebym mógł skupić w nim swoją pasję. Jeśli naprawdę jest zaczarowany, tym lepiej dla nas obojga.$B$BZostawiłem go w stajniach na głównym dziedzińcu twierdzy. Chyba że tamtejsze stwory same wzięły się za kowalstwo – wtedy pewnie wciąż tam leży.', 0),
(876, 'koKR', 'Klejnot Kor – z opowieści, które słyszałem, wynika, że niektórzy rzucający czary używają tych klejnotów do gromadzenia energii dla swojej magii, co czyni ją jeszcze groźniejszą. Nocny elf, któremu kiedyś pomogłem, Thundris Tkacz Wiatru, powie ci więcej, skoro będziesz występować w moim imieniu. Sądzę, że energię zgromadzoną w takim klejnocie da się wykorzystać przy tworzeniu twojej broni.$B$BGdy ostatnio rozmawialiśmy, Thundris przebywał w Auberdine, osadzie w głębi Mrocznego Wybrzeża – skażonego lasu ciągnącego się wzdłuż wybrzeża w cieniu ojczyzny nocnych elfów.', 0),
(877, 'koKR', 'Klejnot Kor – z opowieści, które słyszałem, wynika, że niektórzy rzucający czary używają tych klejnotów do gromadzenia energii dla swojej magii, co czyni ją jeszcze groźniejszą. Nocny elf, któremu kiedyś pomogłem, Thundris Tkacz Wiatru, powie ci więcej, skoro będziesz występować w moim imieniu. Sądzę, że energię zgromadzoną w takim klejnocie da się wykorzystać przy tworzeniu twojej broni.$B$BGdy ostatnio rozmawialiśmy, Thundris przebywał w Auberdine, osadzie w głębi Mrocznego Wybrzeża – skażonego lasu ciągnącego się wzdłuż wybrzeża w cieniu ojczyzny nocnych elfów.', 0),
(951, 'koKR', '(Przez plamy da się odczytać tylko fragmenty dziennika).$B$BUldaman, dzień 3$B$BNie mogę uwierzyć, jak głupio postąpiłem. Dać się zaskoczyć plugawym krasnoludom z Cienistej Kuźni – to błąd godny nowicjusza. Rany goją się powoli; na pewno jestem otruty. Czuję, jak uchodzą ze mnie siły. Mimo to muszę iść na zwiady...$B$B...co gorsza, naszyjnik, który zrobił dla mnie gnom, został strzaskany! Trzy największe osadzone w nim klejnoty przepadły. Muszę je odnaleźć; bez nich naszyjnik jest bezużyteczny...', 0),
(971, 'koKR', 'Uldaman, dzień 4$B$B...pierwszy trop odnalazł się w głębi Uldamanu: jeden z najdzikszych troggów, jakie kiedykolwiek widziałem, wymachiwał wielkim szafirem – założę się, że idealnie pasowałby do naszyjnika. Podsłuchałem, jak jeden z krasnoludów z Cienistej Kuźni wymienia imię bestii: Grimlok. Jednak oddział strażników, którym otacza się ten brutal Grimlok...', 0),
(972, 'koKR', 'Uldaman, dzień 5$B$B...a potem trogg, zabrawszy topaz swoim zabitym „pobratymcom”, pomaszerował do bocznej jaskini niedaleko wejścia do sali...$B$B...szybko włożył topaz do dużej, rzucającej się w oczy urny z tyłu komnaty...$B$B...ze wszystkich możliwych – krasnoludy! I to aż trzy. Obecnie bronią się za barykadą przed troggami. Zawołać ich byłoby samobójstwem, bo w tym osłabionym stanie zalałyby mnie plugawe troggi. Ale gdy już się dowiem, gdzie jest trzeci klejnot...', 0),
(973, 'koKR', 'Uldaman, dzień 6$B$B...taki głodny. Skończyły mi się zapasy, a teraz nawet spleśniały chleb byłby dla mnie ucztą. Widziałem na własne oczy, jak głowa trogga zamienia się w soczysty stek...', 0),
(974, 'koKR', 'Uldaman, dzień 7$B$B...ostatnia szansa, by odkupić moje porażki. Sądzę, że rubin jest w ostatniej zabarykadowanej części, w której krasnoludy bronią się przed troggami. Ich walki – bez wątpienia o klejnoty i inne artefakty z tego miejsca – trwają bez przerwy. To by pasowało do tych podłych krasnoludów, żeby tam go ukryć. Tak czy inaczej, muszę coś zrobić. Może najlepiej będzie rzucić się do szaleńczej ucieczki na powierzchnię...', 0),
(1231, 'koKR', 'Niniejszy dowód czynu potwierdza, że $n $gzabił:zabiła; Margola Szaleńca, postrach Płonącego Wąwozu.$B$BMuzeum Żelaznej Kuźni uznaje to osiągnięcie i dziękuje okazicielowi za hojny wkład.$B$B– Główny kustosz Thorius Kamieniostróż', 0),
(1591, 'koKR', 'To kowadło należy do Jordana Stilwella – proszę NIE używać!$B$B– Jordan', 0),
(1751, 'koKR', 'Szczątki olbrzymiego czerwonego smoka znaleziono na Bagniskach wkrótce po Bitwie o Grim Batol. Tyrannistrasz był podobno starszym małżonkiem Smoczej Królowej, Alexstrazy.', 0),
(1752, 'koKR', 'Ten skamieniały szpon znaleziono u południowych wybrzeży Doliny Cierniodławów. Ekolodzy sądzą, że należał do pradawnego słonecznego ptaka roka. Choć stworzenia te zajmują ważne miejsce w pierwotnych cyklach mitów taurenów, istnienie tego szponu sugeruje, że kiedyś naprawdę żyły.', 0),
(1753, 'koKR', 'Geru, największe z biegusów, są nieliczne i rzadko spotykane.', 0),
(1754, 'koKR', 'To pomniejszona replika szkieletu Zgrzytozęba. Ten legendarny baran był cudem Khaz Modan i bohaterem wielu opowieści krasnoludzkiego folkloru. Do dziś ekolodzy nie potrafią wyjaśnić jego niezwykłych rozmiarów ani wytrzymałości.', 0),
(1755, 'koKR', 'To jajo, znalezione w odległym lesie deszczowym Krateru Un\'Goro, kryło niegdyś zarodek diabłozaura. Materiał genetyczny tego gada okazał się bezcenny dla ekologów Ligi, którzy są bliżej niż kiedykolwiek opracowania surowicy na wyniszczający jad diabłozaurów.', 0),
(1756, 'koKR', 'Ten nienaruszony szkielet pteradona wydobyto w odległym Kraterze Un\'Goro. Z budowy szkieletu jasno wynika, że tego rodzaju dotąd nie spotkano. Szkielet mógł przetrwać pod żyzną glebą tego regionu przez dowolnie wiele stuleci.', 0),
(1757, 'koKR', 'To działające astrolabium, wydobyte z podmorskich ruin Suramaru, wykonali Wysoko Urodzeni spośród nocnych elfów blisko dwanaście tysięcy lat temu. Wysoko Urodzeni, zafascynowani magią, okultyzmem i astronomią, opracowali szereg pomysłowych przyrządów. To urządzenie daje bezcenny wgląd w poziom wiedzy naukowej dawnych nocnych elfów.', 0),
(1758, 'koKR', 'Te pradawne naczynia gliniane wydobyto podczas wykopalisk w Uldamanie. Choć nie ma na nich wiele wymownych run czy hieroglifów, dają wyraźny obraz rzemiosła i codziennych sprzętów dawnej rasy krasnoludów.', 0),
(1759, 'koKR', 'Te rzeźbione płyty reliefowe były być może najważniejszym znaleziskiem w pierwszych komnatach Uldamanu. Ryciny wyraźnie wskazują na związek między podobnymi do golemów ziemnymi a rasą krasnoludów. Jeśli pojawią się dalsze dowody, teorie o naszym rzekomym stworzeniu przez mitycznych tytanów mogą okazać się prawdziwe.', 0),
(1760, 'koKR', 'To osobliwe jajo, znalezione na spieczonych pustkowiach pustyni Tanaris, pozostaje dla współczesnych ekologów zagadką. Badania wieku sugerują, że może mieć nawet tysiąc lat. Choć pewne cechy wskazują na budowę owadzią, jego prawdziwego pochodzenia nie sposób ustalić. Gatunek, który składa tak charakterystyczne jaja, wciąż czeka na odkrycie.', 0),
(1761, 'koKR', 'Ta pozostałość z Drugiej Wojny jest poruszającym przypomnieniem, jak niebezpiecznie blisko była Horda zdobycia Góry Żelaznej Kuźni.', 0),
(1787, 'koKR', 'Nieświadomi, że Sargeras dąży do zniweczenia ich niezliczonych dzieł, tytani wędrowali dalej od świata do świata, kształtując i porządkując każdą planetę tak, jak uznali za stosowne. Podczas tej wędrówki natrafili na mały świat, który jego mieszkańcy mieli później nazwać Azeroth.', 0),
(1788, 'koKR', 'Gdy tytani przemierzali pierwotne krainy, napotkali wiele wrogich istot żywiołów. Żywiołaki te, które czciły rasę niepojęcie złych istot znanych jedynie jako Przedwieczni, poprzysięgły odepchnąć tytanów i uchronić swój świat przed metalicznym dotykiem najeźdźców.', 0),
(1789, 'koKR', 'Panteon, zaniepokojony skłonnością Przedwiecznych do zła, wypowiedział wojnę żywiołakom i ich mrocznym panom. Armiami Przedwiecznych dowodzili najpotężniejsi żywiołakowi porucznicy: Ragnaros Władca Ognia, Therazane Kamienna Matka, Al\'Akir Władca Wiatrów i Neptulon Łowca Przypływów.', 0),
(1790, 'koKR', 'Ich chaotyczne siły szalały po całym świecie i ścierały się z kolosalnymi tytanami. Choć żywiołaki były potężne ponad śmiertelne pojęcie, ich połączone siły nie zdołały powstrzymać potężnych tytanów. Jeden po drugim władcy żywiołów padali, a ich wojska się rozpraszały.', 0),
(1791, 'koKR', 'Panteon zburzył cytadele Przedwiecznych i spętał pięciu złych bogów głęboko pod powierzchnią świata. Bez mocy Przedwiecznych, która wiązała ich szalejące duchy ze światem fizycznym, żywiołaki zostały wygnane na otchłanny plan, gdzie miały walczyć ze sobą przez całą wieczność. Po odejściu żywiołaków natura się uspokoiła, a świat osiadł w pokojowej harmonii. Tytani uznali, że zagrożenie zostało powstrzymane, i zabrali się do pracy.', 0),
(1792, 'koKR', 'Tytani obdarzyli mocą kilka ras, by pomogły im kształtować świat. Aby pomogli im drążyć niezgłębione jaskinie pod ziemią, tytani stworzyli z magicznego, żywego kamienia podobnych do krasnoludów ziemnych. Aby pomogli im wydrążyć morza i wydźwignąć ląd z dna morskiego, tytani stworzyli ogromnych, lecz łagodnych morskich olbrzymów. Przez wiele epok tytani przesuwali i kształtowali ziemię, aż w końcu pozostał jeden doskonały kontynent.', 0),
(1793, 'koKR', 'W sercu kontynentu tytani stworzyli jezioro skrzących się energii. Jezioro, które nazwali Studnią Wieczności, miało być źródłem życia dla świata. Jego potężne energie miały karmić kości świata i pozwolić życiu zapuścić korzenie w żyznej glebie. Z czasem na pierwotnym kontynencie zaczęły się rozwijać rośliny, drzewa, potwory i stworzenia wszelkiego rodzaju.', 0),
(1794, 'koKR', 'Gdy o zmierzchu dobiegł końca ostatni dzień ich trudów, tytani nazwali kontynent Kalimdorem – „krainą wiecznego światła gwiazd”.', 0),
(1795, 'koKR', 'Przekonani, że mały świat został uporządkowany, a ich praca dobiegła końca, tytani przygotowali się do opuszczenia Azeroth. Zanim jednak odeszli, powierzyli najwspanialszym gatunkom świata zadanie czuwania nad Kalimdorem, by żadna siła nie zagroziła jego doskonałemu spokojowi. W tamtej epoce istniało wiele smoczych stad.', 0),
(1796, 'koKR', 'Pięć stad miało jednak władzę nad swoimi pobratymcami. To właśnie te pięć stad tytani wybrali, by roztoczyły pieczę nad rodzącym się światem. Najwięksi członkowie Panteonu przekazali cząstkę swojej mocy przywódcom każdego ze stad. Te majestatyczne smoki (wymienione poniżej) stały się znane jako Wielkie Aspekty, czyli Smocze Aspekty.', 0),
(1797, 'koKR', 'Aman\'Thul, Najwyższy Ojciec Panteonu, przekazał cząstkę swojej kosmicznej mocy ogromnemu brązowemu smokowi, Nozdormu. Najwyższy Ojciec powierzył Nozdormu straż nad samym czasem i pieczę nad wiecznie wirującymi ścieżkami losu i przeznaczenia. Stoicki, honorowy Nozdormu stał się znany jako Ponadczasowy.', 0),
(1798, 'koKR', 'Eonar, tytaniczna patronka wszelkiego życia, oddała cząstkę swojej mocy czerwonemu lewiatanowi, Alexstrazie. Odtąd Alexstraza miała być znana jako Życiodajna i strzec wszystkich żywych istot na świecie. Z powodu jej najwyższej mądrości i bezgranicznego współczucia dla wszystkiego, co żyje, Alexstrazę ukoronowano na Smoczą Królową i dano jej władzę nad jej rodzajem.', 0),
(1799, 'koKR', 'Eonar pobłogosławiła także młodszą siostrę Alexstrazy, smukłą zieloną smoczycę Yserę, cząstką władzy nad naturą. Ysera zapadła w wieczny trans, związana z jawnym Snem Stworzenia. Znana jako Śniąca, miała czuwać nad rozrastającymi się dziczami świata ze swojej zielonej krainy – Szmaragdowego Snu.', 0),
(1800, 'koKR', 'Norgannon, tytaniczny strażnik wiedzy i mistrz magii, obdarzył błękitnego smoka Malygosa cząstką swojej ogromnej mocy. Odtąd Malygos miał być znany jako Tkacz Zaklęć, strażnik magii i ukrytych tajemnic.', 0),
(1801, 'koKR', 'Khaz\'goroth, tytaniczny kształtujący i kowal świata, przekazał część swojej ogromnej mocy potężnemu czarnemu smokowi Neltharionowi. Wielkoduszny Neltharion, znany odtąd jako Strażnik Ziemi, otrzymał władzę nad ziemią i głębinami świata. Uosabiał siłę świata i był największym sojusznikiem Alexstrazy.', 0),
(1802, 'koKR', 'Tak wzmocnionym Pięciu Aspektom powierzono obronę świata pod nieobecność tytanów. Gdy smoki były gotowe strzec ich dzieła, tytani na zawsze opuścili Azeroth. Niestety, była to tylko kwestia czasu, aż Sargeras dowie się o istnieniu nowo narodzonego świata...', 0),
(1865, 'koKR', 'Gdy wysokie elfy walczyły o życie z zaciekłym natarciem trolli, rozproszeni, koczowniczy ludzie z Lordaeronu walczyli o scalenie własnych ziem plemiennych. Plemiona wczesnej ludzkości napadały na swoje osady, nie zważając na jedność rasy ani na honor.', 0),
(1866, 'koKR', 'Jedno plemię, znane jako Arathi, dostrzegło jednak, że trolle stają się zbyt wielkim zagrożeniem, by je lekceważyć. Arathi chcieli poddać swojej władzy wszystkie plemiona, by mogły stawić trollowym hordom wojennym zjednoczony opór.', 0),
(1867, 'koKR', 'W ciągu sześciu lat przebiegli Arathi przechytrzyli i pokonali rywalizujące plemiona. Po każdym zwycięstwie oferowali podbitym pokój i równość; w ten sposób zdobywali lojalność pokonanych. Z czasem plemię Arathi objęło wiele różnych plemion, a szeregi jego armii ogromnie się rozrosły.', 0),
(1868, 'koKR', 'Przekonani, że poradzą sobie z trollowymi hordami wojennymi, a w razie potrzeby nawet z odludkami elfami, wodzowie Arathi postanowili wznieść potężne miasto-twierdzę w południowych rejonach Lordaeronu. Miasto-państwo, nazwane Stromem, stało się stolicą aratorskiego narodu – Aratoru. Gdy Arator rozkwitał, ludzie z całego rozległego kontynentu wędrowali na południe, pod opiekę i ochronę Stromu.', 0),
(1869, 'koKR', 'Zjednoczone pod jednym sztandarem ludzkie plemiona rozwinęły silną, optymistyczną kulturę. Thoradin, król Aratoru, wiedział, że tajemnicze elfy z północnych krain są nieustannie oblegane przez trolle, ale nie chciał narażać bezpieczeństwa swego ludu w obronie stroniących od świata obcych. Mijały miesiące, a z północy docierały pogłoski o rzekomej klęsce elfów. Dopiero gdy do Stromu dotarli znużeni posłowie z Quel\'Thalas, Thoradin zrozumiał, jak wielkie jest naprawdę zagrożenie ze strony trolli.', 0),
(1870, 'koKR', 'Elfy powiedziały Thoradinowi, że armie trolli są ogromne i że gdy trolle zniszczą Quel\'Thalas, ruszą na ziemie południowe. Zdesperowane elfy, rozpaczliwie potrzebujące wsparcia zbrojnego, pospiesznie zgodziły się nauczyć wybranych ludzi władania magią w zamian za pomoc w walce z hordami wojennymi.', 0),
(1871, 'koKR', 'Thoradin, nieufny wobec wszelkiej magii, z konieczności zgodził się pomóc elfom. Niemal natychmiast do Aratoru przybyli elfi czarodzieje i zaczęli uczyć grupę ludzi sztuki magii.', 0),
(1872, 'koKR', 'Elfy przekonały się, że choć ludzie z natury niezgrabnie obchodzą się z magią, mają do niej zdumiewający wrodzony dar. Stu mężczyzn nauczono samych podstaw magicznych sekretów elfów – nie więcej, niż było absolutnie konieczne do walki z trollami. Przekonane, że ich ludzcy uczniowie są gotowi pomóc w walce, elfy opuściły Strom i wyruszyły na północ wraz z potężnymi armiami króla Thoradina.', 0),
(1873, 'koKR', 'Zjednoczone armie elfów i ludzi starły się z przytłaczającymi trollowymi hordami wojennymi u stóp Gór Alterak. Bitwa trwała wiele dni, lecz niestrudzone armie Aratoru ani się nie zmęczyły, ani nie oddały piędzi ziemi przed natarciem trolli. Elfi władcy uznali, że nadszedł czas, by uwolnić przeciw wrogowi moc swojej magii.', 0),
(1874, 'koKR', 'Stu ludzkich magów i mnóstwo elfich czarodziejów sprowadziło gniew niebios i podpaliło armie trolli. Żywiołowe płomienie nie pozwalały trollom regenerować ran i wypalały ich umęczone ciała od środka.', 0),
(1875, 'koKR', 'Gdy armie trolli pękły i próbowały uciekać, wojska Thoradina ścigały je i wyrżnęły wszystkich co do jednego. Trolle nigdy w pełni nie podniosły się po tej klęsce, a historia już nigdy nie ujrzała ich zjednoczonych w jeden naród. Pewne, że Quel\'Thalas zostało ocalone przed zagładą, elfy przysięgły wierność i przyjaźń narodowi Aratoru oraz rodowi jego króla, Thoradina. Ludzie i elfy miały przez kolejne wieki pielęgnować pokojowe stosunki. $B', 0),
(1892, 'koKR', 'W dawnych czasach, gdy tytani opuścili Azeroth, ich dzieci, znane jako ziemni, nadal kształtowały i strzegły głębokich zakamarków świata. Ziemni niewiele interesowali się sprawami ras żyjących na powierzchni i pragnęli jedynie zgłębiać mroczne czeluści ziemi.', 0),
(1893, 'koKR', 'Gdy świat został rozdarty przez implozję Studni Wieczności, ziemni głęboko to odczuli. Oszołomieni bólem samej ziemi, utracili znaczną część swojej tożsamości i zamknęli się w kamiennych komnatach, w których niegdyś ich stworzono. Uldaman, Uldum, Ulduar... tak nazywały się pradawne miasta tytanów, w których ziemni po raz pierwszy przybrali kształt i postać. Pogrzebani głęboko pod światem, ziemni spoczywali w spokoju przez blisko osiem tysięcy lat.', 0),
(1894, 'koKR', 'Choć nie wiadomo, co ich obudziło, ziemni zamknięci w Uldamanie w końcu powstali z dobrowolnego snu. Odkryli, że podczas uśpienia bardzo się zmienili. Ich skaliste powłoki zmiękły i stały się gładką skórą, a ich władza nad kamieniem i ziemią osłabła. Stali się śmiertelnymi istotami.', 0),
(1895, 'koKR', 'Nazwawszy siebie krasnoludami, ostatni z ziemnych opuścili sale Uldamanu i wyruszyli w budzący się świat. Wciąż ukołysani bezpieczeństwem i cudami głębin, założyli rozległe królestwo pod najwyższą górą tej krainy.', 0),
(1896, 'koKR', 'Nazwali swoją krainę Khaz Modan, czyli „Górą Khaza”, na cześć tytanicznego kształtującego, Khaz\'gorotha. Wznosząc ołtarz dla swego tytanicznego ojca, krasnoludy zbudowały w sercu góry potężną kuźnię. Dlatego miasto, które wyrosło wokół niej, odtąd nazywano Żelazną Kuźnią.', 0),
(1897, 'koKR', 'Krasnoludy, z natury zafascynowane obróbką klejnotów i kamienia, zaczęły drążyć okoliczne góry w poszukiwaniu bogactw i cennych minerałów. Zadowolone ze swej pracy pod powierzchnią świata, trzymały się z dala od spraw sąsiadów żyjących na powierzchni.', 0),
(1951, 'koKR', 'Pod potajemną kontrolą Gul\'dana i jego Rady Cieni orkowie stawali się coraz agresywniejsi. Zbudowali ogromne areny, na których orkowie doskonalili umiejętności wojownicze w próbach walki i śmierci. W tym okresie kilku wodzów klanów zabrało głos przeciw rosnącemu zepsuciu swojej rasy.', 0),
(1952, 'koKR', 'Jeden z nich, Durotan z klanu Mroźnego Wilka, ostrzegał, by orkowie nie zatracili się w nienawiści i furii. Jego słowa trafiły jednak w próżnię, bo silniejsi wodzowie, tacy jak Grom Piekłorycz z klanu Wojennej Pieśni, wystąpili jako orędownicy nowej ery wojny i dominacji.', 0),
(1953, 'koKR', 'Kil\'jaeden wiedział, że klany orków są prawie gotowe, ale musiał mieć pewność co do ich ostatecznej lojalności. W tajemnicy kazał Radzie Cieni przyzwać Mannorotha Niszczyciela, żywe naczynie zniszczenia i gniewu. Gul\'dan zwołał wodzów klanów i przekonał ich, że wypicie szalejącej krwi Mannorotha uczyni ich całkowicie niezwyciężonymi.$B', 0),
(1954, 'koKR', ' Pod przewodem Groma Piekłorycza wszyscy wodzowie klanów z wyjątkiem Durotana wypili krew i przypieczętowali tym swój los niewolników Płonącego Legionu. Wzmocnieni gniewem Mannorotha, wodzowie nieświadomie rozciągnęli to zniewolenie na swoich niczego niepodejrzewających pobratymców.', 0),
(1955, 'koKR', 'Ogarnięci klątwą nowej żądzy krwi, orkowie pragnęli wyładować furię na każdym, kto stanął im na drodze. Czując, że nadszedł czas, Gul\'dan zjednoczył walczące ze sobą klany w jedną niepowstrzymaną Hordę.', 0),
(1956, 'koKR', 'Wiedząc jednak, że różni wodzowie, tacy jak Piekłorycz i Orgrim Zgładziciel, będą rywalizować o najwyższą władzę, Gul\'dan ustanowił marionetkowego wodza, który miał rządzić nową Hordą. Na marionetkę Gul\'dana wybrano Czarnorękiego Niszczyciela, wyjątkowo zdeprawowanego i okrutnego orczego wodza. Pod dowództwem Czarnorękiego Horda wyruszyła, by sprawdzić się w walce z prostodusznymi draenei.', 0),
(1957, 'koKR', 'W ciągu kilku miesięcy Horda wytępiła niemal wszystkich draenei żyjących na Draenorze. Tylko garstce rozproszonych ocalałych udało się ujść przed straszliwym gniewem orków. Upojony zwycięstwem Gul\'dan napawał się siłą i potęgą Hordy. Wiedział jednak, że bez wrogów, z którymi mogłaby walczyć, Horda wyniszczy się w nieustannych wewnętrznych walkach, pchana niepohamowanym głodem chwalebnej rzezi.', 0),
(1958, 'koKR', 'Kil\'jaeden wiedział, że Horda jest wreszcie gotowa. Orkowie stali się największą bronią Płonącego Legionu. Przebiegły demon podzielił się tą wiedzą ze swoim czekającym panem, a Sargeras uznał, że wreszcie nadszedł czas jego zemsty.', 0),
(2311, 'koKR', 'Ten nienaruszony szkielet pteradona wydobyto w odległym Kraterze Un\'Goro. Z budowy szkieletu jasno wynika, że tego rodzaju dotąd nie spotkano. Szkielet mógł przetrwać pod żyzną glebą tego regionu przez dowolnie wiele stuleci. $B', 0),
(2350, 'koKR', 'Ten nienaruszony szkielet pteradona wydobyto w odległym Kraterze Un\'Goro. Z budowy szkieletu jasno wynika, że tego rodzaju dotąd nie spotkano. Szkielet mógł przetrwać pod żyzną glebą tego regionu przez dowolnie wiele stuleci.', 0),
(2514, 'koKR', 'Poniżej lista uczniów, którzy w Szkole Górnictwa i Miernictwa Brocka uzyskali ocenę Platynowa Gwiazda, zdobywając tym samym Honorowy kilof górnika:$b$bMelia Kamieniotrzęs$bBardin Ironband$bUmi Pstrykowolt$bRumi Pstrykowolt$bVorel Stalogrot', 0),
(2571, 'koKR', 'Zimowa Uczta$B$BPóźne pory roku w Azeroth są w wielu kulturach czasem przemian. Zwłaszcza krasnoludy i taureni świętują, sięgając do legendy o nadchodzącej Zimowej Zasłonie – okryciu ziemi śniegiem, które zwiastuje czas odnowy. Choć rasy Azeroth rozumieją wspólne legendy dość podobnie, sposoby ich obchodzenia są równie różnorodne jak same rasy.', 0),
(2572, 'koKR', 'Legenda o Praojcu Mrozie$B$BNazwa „Zimowa Uczta” wywodzi się podobno od nadprzyrodzonej istoty, którą w wielu kulturach nazywa się Praojcem Mrozem. Gdy późną porą roku przemierzał krainy, sama zima była jego powiewającym płaszczem. Za nim ziemię okrywał śnieg – i dlatego mówi się, że Praojciec Mróz narzucał na krainę swoją zimową zasłonę. Choć część Azeroth może leżeć pod śniegiem, daje to ziemi czas na odrodzenie i odnowę.', 0),
(2573, 'koKR', 'Krasnoludy$B$BZawsze pochłonięte badaniem swojego pochodzenia, krasnoludy obchodzą tę porę roku jako hołd dla samego Praojca Mroza. Uważają go za uosobienie jednej z pradawnych istot Azeroth – tytanów. Podobnie jak w tym czy innym stopniu wywodzą swój ród od tych mistycznych istot, uważają swój śnieżny dom, Dun Morogh, za najlepszy przykład błogosławieństw Praojca Mroza.', 0),
(2574, 'koKR', 'Taureni$B$BSzamańskie pojmowanie zimy przez taurenów, a także ich niedawne zwrócenie się ku druidyzmowi dobrze współgrają z legendą o Zimowej Uczcie. Skupiają się jednak niemal wyłącznie na odnawiającym aspekcie tej tradycji, pozostawiając oddawanie czci legendom rasom (jak je postrzegają) mniej zestrojonym z naturą rzeczy. Wielu taurenów uważa ten czas za właściwy, by podziękować za błogosławieństwa nowego domu w Mulgorze.', 0),
(2575, 'koKR', 'Ucztowanie$B$BZwyczaj ucztowania o tej porze roku wywodzi się z samej legendy. Gdy Praojciec Mróz przemierzał Azeroth, niosąc za sobą zimę, obdarowywał podobno obfitością tych, którzy witali go z radością. Dlatego ucztowanie w czasie Zimowej Uczty jednoczyło społeczności, które dzieliły się wszystkim, co miały. Zazwyczaj zmianę witał jeden dzień zabawy i ucztowania – wszystko w oczekiwaniu na odnowę ziemi.', 0),
(2576, 'koKR', 'Współczesne obchody$B$BInne kultury również zaczęły uznawać Zimową Ucztę za czas wielkiego świętowania, choć nie według tradycji, na których opiera się legenda. Do współczesnych obchodów tej pory roku przeniknęły zwyczaje często niezwiązane z niczym poza okazją do zabawy i wymiany prezentów. Czasem używa się nawet wizerunku Praojca Mroza, ale bardziej jako zwiastuna handlowego zarobku niż nadprzyrodzonego tytana.', 0),
(2786, 'koKR', 'Turniej wędkarski w Cierniodławach!$BNiedzielne popołudnie – od 14 do 16.$B$BŁów gdziekolwiek na wybrzeżu Cierniodławów (z wyjątkiem Łupieżczej Zatoki) i wypatruj ławic smakorybów, które pojawią się wzdłuż brzegu! Dopilnuj, by twój spławik wylądował w ławicy, a zamiast zwykłych ryb z Cierniodławów złowisz ryby wyjątkowe. Pierwsza osoba, która złowi czterdzieści smakorybów, może je oddać mistrzowi wędkarskiemu Okoniowej Przynęcie w Łupieżczej Zatoce i odebrać nagrodę!$B$BNawet jeśli nie złowisz czterdziestu smakorybów jako pierwsza osoba, wciąż możesz je wymienić na gotówkę, a do złowienia są też wyjątkowe ryby, za które czekają specjalne nagrody!$B', 0),
(2787, 'koKR', 'Imię jego niosło Światłość w najmroczniejsze strony Azeroth.$B$BMęstwo jego zburzyło mury niedoli.$B$BSrebrna Dłoń nie mogła uczynić nic lepszego,$B$Bniż dać światu rycerza, co siebie samego dał w ofierze.', 0),
(2788, 'koKR', 'Nie o sławę zabiegał, by ją pomnażać,$B$Bani o władzę nad własnym ludem.$B$BWolał stanąć do walki za Lordaeron$B$Bw nadziei, że jego bliscy nie będą już musieli walczyć.', 0),
(2789, 'koKR', 'Tragiczna opowieść o tym najświętszym z rycerzy$B$Bnie skończy się nigdy wraz z jego nieświętą śmiercią.$B$BCzcimy go i składamy mu dzięki!$B$BUther na zawsze zazna chwały i Światłości!', 0),
(2841, 'koKR', 'W imieniu Wędzonych Pastwisk jeszcze raz dziękujemy, że się tym zajmujesz. Nie jesteśmy pewni, która grupa ma Metzena, ale zbadanie którejkolwiek będzie dobrym początkiem!$B$BCzas to pieniądz, $gprzyjacielu:przyjaciółko;, a my mamy go w tej sprawie bardzo, bardzo mało. Spiesz się z ratunkiem, bo nie wolno lekceważyć tego, do czego te grupy są zdolne.$B$BTak czy inaczej, na dwóch następnych stronach są listy z żądaniem okupu, które otrzymaliśmy. Powodzenia...', 0),
(2842, 'koKR', 'Jeśli chcecie odzyskać renifera żywego, to pospieszycie się z okupem. Piraci z Południowych Mórz nie lubią zwłoki w zapłacie, a my dobrze wiemy, ile ta bestia jest warta dla WASZEJ odmiany piractwa.$B$BPrzynieście 1000 sztuk złota do wejścia do Zatoczki Zaginionego Takielarza w Tanaris. Każda próba odbicia renifera skończy się tym, że Metzen pójdzie na bardzo długi spacer po bardzo krótkiej desce.$B$BJarrr...$B$BPiraci z Południowych Mórz', 0),
(2843, 'koKR', 'Wasz ukochany pupil nie czuje się najlepiej w bezlitosnym upale Płonącego Wąwozu... mądrze zrobicie, spełniając nasze żądania bez zwłoki.$B$BPrzyniesiecie nam pięć gwiezdnych rubinów i 700 sztuk złota – jedno i drugie włóżcie do jednej zwykłej paczki bez żadnych oznaczeń. W ciągu tygodnia zostawcie paczkę u bram Przełęczy Kamiennej Tamy.$B$BJeśli nie spełnicie naszych żądań, Metzen zostanie daniem głównym tradycyjnej uczty krasnoludów Czarnorytych na Zimową Ucztę.$B$BMmmm... renifer...', 0),
(2844, 'koKR', 'Szybciej niż orły zaprzęg jego gnał,$B$Ba on gwizdał, pokrzykiwał i po imieniu ich zwał:$B$B„Dalej, Mercer! Dalej, Chilton! Dalej, Jordan i Kaplan!$B$BNaprzód, Nagle! Naprzód, Pardo! Naprzód, Goodman i Metzen!$B$BNa sam szczyt ganku! Na sam muru szczyt!$B$BA teraz w drogę! W drogę! Wszyscy w mig!”$B', 0);
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES
(1839, 'koKR', '', 'Ach... no tak, no tak. To idź. Idź na spotkanie śmierci.', '', '', '', '', '', '', '', '', '', '', '', '', '', ''),
(8077, 'koKR', 'Gdy posypujesz Metzena pyłem, jego oczy rozbłyskują reniferową radością. Potrząsa ku tobie porożem i wydaje ciężkie westchnienie, które brzmi jak ulga.$B$BWokół ciebie zaczyna wzbierać magiczna energia. Wygląda na to, że zaraz coś się wydarzy!', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '');
INSERT INTO `gossip_menu_option_locale` (`MenuID`, `OptionID`, `Locale`, `OptionText`, `BoxText`) VALUES
(6763, 0, 'koKR', 'Posyp Metzena odrobiną reniferowego pyłu.', ''),
(50000, 0, 'koKR', 'Otwórz, proszę, bramę, muszę się dostać do Płonącego Wąwozu.', ''),
(50000, 1, 'koKR', 'Eee... Kamyczku... brama jest otwarta.', ''),
(50001, 0, 'koKR', 'Ale ja muszę się tam dostać, więc otwieraj bramę!', ''),
(50002, 0, 'koKR', 'Dobra, to jaka jest ta inna droga?', ''),
(50003, 0, 'koKR', 'Nieważne, jestem $gniewrażliwy:niewrażliwa;!', ''),
(50004, 0, 'koKR', 'Tak...', ''),
(50005, 0, 'koKR', 'Dobrze, postaram się to zapamiętać.', ''),
(50006, 0, 'koKR', 'Klucz? Dobra!', '');
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES
(9019, 0, 0, 'koKR', 'Na pomoc Tronowi!');
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(629, 'koKR', 'Założę się, że to kolejni agenci Syndykatu! Nigdy nie odbierzecie Alterak... ani Południowego Brzegu!', '', 0),
(792, 'koKR', '', '%s czyta list Sully\'ego strona po stronie.', 0),
(793, 'koKR', '', 'To niesprawiedliwe! Mój najdroższy Sully! Wróć do mnie! Nie, $n! Czemu $gprzyniosłeś:przyniosłaś; mi takie wieści!', 0),
(860, 'koKR', '%s uważnie czyta liścik Sary Balloo i wydaje z siebie długie, ciężkie westchnienie.', '', 0),
(870, 'koKR', '%s zaczyna przetrząsać swój plecak...', '', 0),
(871, 'koKR', 'Ach! Jest i mój klucz z zapadką! No to przymocujmy z powrotem te fragmenty zwoju.', '', 0),
(872, 'koKR', 'No i proszę, $n. Zwój naprawiony! Hurra!', '', 0),
(914, 'koKR', '%s czyta starożytny tekst, który $n mu $gprzyniósł:przyniosła;...', '', 0),
(915, 'koKR', 'Aha! To jest to!', '', 0),
(919, 'koKR', '%s chowa przedmioty, które $n mu $gdał:dała;.', '', 0),
(920, 'koKR', 'Dziękuję ci, $n. Moi wspólnicy zdziałają z tym wielkie rzeczy...', '', 0),
(921, 'koKR', '%s przyjmuje relikwie, które $gprzyniósł:przyniosła; $n.', '', 0),
(922, 'koKR', 'Przyjmij moje podziękowania, $n. Dziennik Yagyina będzie twój.', '', 0),
(923, 'koKR', '%s przykuca i zabiera się do czytania Kompendium Yagyina...', '', 0),
(924, 'koKR', '%s obrywa wyzwoloną magią!', '', 0),
(934, 'koKR', 'Au. Ostre.', '', 0),
(956, 'koKR', 'Ragnaros? To doprawdy straszne wieści...', '', 0),
(958, 'koKR', '$GSłyszałeś:Słyszałaś; go, $gwędrowcze:wędrowczyni;. Porozmawiaj ze mną znowu, gdy będziesz $ggotów:gotowa; rozmawiać z Belgrumem.', '', 0),
(1217, 'koKR', '%s obrywa wyzwoloną magią!', '', 0),
(2304, 'koKR', '$n! Skończyłem!', '', 0),
(3267, 'koKR', 'Opowiedz mi więcej o wykuwaniu zbroi.', 'Opowiedz mi więcej o wykuwaniu zbroi.', 0),
(3269, 'koKR', 'Możesz mi wskazać drogę?', 'Możesz mi wskazać drogę?', 0),
(3271, 'koKR', 'Opowiedz mi więcej o wykuwaniu broni.', 'Opowiedz mi więcej o wykuwaniu broni.', 0),
(3283, 'koKR', 'Ładna forma, $n. Stawiam pełny kufel w Kąciku Bruuka, że w użyciu jest równie solidna. Wiesz co, pogadaj z Myolorem Łamigniewem. On cię nakieruje.', '', 0),
(3284, 'koKR', 'Pewnie, że mogę ci pokazać, gdzie jest Myolor. O tam, przy kowadle Wielkiej Kuźni, tam właśnie pracuje. Słuchaj go uważnie, $gchłopcze:dziewczyno;, Myolor to mistrz, jakich mało.', '', 0),
(3285, 'koKR', 'Masz moje uznanie, $n. Kujesz ostrza lepiej niż ktokolwiek, kogo szkoliłem od lat. Ale jeśli chcesz zrobić prawdziwą broń, musisz pogadać z Myolorem Łamigniewem. Ten krasnolud skieruje cię na właściwą drogę.', '', 0),
(3286, 'koKR', 'Idziesz do Myolora, co? Jest o tam... za tobą! Eee, może przed tobą! Przy Wielkim Kowadle!', '', 0),
(3290, 'koKR', 'Z tym mi głowę zawracasz? Już lepiej przywiązać sobie do pleców zdechłego królika i przebiec przez legowisko trolli, niż nosić ten szmelc.', '', 0),
(3416, 'koKR', 'Mam nadzieję, że nie $gprzyszedłeś:przyszłaś; aż do Wielkiej Kuźni tylko po to, żeby się ogrzać. Mów śmiało, $gchłopcze:dziewczyno;, co mogę dla ciebie zrobić?', '', 0),
(3501, 'koKR', 'Zaraz biorę się do roboty, $n!', '', 0),
(3502, 'koKR', 'Proszę bardzo! Król powinien być całkiem zadowolony, jeśli wolno mi tak powiedzieć.', '', 0),
(3503, 'koKR', 'Straż królewska powinna wkrótce przyjść po pomnik. Tymczasem chodź ze mną na górę i dokończmy naszą małą pogawędkę, $n.', '', 0),
(3979, 'koKR', 'Witaj z powrotem w Wielkiej Kuźni, $n. $GPrzyszedłeś:Przyszłaś; odwiedzić starego krasnoluda czy myślisz, że czas na kolejny etap twojego szkolenia?', '', 0),
(4019, 'koKR', '', 'Soczyste owoce na sprzedaż!', 0),
(4020, 'koKR', '', 'Zatop zęby w świeżym, dojrzałym jabłku.', 0),
(4021, 'koKR', '', 'Prosto z bujnych lasów Elwynn – świeże owoce tylko tutaj!', 0),
(4265, 'koKR', '', 'Nie chcę tego słuchać, $n. Nie, nie ma mowy, żebym cię wpuściła do Płonącego Wąwozu. Niemożliwe. Nic z tego. Ile razy mam ci powtarzać – nie mogę cię wpuścić! Nie rozumiesz wspólnej mowy? Jesteś przebranym orkiem? N-I-E. NIE!$B$BJeśli wpuszczę ciebie, będę musiała wpuścić wszystkich. Zaraz twoi bliscy przyjaciele też będą chcieli wejść, potem ich dalecy krewni, potem ich przyjaciele i tak dalej, i tak dalej. Ostatnim razem, kiedy do tego doszło... cóż, nie będziemy mówić o ostatnim razie.', 0),
(4267, 'koKR', '', '$GOszalałeś:Oszalałaś;? Wiesz, jakie bestie zamieszkują to miejsce? Najgorsze, co może się zdarzyć, to że będziemy zgarniać twoje szczątki łopatą. Straciliśmy już przez te okropne potwory paru dobrych krasnoludów.$B$BWięc odpowiedź brzmi: nie. Jeśli koniecznie chcesz się dostać do Płonącego Wąwozu, musisz znaleźć inną drogę.', 0),
(4269, 'koKR', '', 'Nie powinnam ci nawet tego mówić, ale jeśli zdołasz się przedrzeć przez wszystkie stwory i bestie na Bezludziu, może uda ci się dotrzeć do Płonącego Wąwozu.$B$BTak, przez Bezludzie. Orkowie wybrukowali tam jakąś boczną drogę w pobliżu Kargatu. To tylko pokazuje, z jakimi głupcami mamy do czynienia! Tylne drzwi do piekła? Co oni sobie myśleli?', 0),
(4271, 'koKR', '', '$GNiewrażliwy:Niewrażliwa;?', 0),
(4273, 'koKR', '', 'Nie bądź głupcem i posłuchaj moich ostrzeżeń. Nikt nie jest niewrażliwy. Mądrze zrobisz, jeśli zapamiętasz tę radę.', 0),
(4275, 'koKR', '', 'Wiesz co? Skoro uważasz się za bohatera, to jeśli zdołasz przedostać się przez Bezludzie do Płonącego Wąwozu i przyniesiesz mi coś na dowód swojego bohaterstwa, zobaczę, co da się zrobić, żebyś $gdostał:dostała; klucz.$B$BW najdalszym, południowo-wschodnim zakątku Płonącego Wąwozu mieszka dama prawie tak twarda jak ja – Margol Szaleniec. Może warto się temu przyjrzeć.', 0),
(4285, 'koKR', '%s odkurza podstawę artefaktu.', '', 0),
(4286, 'koKR', '%s skrupulatnie ogląda dużą wazę.', '', 0),
(4287, 'koKR', 'Biedny Dorius. Niech ja tylko dorwę tych Czarnorytych, a przysięgam...', '', 0),
(4305, 'koKR', 'Mam idealne miejsce na ten róg!', '', 0),
(4306, 'koKR', 'Trzymałem to miejsce na coś wyjątkowego. Chyba nic nie może być bardziej wyjątkowe niż to, $n.', '', 0),
(4307, 'koKR', 'No i proszę. Gotowe!', '', 0),
(4406, 'koKR', 'Czekałem na ciebie, $n. Dobrze, że ci się udało. Masz przesyłkę?', '', 0),
(4561, 'koKR', 'Straż!', 'Straż!', 0),
(4583, 'koKR', 'Straż!', 'Straż!', 0),
(4601, 'koKR', '', 'Witaj, $n. $GPrzyszedłeś:Przyszłaś; poznać historię Żelaznej Kuźni?', 0),
(4603, 'koKR', 'Jestem $ggotów:gotowa;, historyku Archesonusie.', 'Jestem $ggotów:gotowa;, historyku Archesonusie.', 0),
(4604, 'koKR', '', 'Setki lat temu wielkie miasto Thaurissan dumnie wznosiło się pośród bujnych ziem, które dziś są zrujnowanymi Płonącymi Stepami.$B$BThaurissan było domem narodu krasnoludów z klanu Czarnorytych, a w owym czasie trwała wojna domowa, która rozdzierała cały krasnoludzki naród.$B$BWidzisz, ten zakątek świata był niegdyś częścią Gór Rudej Grani – aż do dnia, w którym Thaurissan pochłonęła gigantyczna eksplozja. Miasto legło w gruzach, a okoliczne ziemie zamieniły się w pokryte popiołem pustkowie.\n', 0),
(4605, 'koKR', 'To tragiczne. Jak do tego doszło?', 'To tragiczne. Jak do tego doszło?', 0),
(4606, 'koKR', '', 'Nie wiemy.$B$BCi Czarnoryci, którzy przeżyli, schronili się we wnętrzu góry i zaczęli odbudowywać swoje miasto.$B$BZ popiołów Thaurissan powstały wtedy Iglica Czarnej Góry i nowy naród Czarnorytych. Dodatkowe umocnienia wzniesiono w Płonącym Wąwozie, w miejscu zwanym Kotłem.$B$BZaczęły krążyć opowieści o pradawnym złu, które rządziło królestwem Czarnorytych.', 0),
(4607, 'koKR', 'Ciekawe, proszę, mów dalej.', 'Ciekawe, proszę, mów dalej.', 0),
(4608, 'koKR', '', 'Ostatnio Czarnorytych coraz częściej widuje się na powierzchni. Na Bezludziu wznieśli fortece. Wielkie siły zwiadowcze wysłali w głębiny Uldamanu na poszukiwanie pradawnej wiedzy. Najechali nawet naszą ojczyznę i uderzyli na naszą tamę nad jeziorem.', 0),
(4609, 'koKR', 'Niewiarygodne! Jak oni śmią?!', 'Niewiarygodne! Jak oni śmią?!', 0),
(4610, 'koKR', '', 'Potrzebujemy poszukiwaczy przygód, $n. Pomożesz nam?', 0),
(4611, 'koKR', 'Oczywiście, że pomogę!', 'Oczywiście, że pomogę!', 0),
(4674, 'koKR', 'Kocham placek.', 'Kocham placek.', 0),
(4675, 'koKR', 'Babcia zawsze mówiła, że nie ma na całym świecie nic lepszego niż ciepły, chrupiący kawałek świeżego, domowego placka wiśniowego.', 'Babcia zawsze mówiła, że nie ma na całym świecie nic lepszego niż ciepły, chrupiący kawałek świeżego, domowego placka wiśniowego.', 0),
(4677, 'koKR', 'Ten placek jest taki pyszny – chcesz trochę?', 'Ten placek jest taki pyszny – chcesz trochę?', 0),
(4678, 'koKR', 'Kiepski dzień? Spróbuj placka wiśniowego.', 'Kiepski dzień? Spróbuj placka wiśniowego.', 0),
(4680, 'koKR', 'Ten placek wiśniowy jest tak pyszny, że niejeden dorosły gnom by się rozpłakał.', 'Ten placek wiśniowy jest tak pyszny, że niejeden dorosły gnom by się rozpłakał.', 0),
(4681, 'koKR', 'Spróbuj tego placka wiśniowego, a uśmiechniesz się od ucha do ucha, i to na dziesięć mil.', 'Spróbuj tego placka wiśniowego, a uśmiechniesz się od ucha do ucha, i to na dziesięć mil.', 0),
(4682, 'koKR', 'Świeży placek wiśniowy na sprzedaż! Wygląda tak dobrze, że aż łza się w oku kręci.', 'Świeży placek wiśniowy na sprzedaż! Wygląda tak dobrze, że aż łza się w oku kręci.', 0),
(4684, 'koKR', 'Placek wiśniowy to moje najulubieńsze jedzenie w całym Azeroth.', 'Placek wiśniowy to moje najulubieńsze jedzenie w całym Azeroth.', 0),
(4723, 'koKR', 'Klucz... zdobądź klucz... Gerstahn ma... klucz.', '', 0),
(4724, 'koKR', 'Zrób wreszcie coś pożytecznego! WYCIĄGNIJ MNIE STĄD! Klucz ma wielka śledcza.', '', 0),
(4725, 'koKR', 'HEJ! HEJ, TY! $R! Wyciągnij mnie stąd!', '', 0),
(4726, 'koKR', '%s jęczy.', '', 0),
(4731, 'koKR', 'Miejmy to już za sobą, ty plugawa kreaturo.$B$B<Kharan pochyla głowę, odsłaniając krótki, gruby kark.>', '', 0),
(4732, 'koKR', 'Nie $gprzyszedłem:przyszłam; cię skrzywdzić, Kharanie. Przysłał mnie Gor\'shak. Powiedział, że opowiesz mi o księżniczce.', 'Nie $gprzyszedłem:przyszłam; cię skrzywdzić, Kharanie. Przysłał mnie Gor\'shak. Powiedział, że opowiesz mi o księżniczce.', 0),
(4733, 'koKR', 'Wszystko stracone...', '', 0),
(4734, 'koKR', 'Nie wszystko stracone, Kharanie!', 'Nie wszystko stracone, Kharanie!', 0),
(4735, 'koKR', 'Wyglądam ci na głupca? Równie dobrze mógłbym sam podpisać jej wyrok śmierci! Dlaczego miałbym ci ufać?\n', '', 0),
(4736, 'koKR', 'Bo wciąż żyjesz, a moje ręce nie zaciskają się na twoim krótkim, grubym karku.', 'Bo wciąż żyjesz, a moje ręce nie zaciskają się na twoim krótkim, grubym karku.', 0),
(4737, 'koKR', '<Kharan wzdycha.>$B$BChyba... chyba masz rację.$B$BGor\'shak powiedział mi, że twój wódz ma wielkie plany. Plany, które mogą zmienić stosunki między Przymierzem a Hordą. Co o tym wiesz?', '', 0),
(4738, 'koKR', 'Nic. Mam rozkaz porozmawiać z tobą, a potem z Thrallem. Wiem tylko tyle, że Thrallowi zależy na uratowaniu twojej księżniczki.\n', 'Nic. Mam rozkaz porozmawiać z tobą, a potem z Thrallem. Wiem tylko tyle, że Thrallowi zależy na uratowaniu twojej księżniczki.\n', 0),
(4739, 'koKR', 'W takim razie słuchaj uważnie.$B$BKilka miesięcy temu sędzia Jeziernych Włości wysłał posłańców do Żelaznej Kuźni, błagając króla o pomoc przeciw najazdom orków z Czarnej Skały, nadciągającym z Rudej Grani i Płonących Stepów.$B$BKsiężniczka Moira zgłosiła się na ochotnika, choć ją od tego odwodziłem. Przydzielono mi dwudziestu doborowych gwardzistów, którzy mieli chronić księżniczkę w niebezpiecznej podróży znad Loch do Jeziernych Włości.', '', 0),
(4740, 'koKR', 'Co by wyjaśniało, czemu siedzisz w celi na dnie góry, prawda, krasnoludzie?', 'Co by wyjaśniało, czemu siedzisz w celi na dnie góry, prawda, krasnoludzie?', 0),
(4741, 'koKR', '<Kharan odchrząkuje.>$B$BPrzeszliśmy tunelem do Płonącego Wąwozu i dalej, przez spustoszone pustkowie, jakim jest cały wąwóz. Z perspektywy czasu – panowała tam złowroga cisza. Jedynym zagrożeniem była miejscowa dzika zwierzyna: stworzenia, z którymi moi ludzie łatwo sobie radzili.$B$BDo Czarnej Góry dotarliśmy względnie łatwo i przeszliśmy przez jej kamienne budowle bez najmniejszych przeszkód.', '', 0),
(4742, 'koKR', 'I co się stało?', 'I co się stało?', 0),
(4743, 'koKR', 'Gdy przemierzaliśmy Płonące Stepy, wpadliśmy w zasadzkę. Musiała ich być setka... krasnoludy z klanu Czarnorytych! Wyłaniały się ze ścian, ze skał na Stepach; z każdej szczeliny, zakamarka i zaułka w zasięgu wzroku. Obległy nas, przytłoczyły strażników i tych kilku dzielnych bohaterów, którzy zgodzili się pomóc nam w tej misji.$B$BJedno było jasne: to była starannie zaplanowana zasadzka. Jakby znali każdy nasz ruch, zanim go wykonaliśmy...', '', 0),
(4744, 'koKR', 'Podejrzewasz więc, że maczał w tym palce ktoś od środka? Że ktoś ich uprzedził?', 'Podejrzewasz więc, że maczał w tym palce ktoś od środka? Że ktoś ich uprzedził?', 0),
(4745, 'koKR', 'Jak inaczej mogło do tego dojść? Ktoś musiał dać cynk Czarnorytym.$B$B<Kharan grozi ci pięścią.>$B$BPrzysięgam, jeśli kiedyś się stąd wydostanę, resztę swoich dni poświęcę na odnalezienie zdrajcy.', '', 0),
(4746, 'koKR', 'Proszę, opowiadaj dalej.', 'Proszę, opowiadaj dalej.', 0),
(4747, 'koKR', 'Na czym skończyłem? Ach tak, pojmano nas. Moich doborowych gwardzistów stracono na miejscu. Mnie oszczędzili, a księżniczkę wywieźli na baranie. Zabrano mnie do lochów Żużlowej Jamy, a potem przeniesiono do tego więzienia.$B$BMogę tylko przypuszczać, że żyję, bo chcą wyciągnąć okup za moje nędzne życie. A może z czystego okrucieństwa, żebym bez końca odtwarzał w myślach to, co się wydarzyło. Żal to najokrutniejszy ze strażników więziennych.', '', 0),
(4748, 'koKR', 'W rzeczy samej.', 'W rzeczy samej.', 0),
(4749, 'koKR', 'Teraz przebywa u boku imperatora Thaurissana. Trzyma ją pod wpływem jakiegoś potężnego zaklęcia, które odmienia myśli... a ja tu siedzę, zupełnie bezradny.\n', '', 0),
(4750, 'koKR', 'Jeśli to jakaś pociecha, zostawię drzwi celi otwarte. Jak się stąd wydostaniesz, to już twój problem. Żegnaj, Kharanie.\n', 'Jeśli to jakaś pociecha, zostawię drzwi celi otwarte. Jak się stąd wydostaniesz, to już twój problem. Żegnaj, Kharanie.\n', 0),
(5256, 'koKR', 'Mów dalej...', 'Mów dalej...', 0),
(5257, 'koKR', 'Drzwi są otwarte, Kharanie. Jesteś wolny.', 'Drzwi są otwarte, Kharanie. Jesteś wolny.', 0),
(5311, 'koKR', 'Dzięki, że pozbyliście się tych głupich senatorów. A teraz szykujcie się na zgubę z rąk najpotężniejszego sługi Ragnarosa.', '', 0),
(5312, 'koKR', 'Wasze wysiłki są zupełnie bezcelowe, głupcy! Nigdy mnie nie pokonacie!', '', 0),
(5313, 'koKR', 'I tak tylko przeszkadzali.', '', 0),
(5314, 'koKR', 'Ha! Nawet nie potraficie sobie wyobrazić, jak daremne są wasze wysiłki.', '', 0),
(5315, 'koKR', 'To wszystko, na co was stać? Naprawdę sądzicie, że zdołacie pokonać kogoś tak wspaniałego jak ja?', '', 0),
(5425, 'koKR', 'Niesamowite, prawda? Wszystkie te artefakty i szczątki.$B$BSam nie wiem, co mi bardziej imponuje – ich rozmiar czy opowieści, które się z nimi wiążą. Tyle jest do zbadania i poznania. A te powiązania, które możemy odkryć...$B$B$GWiedziałeś:Wiedziałaś;, że podobno wiele ras ma to samo dziedzictwo co nocne elfy?', '', 0),
(5429, 'koKR', '', '%s jest wyraźnie wstrząśnięta śmiercią imperatora Thaurissana.', 0),
(5431, 'koKR', 'Niech żyje król, maleńka!', '', 0),
(5447, 'koKR', 'Niesamowite! Zdumiewające! Nawet nie wiem, co to znaczy!', '', 0),
(5448, 'koKR', 'Spójrz na te próbki! Co to znaczy? Co to znaczy? Będę potrzebował czasu, czasu, żeby przejrzeć wszystkie te informacje. I będę potrzebował więcej informacji. Informacji, których nie mogę zdobyć... niech to! Myśl, Laris, myśl!$B$BCo teraz zrobisz? Co?!$B$BMusi być jakieś rozwiązanie!', '', 0),
(5449, 'koKR', 'Musi gdzieś w Azeroth być miejsce, gdzie znajdziemy szlamy nieskażone przez Plagę ani nic innego. Ale gdzie?!', '', 0),
(5450, 'koKR', 'Czy szlam czymś się różni od mazi?', 'Czy szlam czymś się różni od mazi?', 0),
(5451, 'koKR', 'Nie, nic mi o tym nie wiadomo. Zależy to chyba głównie od regionu. Jedne rasy nazywają je mazią, inne szlamem. To raczej kwestia upodobań.$B$BZa każdym razem, gdy trafiałem na szlam, muł czy maź, były to w zasadzie te same stworzenia. Różnice zdają się wynikać z ich otoczenia i dlatego potrzebujemy czystej próbki.', '', 0),
(5452, 'koKR', 'Co masz na myśli, mówiąc „czystej”?', 'Co masz na myśli, mówiąc „czystej”?', 0),
(5453, 'koKR', 'Czysta próbka to taka, której nie skaziły żadne niezamierzone wpływy. Musimy znaleźć te stworzenia w jak najbardziej pierwotnym, naturalnym środowisku.$B$BCzyli gdzieś z dala od cywilizacji i od wpływu dominujących ras Azeroth. W miejscu... nietkniętym.', '', 0),
(5454, 'koKR', 'Przychodzi ci do głowy jakieś miejsce, które byłoby aż tak nietknięte?', 'Przychodzi ci do głowy jakieś miejsce, które byłoby aż tak nietknięte?', 0),
(5455, 'koKR', 'Na pewno nie będzie to nigdzie we Wschodnich Królestwach, to pewne.$B$BTo musi być gdzieś w Kalimdorze, ale wciąż dość daleko od Hordy i innych ras. Miejsce, którego nie dotknął Rozłam – czyli też nigdzie w pobliżu cywilizacji nocnych elfów.$B$BZgaduję, że musiałoby być też jakoś osłonięte... jak dolina albo krater. Nie wiem. Teraz już tylko zgaduję. Przykro mi, że nie mogłem bardziej ci pomóc.', '', 0),
(5457, 'koKR', 'Zmiażdżę was na drobne kawałeczki!', '', 0),
(5536, 'koKR', 'Płyny i mieszaniny bulgoczą i drgają, gdy się zbliżasz. Obok aparatury leżą duże szczypce, które wyglądają na odpowiednie do wrzucania próbek szlamu.$B$BJest tu też sprzęt ochronny, ale jest zakurzony i najwyraźniej nikt go nie używa.$B$BWydaje ci się, że dotykanie czegokolwiek nie byłoby rozsądne.', '', 0),
(5727, 'koKR', 'Co? Nie mam czasu na pogaduszki, tata chce, żebym skończył dla niego to zamówienie.', '', 0),
(5783, 'koKR', 'Życie kowala nie jest łatwe, ale wkłada stal w kości i ogień w serce. Mój tata był kowalem, a przed nim mój dziadek, w kuźniach pod Grim Batol. A teraz mój syn idzie w nasze ślady – ten chłopak napawa mnie dumą.', '', 0),
(6475, 'koKR', 'Witaj, $n. Jestem Myolor Łamigniew, strażnik Wielkiej Kuźni.', '', 0),
(6503, 'koKR', 'Potrzebuję szkolenia.', 'Potrzebuję szkolenia.', 0),
(6653, 'koKR', 'I co się stało?', 'I co się stało?', 0),
(7144, 'koKR', 'Tak, tak. Widzę cię.$B$BRuszaj w drogę. Może i $gzdobyłeś:zdobyłaś; zaufanie paru osób, ale mnie trzeba czegoś więcej, żeby to udowodnić!', '', 0),
(7634, 'koKR', 'Z powodu niezgodności specyfikacji twojej klasy nie jestem w stanie pomóc ci w usunięciu jakichkolwiek braków w umiejętnościach.', 'Z powodu niezgodności specyfikacji twojej klasy nie jestem w stanie pomóc ci w usunięciu jakichkolwiek braków w umiejętnościach.', 0),
(7635, 'koKR', 'Doskonale! Spełniasz wymagane parametry i specyfikacje. Co mogę dla ciebie zrobić?', 'Doskonale! Spełniasz wymagane parametry i specyfikacje. Co mogę dla ciebie zrobić?', 0),
(7695, 'koKR', 'Nie daj się zwieść tym wielkim, niewinnym oczom. Tally to ekspertka, jak się patrzy: codziennie uczę się od niej czegoś nowego. A jak myślisz, czemu siedzę tu, w Majsterkowie? Wyglądam ci na inżyniera? No właśnie, tak myślałem.', '', 0),
(7718, 'koKR', '', 'Nie daj się zwieść tym paciorkowatym oczkom i krzaczastej brodzie. Vosur to zdolny uczeń i dobry przyjaciel, nawet jeśli strzyka mi w karku, kiedy z nim rozmawiam.', 0),
(7802, 'koKR', '', 'Słyszałam, że nowy Henweigh 6000 wkrótce zjedzie z linii montażowej. Ledwo mogę opanować ekscytację!', 0),
(7811, 'koKR', 'Co? Czegoś chcesz?', '', 0),
(7836, 'koKR', '', 'Plany mojej sześciometrowej strzykawki do polewania indyka są prawie gotowe! Teraz potrzebuję już tylko sześciometrowego indyka...', 0),
(7851, 'koKR', 'Jeśli moje obliczenia są poprawne, koło wkrótce stanie się przestarzałe!', '', 0),
(7871, 'koKR', 'Są sposoby, by wzmocnić stal nie tylko młotem i kuźnią, $gmłody wędrowcze:młoda wędrowczyni;.', '', 0),
(7889, 'koKR', 'Kim jesteś? Czego ode mnie chcesz?', '', 0),
(7958, 'koKR', '', 'Ta skóra jeszcze się nie nadaje do obróbki. Szkoda, że wyprawianie skóry trwa tak długo. Musi być jakiś sposób, żeby skrócić to całe czekanie. To nie może być dobre dla mojego zdrowia, wiesz?', 0),
(7999, 'koKR', 'Mnóstwo roboty! Nie miałem tyle pracy, odkąd mój kuzyn przypadkiem zamienił w parę całą tkaninę i skórę w Gnomoregan. Ojej, ależ potem przez jakiś czas wiało! Ach, $n, to były czasy...', '', 0),
(8068, 'koKR', 'Witaj w moim sklepie. Co mogę dla ciebie zrobić?', '', 0),
(8141, 'koKR', 'Ach, ta darnasyjska tkanina jest najlepsza!', '', 0),
(8209, 'koKR', 'Zapamiętaj moje słowa! Nigdzie we Wschodnich Królestwach nie znajdziesz szybszych gryfów niż tutaj, w Thelsamarze!', '', 0),
(8213, 'koKR', 'Jak dla mnie, nie ma lepszego fachu niż górnictwo. I jak dla mnie, nie ma lepszego górnika niż krasnolud!', '', 0),
(8217, 'koKR', 'Krasnoludy z klanu Dzikiego Młota mogą mieć szybkie wierzchowce, ale czy te ich gryfy z Orlego Gniazda wytrzymałyby żar Wielkiej Kuźni? Nie sądzę!', '', 0),
(8220, 'koKR', 'Najlepszy górnik mocno trzyma swój kilof, ma w piersi dzielne serce, a we włosach gęsty, czarny pył.', '', 0),
(8337, 'koKR', 'Potrzebuję szkolenia, Grimnurze.', 'Potrzebuję szkolenia, Grimnurze.', 0),
(8344, 'koKR', 'Może i mieliśmy suszę, ale mięsa nie brakuje! Chcesz obejrzeć moje towary?', '', 0),
(8345, 'koKR', 'Chcę obejrzeć twoje towary, Dirge.', 'Chcę obejrzeć twoje towary, Dirge.', 0),
(8348, 'koKR', 'To ja ich karmię, młody. Tak jest, Daryl Riknussun, do usług.', '', 0),
(8355, 'koKR', 'Żyję! Dziękuję, doktorze!', '', 0),
(8359, 'koKR', 'HURRA! ŻYJĘ!', '', 0),
(8361, 'koKR', 'Słodkie, słodkie objęcia... zabierzcie mnie...', '', 0),
(8881, 'koKR', 'Chcesz się szkolić we władaniu bronią, co? No to nie stój tak z rozdziawioną gębą, mów śmiało, $gchłopcze:dziewczyno;!', '', 0),
(8882, 'koKR', 'Jakiej broni chcesz się nauczyć?', '', 0),
(8883, 'koKR', '', 'No cześć! Chcesz poznać właściwą technikę władania nową bronią?', 0),
(8884, 'koKR', '', 'Oj, nie chcesz się szkolić ze mną? Jaka inna broń wpadła ci w oko?', 0),
(8956, 'koKR', 'Witaj w Lidze Odkrywców. Jeśli potrzebujesz informacji, a są one w formie książkowej, to może zdołam ci pomóc.', '', 0),
(8970, 'koKR', 'Dobrze cię znów widzieć, $gdoktorze:pani doktor; $n. Śledzę twoje postępy i śmiem twierdzić, że czas, abyś $gpoznał:poznała; bardziej zaawansowane techniki bandażowania.$B$BWracaj do mnie od czasu do czasu, w miarę jak twoja umiejętność będzie rosła, a nauczę cię wszystkiego, co wiem.', '', 0),
(8974, 'koKR', 'Witaj, $n. Jestem doktor Gustaf VanHowzen, naczelny chirurg urazowy Oddziału Urazowego Przymierza.', '', 0),
(9002, 'koKR', 'Witaj! Jestem porucznik Haggerdin, oficer odpowiedzialny za werbunek do Straży Gromdardy.$B$BGdy zdobędziesz prestiż i sławę w Straży Gromdardy, wróć do mnie, a zajmę się ulepszeniem twoich insygniów. A jeśli kiedyś zgubisz swoje insygnia, mogę wydać ci nowe.', '', 0),
(9010, 'koKR', 'Tak, wyglądasz na kogoś, kto nadaje się na przywódcę. Chcesz założyć gildię, żeby walczyć za Przymierze?', '', 0),
(9582, 'koKR', 'I co się stało?', 'I co się stało?', 0),
(9684, 'koKR', 'Odszukaj Shandrinę w Schronieniu Srebrnego Wiatru. Sprzeda ci „Książkę kucharską eksperta”.', 'Odszukaj Shandrinę w Schronieniu Srebrnego Wiatru. Sprzeda ci „Książkę kucharską eksperta”.', 0),
(9895, 'koKR', '', 'Hej, ty tam! Jeśli chcesz zdobyć szacunek krasnoludów z Żelaznej Kuźni, możesz zacząć od przekazania cennych zasobów! Żelaznej Kuźni kończą się zapasy tkanin; materiały i bandaże nie rosną na drzewach, wiesz?$B$BZamiast spieniężać różne kawałki tkanin znalezione podczas przygód, przekaż je nam! W ten sposób zyskasz uznanie krasnoludzkiego ludu Żelaznej Kuźni!', 0),
(9897, 'koKR', 'My, wygnańcy z Gnomoregan, jesteśmy w jeszcze gorszym położeniu, bo kończą nam się zapasy tkanin! Może nam pomożesz, co?!$B$BPrzynieś mi nadmiarowe kawałki tkanin, które masz, żebyśmy mogli uzupełnić zapasy. Przekazując je, zdobędziesz szacunek i zaufanie gnomów na całym świecie. A tego nie kupisz za pieniądze! No, w sumie za tkaninę kupisz, ale nie o to chodzi...', '', 0),
(10037, 'koKR', 'Tu wymienisz kupony! Zamień swoje kupony na nagrody! Podchodźcie śmiało!', '', 0),
(10105, 'koKR', 'Już jest! Festyn Lunomroku jest otwarty! Koniecznie zobacz najbardziej ekscytujące widowisko w całym Azeroth!', '', 0),
(10106, 'koKR', 'Festyn Lunomroku przyjechał do miasta! Koniecznie przeżyj najbardziej porywające widowisko, jakie kiedykolwiek zobaczysz!', '', 0),
(10107, 'koKR', 'Festyn Lunomroku potrwa tylko krótko, zanim opadnie kurtyna. Odwiedź go jeszcze dziś!', '', 0),
(10108, 'koKR', 'Chłopcy i dziewczęta – dzieci w każdym wieku – Festyn Lunomroku przybył! Hura!', '', 0),
(10110, 'koKR', 'Mówisz, że Festyn Lunomroku już przybył? Gdzie go znajdę?', 'Mówisz, że Festyn Lunomroku już przybył? Gdzie go znajdę?', 0),
(10112, 'koKR', 'Festyn Lunomroku rozbił się właśnie w Kniei Elwynn, tuż na południe od Złotych Włości. Nie przegap go!', '', 0),
(10429, 'koKR', 'Pokaż mi swój wybór fajerwerków.', 'Pokaż mi swój wybór fajerwerków.', 0),
(10430, 'koKR', 'Witaj, $N. Trwają Dożynki – czas wielkiej obfitości i czas pamięci. Zasiadamy do uczt, by świętować wszystko, za co możemy być wdzięczni, i wspominamy naszych przodków oraz dawnych bohaterów, by podziękować za dziedzictwo, które nam zostawili.$B$BŚmiało, częstuj się przygotowaną tu ucztą. Mam też na sprzedaż trochę fajerwerków, by uczcić tę radosną porę roku.', '', 0),
(10488, 'koKR', 'Jak dla mnie, najlepsze w wędkowaniu jest to niespieszne tempo. Daje czas, żeby pomyśleć, zastanowić się nad przeszłością i zaplanować przyszłość.$B$BA, i to też świetna wymówka, żeby wypić. Dużo.', '', 0),
(10489, 'koKR', 'Jeszcze raz dzięki za zwrot mojej szczęśliwej miarki, $n. Przysięgam, że dzięki niej łowię większe ryby!', '', 0),
(10490, 'koKR', 'Chcę złowić Gahz\'rankę! Powiedz mi jak!', 'Chcę złowić Gahz\'rankę! Powiedz mi jak!', 0),
(10491, 'koKR', 'Żeby złowić Gahz\'rankę, potrzebujesz specjalnej przynęty z błotnego skunksa. Robię je sam!$B$BAle sama przynęta nie wystarczy; potrzebujesz też kilku błotnych skunksów... trzeba je włożyć do przynęty, żeby nabrała porządnego smrodku!$B$BGdy już zdobędziesz błotne skunksy, zarzuć przynętę z Cypla Pagle\'a w Zul\'Gurub... a potem weź sobie coś do picia i czekaj... ale nie za długo, bo Gahz\'ranka na pewno przyjdzie, aż ziemia zadudni!', '', 0),
(10492, 'koKR', 'Nat, chcę kupić twoje przynęty z błotnego skunksa!', 'Nat, chcę kupić twoje przynęty z błotnego skunksa!', 0),
(10500, 'koKR', 'Jak złowić błotne skunksy do twojej przynęty?', 'Jak złowić błotne skunksy do twojej przynęty?', 0),
(10502, 'koKR', 'Błotne skunksy to wyjątkowo śmierdząca odmiana ryb, która lubi tropikalne wody. Zuliański błotny skunks – najbardziej śmierdzący ze wszystkich – żyje tylko w parnych wodach Zul\'Gurub.$B$BMyślę, że to właśnie zuliańskie błotne skunksy przyciągnęły tam Gahz\'rankę, choć trolle pewnie ci powiedzą, że to jeden z ich bogów...$B$BWierz, w co chcesz, ale zapamiętaj – napełnij jedną z moich przynęt zuliańskimi błotnymi skunksami, a ten staruszek na pewno przyjdzie!', '', 0),
(10524, 'koKR', '', '$N, potrzebujemy twojej pomocy w Wąwozie Wojennej Pieśni. Wesprzesz nas w walce z Konwojentami Wojennej Pieśni?', 0),
(10526, 'koKR', '$n, masz ty w ogóle pojęcie, z czym się mierzymy w Dolinie Alterak? $GGotów:Gotowa; do walki z Klanem Mroźnego Wilka?', '', 0),
(10595, 'koKR', 'Witaj, $gmistrzu:mistrzyni; wędki i kołowrotka! Jeśli chcesz zmierzyć się z najlepszymi wędkarzami w tych krainach, to słuchaj uważnie! W najbliższą niedzielę w Cierniodławach odbędą się zawody, które wyłonią mistrza wędkarstwa!\n', '', 0),
(10687, 'koKR', '', 'Pozdrawiam, $N. Witaj w Twierdzy Druidów. Stąd uderzymy na silithidy tam, gdzie są najsilniejsze. Mam nadzieję, że $gprzybyłeś:przybyłaś; nam pomóc.', 0),
(10756, 'koKR', 'Witaj, $N. Czy nie widziałem cię niedawno na pewnym ekskluzywnym zlocie? Wyglądasz znajomo, ale z drugiej strony to ruchliwe miasto.$B$BJeśli $gbyłeś:byłaś; na tym konwencie, na pewno $gdostałeś:dostałaś; sekretny kod. Podaj mi swój kod, a w zamian dam ci specjalną nagrodę.', 'Witaj, $N. Czy nie widziałem cię niedawno na pewnym ekskluzywnym zlocie? Wyglądasz znajomo, ale z drugiej strony to ruchliwe miasto.$B$BJeśli $gbyłeś:byłaś; na tym konwencie, na pewno $gdostałeś:dostałaś; sekretny kod. Podaj mi swój kod, a w zamian dam ci specjalną nagrodę.', 0),
(10786, 'koKR', 'Ko, ko, ko! Wesołych Zaduszników, $n!', '', 0),
(10798, 'koKR', 'Ko, ko, ko! Wesołych Zaduszników, $n!', '', 0),
(11386, 'koKR', 'Leży tu sterta zapakowanych prezentów.', '', 0),
(11415, 'koKR', 'Witaj, $N – jestem oficerem do spraw pochwał i działam w imieniu Darnassus. Moim obowiązkiem jest pomagać poszukiwaczom przygód, którzy otrzymali sygnety pochwalne Przymierza.$B$BPrzyjmuję sygnety w różnych ilościach, ale najkorzystniej dla ciebie będzie oddać od razu komplet dziesięciu. Gdy przekażesz mi sygnety, wpiszę twoje czyny do naszych rejestrów. Dzięki temu zyskasz uznanie Darnassus za swą służbę i poświęcenie.\n', 'Witaj, $N – jestem oficerem do spraw pochwał i działam w imieniu Darnassus. Moim obowiązkiem jest pomagać poszukiwaczom przygód, którzy otrzymali sygnety pochwalne Przymierza.$B$BPrzyjmuję sygnety w różnych ilościach, ale najkorzystniej dla ciebie będzie oddać od razu komplet dziesięciu. Gdy przekażesz mi sygnety, wpiszę twoje czyny do naszych rejestrów. Dzięki temu zyskasz uznanie Darnassus za swą służbę i poświęcenie.\n', 0),
(11416, 'koKR', 'Witaj, $N – jestem oficerem do spraw pochwał i działam w imieniu Wygnańców z Gnomoreganu. Moim obowiązkiem jest pomagać poszukiwaczom przygód, którzy otrzymali sygnety pochwalne Przymierza.$B$BPrzyjmuję sygnety w różnych ilościach, ale najkorzystniej dla ciebie będzie oddać od razu komplet dziesięciu. Gdy przekażesz mi sygnety, wpiszę twoje czyny do naszych rejestrów. Dzięki temu zyskasz uznanie Wygnańców z Gnomoreganu za swą służbę i poświęcenie.\n', 'Witaj, $N – jestem oficerem do spraw pochwał i działam w imieniu Wygnańców z Gnomoreganu. Moim obowiązkiem jest pomagać poszukiwaczom przygód, którzy otrzymali sygnety pochwalne Przymierza.$B$BPrzyjmuję sygnety w różnych ilościach, ale najkorzystniej dla ciebie będzie oddać od razu komplet dziesięciu. Gdy przekażesz mi sygnety, wpiszę twoje czyny do naszych rejestrów. Dzięki temu zyskasz uznanie Wygnańców z Gnomoreganu za swą służbę i poświęcenie.\n', 0),
(11417, 'koKR', 'Witaj, $N – jestem oficerem do spraw pochwał i działam w imieniu Żelaznej Kuźni. Moim obowiązkiem jest pomagać poszukiwaczom przygód, którzy otrzymali sygnety pochwalne Przymierza.$B$BPrzyjmuję sygnety w różnych ilościach, ale najkorzystniej dla ciebie będzie oddać od razu komplet dziesięciu. Gdy przekażesz mi sygnety, wpiszę twoje czyny do naszych rejestrów. Dzięki temu zyskasz uznanie Żelaznej Kuźni za swą służbę i poświęcenie.\n', 'Witaj, $N – jestem oficerem do spraw pochwał i działam w imieniu Żelaznej Kuźni. Moim obowiązkiem jest pomagać poszukiwaczom przygód, którzy otrzymali sygnety pochwalne Przymierza.$B$BPrzyjmuję sygnety w różnych ilościach, ale najkorzystniej dla ciebie będzie oddać od razu komplet dziesięciu. Gdy przekażesz mi sygnety, wpiszę twoje czyny do naszych rejestrów. Dzięki temu zyskasz uznanie Żelaznej Kuźni za swą służbę i poświęcenie.', 0),
(11430, 'koKR', 'Prezenty dla wszystkich! Praojciec Mróz położył pod drzewkiem podarunki dla każdego.', '', 0),
(11509, 'koKR', 'Gdzie jest Nestor Złotostudnia?', 'Gdzie jest Nestor Złotostudnia?', 0),
(11510, 'koKR', 'Nestor Złotostudnia przebywa w wiosce Kharanos w Dun Morogh.', 'Nestor Złotostudnia przebywa w wiosce Kharanos w Dun Morogh.', 0),
(11765, 'koKR', 'Chcę wpisać sekretny kod, żeby otrzymać mojego zwierzaka murloka.', 'Chcę wpisać sekretny kod, żeby otrzymać mojego zwierzaka murloka.', 0),
(11772, 'koKR', 'Widzisz mnie? Wiesz, jak bardzo jestem tu ignorowany tylko dlatego, że nikt mnie nie widzi? Jak miło mieć wreszcie z kim porozmawiać!$B$BWięc musiał cię przysłać jakiś żyjący członek mojej dawnej kompanii najemników, mam rację? Oczywiście, że mam!$B$BAle dość tych pogaduszek, czeka nas mnóstwo pracy, jeśli masz naprawić sprawy i zwrócić lordowi Valthalakowi jego ducha!', '', 0),
(11773, 'koKR', '$GZgubiłem:Zgubiłam; amulet lorda Valthalaka!', '$GZgubiłem:Zgubiłam; amulet lorda Valthalaka!', 0),
(11774, 'koKR', 'Ach, $n, nie płacz. Masz szczęście, bo kiedy ostatnio $gdałeś:dałaś; mi amulet, dostroiłem się do niego. Po prostu przyzwę go z powrotem, gdziekolwiek go $gupuściłeś:upuściłaś;.$B$BZajrzyj teraz do swoich toreb.', '', 0),
(11776, 'koKR', '$GZgubiłem:Zgubiłam; część amuletu lorda Valthalaka!', '$GZgubiłem:Zgubiłam; część amuletu lorda Valthalaka!', 0),
(11777, 'koKR', 'No już, już, $n, nie martw się! Którą część amuletu $gzapodziałeś:zapodziałaś;?$B$BA $gsprawdziłeś:sprawdziłaś; wszystkie torby i bank?', '', 0),
(11778, 'koKR', 'Tak, $gsprawdziłem:sprawdziłam;, brakuje mi górnej części!', 'Tak, $gsprawdziłem:sprawdziłam;, brakuje mi górnej części!', 0),
(11779, 'koKR', 'Bez obaw, Bodley zajmie się sprawą! Zobaczmy... ach tak... jest. Tylko ją przyzwę... i hokus-pokus!$B$BPostaraj się jej znowu nie zgubić, $n.', '', 0),
(11780, 'koKR', 'Tak, $gsprawdziłem:sprawdziłam;, brakuje mi lewej części!', 'Tak, $gsprawdziłem:sprawdziłam;, brakuje mi lewej części!', 0),
(11781, 'koKR', 'Tak, tak, uspokój się, $N, nie ma się czym martwić. Szczęśliwym trafem, kiedy pierwszy raz $gdałeś:dałaś; mi lewą część, dostroiłem się do niej, więc przyzwanie jej z powrotem z miejsca, gdzie ją „$gzapodziałeś:zapodziałaś;”, to naprawdę żaden problem.$B$BProszę, i tym razem lepiej jej pilnuj.', '', 0),
(11784, 'koKR', '$GZapodziałem:Zapodziałam; Kosz żarowy przywołania!', '$GZapodziałem:Zapodziałam; Kosz żarowy przywołania!', 0),
(11785, 'koKR', 'Żartujesz, prawda? Dobra, dobra, bez paniki. Na szczęście, kiedy nasycałem go składnikiem, który $gzdobyłeś:zdobyłaś;, też się do niego dostroiłem. Powinienem zdołać go namierzyć i przyzwać, gdziekolwiek go $gzostawiłeś:zostawiłaś;.$B$BNa pewno go $gzgubiłeś:zgubiłaś;? $GSprawdziłeś:Sprawdziłaś; wszystkie torby i bank?', '', 0),
(11786, 'koKR', 'Tak, proszę, przyzwij go z powrotem!', 'Tak, proszę, przyzwij go z powrotem!', 0),
(11787, 'koKR', 'Proszę bardzo, $n. Dobrze, że moje moce wieszczenia i przyzywania wciąż działają w tym widmowym stanie, co?', '', 0),
(11830, 'koKR', '$n! $GWróciłeś:Wróciłaś; tylko po to, żeby ze mną pogadać? To bardzo miłe z twojej strony, a do tego wyglądasz całkiem nieźle w tym stroju!$B$BNie wiesz, jak mi dobrze, kiedy cię widzę. Bywa tu dość samotnie, zwłaszcza że większość tych gamoni w ogóle mnie nie widzi. To wspaniałe, co dla nas wszystkich $gzrobiłeś:zrobiłaś;, i nigdy tego nie zapomnę!$B$BDzięki, że $gwpadłeś:wpadłaś; się przywitać, i nie znikaj na tak długo.', '', 0),
(11904, 'koKR', '', 'Staraj się nie zwracać na siebie zbytniej uwagi, czekam, aż Rada udzieli mi audiencji. Nie żeby mi przeszkadzało czekanie – przy tych wszystkich krzepkich strażnikach czuję się całkiem bezpiecznie.', 0),
(11906, 'koKR', 'Witaj, $gprzyjacielu:przyjaciółko;! Może zainteresują cię ektoplazmatyczne kondensatory? Albo porządny wielokierunkowy asymilator widmowy?', '', 0),
(11908, 'koKR', 'Chyba $gzapodziałem:zapodziałam; destylator, Mux. Czy przypadkiem nie $gzostawiłem:zostawiłam; go tutaj?', 'Chyba $gzapodziałem:zapodziałam; destylator, Mux. Czy przypadkiem nie $gzostawiłem:zostawiłam; go tutaj?', 0),
(11909, 'koKR', 'W sprawie tego wykrywacza duchów. Czy przypadkiem nie $gzostawiłem:zostawiłam; go tutaj? Chyba go $gzgubiłem:zgubiłam;.', 'W sprawie tego wykrywacza duchów. Czy przypadkiem nie $gzostawiłem:zostawiłam; go tutaj? Chyba go $gzgubiłem:zgubiłam;.', 0),
(11915, 'koKR', 'Bodley, powiedz mi, o co w tym wszystkim chodzi.', 'Bodley, powiedz mi, o co w tym wszystkim chodzi.', 0),
(11916, 'koKR', 'To naprawdę proste, $n. Moja dawna kompania najemników, Zawoalowane Ostrze, przyjęła niewłaściwe zlecenie w niewłaściwym czasie.$B$BWynajął nas goblin przemytnik z Łupieżczej Zatoki, niejaki Gremnik Rizzlesprang, który pożądał księgi zaklęć lorda Valthalaka. A może łączyła ich jakaś dawna rywalizacja? Chyba już się nie dowiemy, bo Gremnika zabiła niedawno grupa widmowych zabójców Valthalaka. Potrafią być naprawdę groźni, gdy zbierze się ich wielu.$B$BNa czym to skończyłem?', '', 0),
(11917, 'koKR', 'Opowiadałeś mi o Zawoalowanym Ostrzu i o tym, jak przyjęliście niewłaściwe zlecenie.', 'Opowiadałeś mi o Zawoalowanym Ostrzu i o tym, jak przyjęliście niewłaściwe zlecenie.', 0),
(11918, 'koKR', 'Ach tak, racja.$B$BWięc wdzieramy się głęboko w górne rejony Iglicy Czarnej Góry, przeciwko jej panu i przywódcy; to było jeszcze przed Drakkisatem. Niezbyt mądre, jak dla mnie, ale nasz przywódca, Anthion Harmon – $gpoznałeś:poznałaś; go – zawsze kochał wyzwania.$B$BO dziwo, wszystko szło zgodnie z planem, aż do chwili, gdy wyrywaliśmy księgę zaklęć Valthalaka z jego zesztywniałych palców. Wtedy wszystko się posypało.$B$BMam mówić dalej? Wyglądasz, jakby ci oczy zachodziły mgłą.', '', 0),
(11919, 'koKR', 'Nie, nie, proszę, mów dalej... po prostu powietrze jest tu takie, eee, zadymione.', 'Nie, nie, proszę, mów dalej... po prostu powietrze jest tu takie, eee, zadymione.', 0),
(11920, 'koKR', '<Bodley patrzy na ciebie z powątpiewaniem, ale mówi dalej...>$B$BStoimy więc z księgą zaklęć w ręku, a w czterech oczach Kormoka, naszego dwugłowego ogra nekromanty, pojawia się jakiś dziwny błysk. To było naprawdę upiorne, bo ta druga para oczu zawsze wyglądała jakoś martwo, jak u krowy, wiesz? I nagle Kormok po prostu wyciąga rękę i zrywa amulet, który nosił Valthalak.$B$BReszta kompanii oszalała; jedni krzyczeli, żeby go zostawił, inni chcieli go dla siebie.', '', 0),
(11921, 'koKR', 'Proszę, mów dalej, Bodley.', 'Proszę, mów dalej, Bodley.', 0),
(11922, 'koKR', 'Rany, nie musisz błagać! Zresztą już prawie kończę.$B$BCała kompania jest więc pośrodku tej ogromnej komnaty i bije się o ten amulet, a wiesz, jakie tam jest echo! W końcu rozpadł się na trzy części, a my rzuciliśmy kośćmi i trafiły do różnych osób albo grup.$B$BReszta to trochę mgła, bo mniej więcej wtedy duch starego Valthalaka postanowił się pojawić i zaczął przyzywać tych wszystkich widmowych zabójców.', '', 0),
(11923, 'koKR', '$GMyślałem:Myślałam;, że już prawie kończysz?', '$GMyślałem:Myślałam;, że już prawie kończysz?', 0),
(11924, 'koKR', 'Spokojnie!$B$B<Bodley mamrocze coś pod nosem o niecierpliwości żywych>$B$BJak mówiłem, duch lorda Valthalaka i widmowi zabójcy, przyzwani dzięki jego nekromanckim sztuczkom, zaczęli nas atakować. Mówię ci, w tamtej chwili nie byliśmy w stanie się bronić, więc uciekliśmy. Wciąż pamiętam, jak Mor Szare Kopyto, jeden z naszych druidów, w pewnym momencie poślizgnął się i spadł do niższych rejonów iglicy.$B$BReszta, jak to mówią, to już historia.', '', 0),
(11925, 'koKR', 'Co się stało z twoją kompanią najemników, Zawoalowanym Ostrzem?', 'Co się stało z twoją kompanią najemników, Zawoalowanym Ostrzem?', 0),
(11926, 'koKR', 'Potem się rozpadliśmy, ot co się stało. Za dużo złej krwi, chyba... narastała już od jakiegoś czasu. A sprawa z amuletem była tym ostatnim źdźbłem, pod którym pęka grzbiet kodo.$B$BOd tamtej pory słudzy Valthalaka wykańczają nas jednego po drugim. Większość posiadaczy części amuletu nie żyje, a ich dusze skaziła cząstka ducha Valthalaka, zamknięta w każdej z części.$B$BDlatego cieszę się, że tu jesteś, $n. Z twoją pomocą zdołamy złożyć amulet z powrotem i oddać go lordowi Valthalakowi!', '', 0),
(13601, 'koKR', '', '%s jęczy.', 0),
(14351, 'koKR', 'Tak, jestem jednym ze „Złamanych”. Ufam, że ci to nie przeszkadza? Złamani czy draenei – musimy znosić drwiny, którymi obrzucają nas niektórzy w naszej społeczności. Liczy się tylko lepsze zrozumienie żywiołów tego świata i porozumienie z nimi.', 'Tak, jestem jednym ze „Złamanych”. Ufam, że ci to nie przeszkadza? Złamani czy draenei – musimy znosić drwiny, którymi obrzucają nas niektórzy w naszej społeczności. Liczy się tylko lepsze zrozumienie żywiołów tego świata i porozumienie z nimi.', 0),
(16153, 'koKR', 'Festiwal Księżyca to dla nas wyjątkowy czas. Odszukujemy naszych pradawnych nestorów, ziemnych, i oddajemy im cześć.', 'Festiwal Księżyca to dla nas wyjątkowy czas. Odszukujemy naszych pradawnych nestorów, ziemnych, i oddajemy im cześć.', 0),
(16204, 'koKR', 'Co za wstyd! Ktoś wziął mnie za jednego z pomocników Praojca Mroza.', 'Co za wstyd! Ktoś wziął mnie za jednego z pomocników Praojca Mroza.', 0),
(16206, 'koKR', 'Festiwal Księżyca to najlepsza pora roku na fajerwerki!', 'Festiwal Księżyca to najlepsza pora roku na fajerwerki!', 0),
(16212, 'koKR', 'Praojca Mroza znajdziesz przed bankiem w Żelaznej Kuźni. Prezenty rozdaje się pod drzewkiem, które stoi obok niego.', 'Praojca Mroza znajdziesz przed bankiem w Żelaznej Kuźni. Prezenty rozdaje się pod drzewkiem, które stoi obok niego.', 0),
(16214, 'koKR', 'Idź do Dzielnicy Mistycznej w Żelaznej Kuźni i porozmawiaj z tamtejszymi druidami nocnych elfów. Mogą przenieść cię do Gaju Luny, żebyś $gmógł:mogła; wziąć udział w obchodach Festiwalu Księżyca.', 'Idź do Dzielnicy Mistycznej w Żelaznej Kuźni i porozmawiaj z tamtejszymi druidami nocnych elfów. Mogą przenieść cię do Gaju Luny, żebyś $gmógł:mogła; wziąć udział w obchodach Festiwalu Księżyca.', 0),
(19010, 'koKR', 'Chcę zapomnieć płatnerstwo!', 'Chcę zapomnieć płatnerstwo!', 0),
(20551, 'koKR', 'Bixi Trzęsibuch, tu, w tym sklepie, może cię wyszkolić w sztyletach. Jeśli szukasz gdzie indziej, to każdy z pozostałych – Woo Ping w Wichrogrodzie, Handiir w Exodarze i Ilyenia Księżycogień w Darnassus – może cię tego i owego nauczyć. Ja tam nigdy nie przepadałem za walką na noże.', 'Bixi Trzęsibuch, tu, w tym sklepie, może cię wyszkolić w sztyletach. Jeśli szukasz gdzie indziej, to każdy z pozostałych – Woo Ping w Wichrogrodzie, Handiir w Exodarze i Ilyenia Księżycogień w Darnassus – może cię tego i owego nauczyć. Ja tam nigdy nie przepadałem za walką na noże.', 0),
(20555, 'koKR', 'Buliwyf chętnie nauczy cię wszystkiego, co trzeba wiedzieć o broni palnej!', 'Buliwyf chętnie nauczy cię wszystkiego, co trzeba wiedzieć o broni palnej!', 0),
(20570, 'koKR', 'Nie znam lepszego znawcy toporów niż Buliwyf! Jednoręczne, dwuręczne... we wszystkich jest mistrzem!', 'Nie znam lepszego znawcy toporów niż Buliwyf! Jednoręczne, dwuręczne... we wszystkich jest mistrzem!', 0),
(20571, 'koKR', 'Mój kumpel Buliwyf może ci pokazać, jak się posługiwać bronią pięściową... albo, jeśli wolisz, Ilyenia Księżycogień – mistrzyni broni z rasy nocnych elfów na Tarasie Wojowników w Darnassus – też może cię tego nauczyć!', 'Mój kumpel Buliwyf może ci pokazać, jak się posługiwać bronią pięściową... albo, jeśli wolisz, Ilyenia Księżycogień – mistrzyni broni z rasy nocnych elfów na Tarasie Wojowników w Darnassus – też może cię tego nauczyć!', 0),
(20572, 'koKR', 'Moja dzielna towarzyszka Bixi Trzęsibuch może cię wyszkolić w kuszach. Ale jeśli szukasz innych nauczycieli, spróbuj u Ilyenii Księżycogień na Tarasie Wojowników w Darnassus albo u mistrza broni draenei, Handiira, na Tarasie Handlarzy w Exodarze.', '', 0),
(20573, 'koKR', 'Ilyenia Księżycogień, nocna elfka i mistrzyni broni, która mieszka na Tarasie Wojowników w Darnassus, może cię nauczyć posługiwania się łukiem.', 'Ilyenia Księżycogień, nocna elfka i mistrzyni broni, która mieszka na Tarasie Wojowników w Darnassus, może cię nauczyć posługiwania się łukiem.', 0),
(20575, 'koKR', 'Maczugi to specjalność Buliwyfa! Kręci się gdzieś po sklepie i zrzędzi. Jeśli jego metody szkolenia ci nie odpowiadają, słyszałam, że mistrz broni draenei w Exodarze, Handiir, też zna się na tej broni! Znajdziesz go na tamtejszym Tarasie Handlarzy.', 'Maczugi to specjalność Buliwyfa! Kręci się gdzieś po sklepie i zrzędzi. Jeśli jego metody szkolenia ci nie odpowiadają, słyszałam, że mistrz broni draenei w Exodarze, Handiir, też zna się na tej broni! Znajdziesz go na tamtejszym Tarasie Handlarzy.', 0),
(20576, 'koKR', 'Woo Ping to mistrz broni drzewcowej. Szkoli uczniów w Arsenale Wellera w Wichrogrodzie.', 'Woo Ping to mistrz broni drzewcowej. Szkoli uczniów w Arsenale Wellera w Wichrogrodzie.', 0),
(20577, 'koKR', 'Walki kosturem uczą zarówno Woo Ping, mistrz z Arsenału Wellera w Wichrogrodzie, jak i Ilyenia Księżycogień, która szkoli nocne elfy na Tarasie Wojowników w Darnassus.', 'Walki kosturem uczą zarówno Woo Ping, mistrz z Arsenału Wellera w Wichrogrodzie, jak i Ilyenia Księżycogień, która szkoli nocne elfy na Tarasie Wojowników w Darnassus.', 0),
(20578, 'koKR', 'Jest dwóch mistrzów miecza: Handiir i Woo Ping. Pierwszego znajdziesz na Tarasie Handlarzy w Exodarze, a drugiego w Arsenale Wellera w Wichrogrodzie.', 'Jest dwóch mistrzów miecza: Handiir i Woo Ping. Pierwszego znajdziesz na Tarasie Handlarzy w Exodarze, a drugiego w Arsenale Wellera w Wichrogrodzie.', 0),
